                                <div><div className="text-[9px] font-black text-gray-400 uppercase mb-1">{t.total}</div><div className="text-base font-black text-gray-900">{catTotal}</div></div>
                                <div><div className="text-[9px] font-black text-gray-400 uppercase mb-1">{t.progress}</div><div className={`text-base font-black ${activePeriod === 'five_year' ? 'text-purple-600' : (activePeriod === 'yearly' ? 'text-red-600' : 'text-indigo-600')}`}>{catProgress}%</div></div>
                            </div>

                            {/* Task List */}
                            <div className="flex-grow overflow-y-auto p-4 space-y-4 custom-scrollbar">
                                {cat.tasks.map((task) => {
                                    const taskProg = calculateTaskProgress(task);
                                    const isExpanded = expandedTaskId === task.id;
                                    const hasSteps = (task.subTasks || []).length > 0;

                                    return (
                                        <div key={task.id} className={`flex flex-col rounded-2xl border transition-all ${isExpanded ? `ring-2 ${activePeriod === 'five_year' ? 'ring-purple-200 border-purple-200' : 'ring-indigo-200 border-indigo-200'}` : 'border-gray-100 shadow-sm'} ${task.isCompleted ? 'bg-gray-50' : 'bg-white'}`}>
                                            <div className="flex items-start gap-3 p-3">
                                                <button 
                                                    onClick={() => toggleTask(cat.id, task.id)}
                                                    className={`w-5 h-5 rounded-lg border-2 flex items-center justify-center shrink-0 mt-0.5 transition-all ${task.isCompleted ? (activePeriod === 'five_year' ? 'bg-purple-600 border-purple-600' : 'bg-indigo-600 border-indigo-600') + ' text-white shadow-sm' : 'border-gray-200 bg-white hover:border-indigo-400'}`}
                                                >
                                                    {task.isCompleted && <IconCheck className="w-3 h-3" />}
                                                </button>

                                                <div className="flex-grow flex flex-col min-w-0" onClick={() => setExpandedTaskId(isExpanded ? null : task.id)}>
                                                    <span className={`text-[12px] font-black leading-tight cursor-pointer ${task.isCompleted ? 'text-gray-300 line-through' : 'text-gray-700'}`}>
                                                        {task.text}
                                                    </span>

                                                    {/* Goal Progress Bar */}
                                                    {(hasSteps || isExpanded) && (
                                                        <div className="mt-2 w-full">
                                                            <div className="flex justify-between items-center mb-1">
                                                                <span className={`text-[9px] font-black uppercase ${activePeriod === 'five_year' ? 'text-purple-400' : 'text-indigo-400'}`}>{t.progress}</span>
                                                                <span className={`text-[9px] font-black ${activePeriod === 'five_year' ? 'text-purple-600' : 'text-indigo-600'}`}>{taskProg}%</span>
                                                            </div>
                                                            <div className="w-full bg-gray-100 h-1 rounded-full overflow-hidden">
                                                                <div className={`h-full transition-all duration-700 ${taskProg === 100 ? 'bg-green-500' : (activePeriod === 'five_year' ? 'bg-purple-600' : 'bg-indigo-600')}`} style={{ width: `${taskProg}%` }}></div>
                                                            </div>
                                                        </div>
                                                    )}
                                                </div>

                                                <div className="flex flex-col gap-1 shrink-0 opacity-0 group-hover/col:opacity-100 transition-opacity">
                                                     <button onClick={() => setExpandedTaskId(isExpanded ? null : task.id)} className={`p-1.5 rounded-lg hover:bg-gray-100 text-gray-400 ${isExpanded ? (activePeriod === 'five_year' ? 'text-purple-600' : 'text-indigo-600') : ''}`} title={t.breakDown}>
                                                         <IconActivity className="w-3 h-3" />
                                                     </button>
                                                     <button onClick={() => removeTask(cat.id, task.id)} className="p-1.5 rounded-lg hover:bg-red-50 text-red-200 hover:text-red-500">
                                                         <IconTrash className="w-3 h-3" />
                                                     </button>
                                                </div>
                                            </div>

                                            {/* Sub-tasks / Break-down View */}
                                            {isExpanded && (
                                                <div className="px-3 pb-4 space-y-2 animate-slide-in">
                                                    <div className="h-px bg-gray-100 mx-2 mb-3"></div>
                                                    <div className={`space-y-2 pl-4 border-r-2 ${activePeriod === 'five_year' ? 'border-purple-50' : 'border-indigo-50'}`}>
                                                        {task.subTasks?.map(st => (
                                                            <div key={st.id} className="flex items-center gap-3 group/step">
                                                                <button 
                                                                    onClick={() => toggleSubTask(cat.id, task.id, st.id)}
                                                                    className={`w-4 h-4 rounded border flex items-center justify-center transition-all ${st.isCompleted ? (activePeriod === 'five_year' ? 'bg-purple-400 border-purple-400' : 'bg-indigo-400 border-indigo-400') + ' text-white' : 'border-gray-300 bg-white hover:border-indigo-200'}`}
                                                                >
                                                                    {st.isCompleted && <IconCheck className="w-2.5 h-2.5" />}
                                                                </button>
                                                                <span className={`text-[11px] font-bold flex-grow ${st.isCompleted ? 'text-gray-300 line-through' : 'text-gray-500'}`}>
                                                                    {st.text}
                                                                </span>
                                                                <button onClick={() => {
                                                                    const updated = task.subTasks?.filter(s => s.id !== st.id);
                                                                    const allDone = updated?.every(s => s.isCompleted) || false;
                                                                    const updatedCategories = currentUserGoals.categories.map(c => 
                                                                        c.id === cat.id ? { ...c, tasks: c.tasks.map(t => t.id === task.id ? { ...t, subTasks: updated, isCompleted: allDone } : t) } : c
                                                                    );
                                                                    const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
                                                                    setCurrentUserGoals(updatedGoals);
                                                                    saveUserGoals(updatedGoals);
                                                                }} className="text-red-200 hover:text-red-400 opacity-0 group-hover/step:opacity-100 transition-opacity">✕</button>
                                                            </div>
                                                        ))}
                                                        <input 
                                                            className="w-full bg-gray-50 border-none rounded-lg px-3 py-1.5 text-[10px] font-bold outline-none focus:ring-1 focus:ring-indigo-100"
                                                            placeholder={t.addSubTask}
                                                            onKeyDown={(e) => {
                                                                if (e.key === 'Enter') {
                                                                    handleAddSubTask(cat.id, task.id, (e.target as HTMLInputElement).value);
                                                                    (e.target as HTMLInputElement).value = '';
                                                                }
                                                            }}
                                                        />
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                                {cat.tasks.length === 0 && (
                                    <div className="h-full flex flex-col items-center justify-center text-center py-10 opacity-40">
                                        <div className="w-12 h-12 bg-gray-50 rounded-full flex items-center justify-center mb-2 border border-dashed border-gray-200">
                                            <IconTarget className="w-6 h-6 text-gray-200" />
                                        </div>
                                        <span className="text-[10px] font-black text-gray-300 uppercase tracking-widest">{t.empty}</span>
                                    </div>
                                )}
                            </div>

                            {/* Column Footer */}
                            {canEdit && (
                                <div className="p-4 border-t border-gray-50">
                                    <button 
                                        onClick={() => handleAddTask(cat.id)}
                                        className={`w-full py-2.5 rounded-2xl border-2 border-dashed border-gray-200 text-gray-400 font-black text-[11px] uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${activePeriod === 'five_year' ? 'hover:border-purple-300 hover:text-purple-600 hover:bg-purple-50' : 'hover:border-indigo-300 hover:text-indigo-600 hover:bg-indigo-50'}`}
                                    >
                                        <IconPlus className="w-4 h-4" /> {t.addGoal}
                                    </button>
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>

            <div className="text-center pt-8 border-t border-gray-100 print:hidden">
                <p className="text-[10px] font-black text-gray-300 uppercase tracking-widest">{t.smartNote}</p>
                <p className="text-[10px] font-bold text-gray-400 mt-2">{t.lastUpdate} {new Date(currentUserGoals?.lastUpdated || '').toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</p>
            </div>

            <style>{`
                .no-scrollbar::-webkit-scrollbar { display: none; }
                .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
                .custom-scrollbar::-webkit-scrollbar { width: 4px; height: 4px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
                @keyframes fade-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
                .animate-fade-in { animation: fade-in 0.4s ease-out forwards; }
                @keyframes slide-in { from { opacity: 0; transform: translateX(5px); } to { opacity: 1; transform: translateX(0); } }
                .animate-slide-in { animation: slide-in 0.2s ease-out forwards; }

                @media print {
                    @page { size: A4; margin: 0; }
                    body { background: white !important; margin: 0; padding: 0; }
                    #root > div > header, #root > div > footer, #root > div > nav, #root > div > .fixed, .print\\:hidden { display: none !important; }
                    main { padding: 0 !important; max-width: 100% !important; margin: 0 !important; }
                    .print\\:flex { display: flex !important; }
                    .print\\:block { display: block !important; }
                    .print\\:grid { display: grid !important; }

                    /* Ensure colors are printed */
                    * { -webkit-print-color-adjust: exact !important; color-adjust: exact !important; }

                    /* Force content to stay within A4 */
                    .print-container { height: 297mm; width: 210mm; }
                }
            `}</style>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconCalendar, IconChart, IconShield, IconBrain, IconArrowRight, IconActivity, IconBriefcase, IconUsers, IconPrinter, IconAward, IconTrendingUp, IconClock } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف کاری (Business)', color: 'bg-blue-50 border-blue-200 text-blue-700 header-blue', type: 'business' as const },
    { id: 'cat2', title: 'توسعه فردی (Personal)', color: 'bg-emerald-50 border-emerald-200 text-emerald-700 header-green', type: 'personal' as const },
    { id: 'cat3', title: 'سلامتی و لایف‌استایل', color: 'bg-orange-50 border-orange-200 text-orange-700 header-orange', type: 'personal' as const },
    { id: 'cat4', title: 'اهداف مالی', color: 'bg-purple-50 border-purple-200 text-purple-700 header-purple', type: 'personal' as const },
    { id: 'cat5', title: 'سایر موارد', color: 'bg-pink-50 border-pink-200 text-pink-700 header-pink', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [editingTitleId, setEditingTitleId] = useState<string | null>(null);
    const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

    const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');
    const canEdit = selectedUserId === currentUser.id;

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => {
            c.tasks.forEach(t => {
                total++;
                if (t.isCompleted) done++;
            });
        });
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const t = {
        fa: {
            title: 'ردیاب اهداف هوشمند',
            daily: 'امروز',
            weekly: 'هفتگی',
            monthly: 'ماهانه',
            yearly: 'سالانه',
            five_year: '۵ ساله',
            viewMode: 'درحال مشاهده:',
            business: 'اهداف کاری',
            personal: 'توسعه فردی',
            addGoal: 'افزودن هدف جدید',
            editTitle: 'ویرایش عنوان',
            saveTitle: 'ذخیره',
            done: 'انجام شد',
            total: 'کل',
            progress: 'پیشرفت',
            empty: 'هدفی ثبت نشده است.',
            masterView: 'مشاهده اهداف:',
            lastUpdate: 'آخرین بروزرسانی:',
            smartNote: 'اهداف باید هوشمند (SMART) باشند.',
            addSubTask: 'افزودن گام اجرایی...',
            breakDown: 'خرد کردن هدف',
            print: 'خروجی چاپ پوستر',
            reportTitle: 'برنامه راهبردی و اهداف بلندمدت',
            visionNote: 'رویاهای بزرگ داشته باشید، اما از قدم‌های کوچک شروع کنید.'
        },
        en: {
            title: 'SMART Goal Tracker',
            daily: 'Daily',
            weekly: 'Weekly',
            monthly: 'Monthly',
            yearly: 'Yearly',
            five_year: '5-Year',
            viewMode: 'Current View:',
            business: 'Business Goals',
            personal: 'Personal Development',
            addGoal: 'Add Goal',
            editTitle: 'Edit Title',
            saveTitle: 'Save',
            done: 'Done',
            total: 'Total',
            progress: 'Progress',
            empty: 'No goals set yet.',
            masterView: 'View Staff Goals:',
            lastUpdate: 'Last Updated:',
            smartNote: 'Specific, Measurable, Achievable, Relevant, Time-bound',
            addSubTask: 'Add step...',
            breakDown: 'Break down',
            print: 'Print Poster',
            reportTitle: 'Strategic Plan & Vision',
            visionNote: 'Dream big, but start small.'
        }
    }[lang];

    const selectedPerson = useMemo(() => personnel.find(p => p.id === selectedUserId), [personnel, selectedUserId]);

    const handleAddTask = (catId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const taskText = window.prompt(lang === 'fa' ? 'عنوان هدف را وارد کنید:' : 'Enter goal title:');
        if (!taskText) return;

        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: taskText, isCompleted: false, subTasks: [] }] };
            }
            return c;
        });

        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.map(t => {
                    if (t.id === taskId) {
                        const newCompleted = !t.isCompleted;
                        const updatedSubTasks = t.subTasks?.map(st => ({ ...st, isCompleted: newCompleted }));
                        return { ...t, isCompleted: newCompleted, subTasks: updatedSubTasks };
                    }
                    return t;
                })};
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleAddSubTask = (catId: string, taskId: string, text: string) => {
        if (!canEdit || !currentUserGoals || !text.trim()) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.map(t => {
                    if (t.id === taskId) {
                        const newSub: GoalSubTask = { id: `st-${Date.now()}`, text, isCompleted: false };
                        return { ...t, subTasks: [...(t.subTasks || []), newSub], isCompleted: false };
                    }
                    return t;
                })};
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleSubTask = (catId: string, taskId: string, subId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.map(t => {
                    if (t.id === taskId) {
                        const updatedSubTasks = t.subTasks?.map(st => st.id === subId ? { ...st, isCompleted: !st.isCompleted } : st);
                        const allDone = updatedSubTasks?.every(st => st.isCompleted) || false;
                        return { ...t, subTasks: updatedSubTasks, isCompleted: allDone };
                    }
                    return t;
                })};
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const removeTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals || !window.confirm('حذف هدف؟')) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.filter(t => t.id !== taskId) };
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleUpdateCategoryTitle = (catId: string, newTitle: string) => {
        if (!canEdit || !currentUserGoals || !newTitle.trim()) {
            setEditingTitleId(null);
            return;
        }
        const updatedCategories = currentUserGoals.categories.map(c => 
            c.id === catId ? { ...c, title: newTitle } : c
        );
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
        setEditingTitleId(null);
    };

    const calculateTaskProgress = (task: GoalTask) => {
        if (!task.subTasks || task.subTasks.length === 0) return task.isCompleted ? 100 : 0;
        const done = task.subTasks.filter(st => st.isCompleted).length;
        return Math.round((done / task.subTasks.length) * 100);
    };

    const handlePrint = () => {
        window.print();
    };

    if (isLoading) return <div className="p-8 text-center animate-pulse text-indigo-600 font-bold">در حال بارگذاری اهداف استراتژیک...</div>;

    const periodIcons: Record<string, React.ReactNode> = {
        daily: <IconClock className="w-4 h-4" />,
        weekly: <IconCalendar className="w-4 h-4" />,
        monthly: <IconActivity className="w-4 h-4" />,
        yearly: <IconAward className="w-4 h-4" />,
        five_year: <IconTrendingUp className="w-4 h-4" />
    };

    // Explicitly defining all 5 periods for the navigation
    const navItems = [
        { id: 'daily', activeColor: 'bg-blue-600 shadow-blue-100', hoverColor: 'hover:text-blue-600' },
        { id: 'weekly', activeColor: 'bg-green-600 shadow-green-100', hoverColor: 'hover:text-green-600' },
        { id: 'monthly', activeColor: 'bg-orange-600 shadow-orange-100', hoverColor: 'hover:text-orange-600' },
        { id: 'yearly', activeColor: 'bg-red-600 shadow-red-100', hoverColor: 'hover:text-red-600' },
        { id: 'five_year', activeColor: 'bg-purple-600 shadow-purple-100', hoverColor: 'hover:text-purple-600' }
    ];

    return (
        <div className="space-y-8 animate-fade-in pb-12">
            {/* Control Center */}
            <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-gray-100 flex flex-col lg:flex-row gap-8 items-center relative overflow-hidden print:hidden">
                <div className={`absolute top-0 right-0 w-48 h-48 rounded-bl-full -z-10 opacity-10 transition-colors duration-700 ${activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-red-600' : 'bg-indigo-600')}`}></div>

                <div className="shrink-0 w-full lg:w-1/3">
                    <h2 className="text-3xl font-black text-gray-900 mb-1 uppercase tracking-tight">{t.title}</h2>
                    <div className="flex items-center gap-2 mb-6">
                        <span className="text-xs font-bold text-gray-400">{t.viewMode}</span>
                        <span className={`px-2 py-0.5 rounded-lg text-[10px] font-black text-white ${navItems.find(n => n.id === activePeriod)?.activeColor.split(' ')[0]}`}>
                            {t[activePeriod as keyof typeof t.fa]}
                        </span>
                    </div>

                    {/* CORRECTED PERIOD SWITCHER (Grid Only) */}
                    <div className="bg-gray-100 p-1.5 rounded-2xl mb-6 grid grid-cols-5 gap-1.5 border border-gray-200 shadow-inner">
                        {navItems.map(btn => (
                            <button 
                                key={btn.id}
                                onClick={() => { setActivePeriod(btn.id as GoalPeriod); setExpandedTaskId(null); }}
                                className={`flex flex-col items-center justify-center py-3 rounded-xl transition-all duration-300 ${activePeriod === btn.id ? `${btn.activeColor} text-white shadow-lg scale-105 z-10` : `text-gray-500 ${btn.hoverColor} hover:bg-white`}`}
                            >
                                <div className="mb-1">{periodIcons[btn.id]}</div>
                                <span className="text-[9px] font-black uppercase whitespace-nowrap">{t[btn.id as keyof typeof t.fa]}</span>
                            </button>
                        ))}
                    </div>

                    <div className="flex flex-col gap-3">
                        {isMaster && (
                            <div className="space-y-1">
                                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-1">{t.masterView}</label>
                                <select 
                                    className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-100"
                                    value={selectedUserId}
                                    onChange={(e) => { setSelectedUserId(e.target.value); setExpandedTaskId(null); }}
                                >
                                    {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                                </select>
                            </div>
                        )}
                        <button 
                            onClick={handlePrint}
                            className={`w-full py-3.5 text-white rounded-2xl text-xs font-black flex items-center justify-center gap-2 transition-all shadow-lg border-b-4 active:border-b-0 active:translate-y-1 ${activePeriod === 'five_year' ? 'bg-purple-600 border-purple-800' : (activePeriod === 'yearly' ? 'bg-red-600 border-red-800' : 'bg-indigo-600 border-indigo-800')}`}
                        >
                            <IconPrinter className="w-4 h-4" /> {t.print}
                        </button>
                    </div>
                </div>

                {/* Overall Progress Gauge */}
                <div className="flex flex-col items-center gap-2 lg:border-r lg:px-10 border-gray-100">
                    <div className="relative w-36 h-36 flex items-center justify-center">
                        <svg className="w-full h-full transform -rotate-90">
                            <circle cx="72" cy="72" r="62" stroke="currentColor" strokeWidth="12" fill="transparent" className="text-gray-100" />
                            <circle cx="72" cy="72" r="62" stroke="currentColor" strokeWidth="12" fill="transparent" strokeDasharray={389.557} strokeDashoffset={389.557 - (stats.percent / 100) * 389.557} className={`transition-all duration-1000 ease-out ${activePeriod === 'five_year' ? 'text-purple-600' : (activePeriod === 'yearly' ? 'text-red-600' : 'text-indigo-600')}`} />
                        </svg>
                        <div className="absolute inset-0 flex flex-col items-center justify-center">
                            <span className="text-3xl font-black text-gray-900">{stats.percent}%</span>
                            <span className="text-[9px] font-black text-gray-400 uppercase tracking-tighter">{t.progress}</span>
                        </div>
                    </div>
                </div>

                {/* Categorical Breakdown */}
                <div className="flex-grow grid grid-cols-2 sm:grid-cols-3 gap-4 w-full">
                    {currentUserGoals?.categories.map(cat => {
                        const catTotal = cat.tasks.length;
                        const catDone = cat.tasks.filter(t => t.isCompleted).length;
                        const catProgress = catTotal > 0 ? Math.round((catDone / catTotal) * 100) : 0;
                        const catColor = cat.color.split(' ')[2].replace('text-', 'bg-');
                        return (
                            <div key={cat.id} className="bg-gray-50 p-4 rounded-3xl flex flex-col justify-center border border-gray-100 group hover:bg-white hover:shadow-md transition-all">
                                <div className="text-[9px] font-black text-gray-400 uppercase truncate mb-2">{cat.title}</div>
                                <div className="flex items-center justify-between gap-3">
                                    <div className="flex-grow bg-gray-200 h-2 rounded-full overflow-hidden">
                                        <div className={`h-full rounded-full transition-all duration-1000 ${catColor}`} style={{ width: `${catProgress}%` }}></div>
                                    </div>
                                    <span className="text-[11px] font-black text-gray-700">{catProgress}%</span>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* --- MAIN GRID (Task Board) --- */}
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-5 gap-6 print:hidden">
                {currentUserGoals?.categories.map((cat) => {
                    const catTotal = cat.tasks.length;
                    const catDone = cat.tasks.filter(t => t.isCompleted).length;
                    const catProgress = catTotal > 0 ? Math.round((catDone / catTotal) * 100) : 0;

                    const headerColors: any = {
                        'header-blue': 'bg-blue-500',
                        'header-pink': 'bg-pink-500',
                        'header-green': 'bg-emerald-500',
                        'header-orange': 'bg-orange-500',
                        'header-purple': 'bg-purple-500'
                    };
                    const hColor = headerColors[cat.color.split(' ').find(c => c.startsWith('header-')) || ''] || 'bg-indigo-500';

                    return (
                        <div key={cat.id} className={`bg-white rounded-[2.5rem] border border-gray-100 shadow-lg overflow-hidden flex flex-col min-h-[550px] group/col transition-all duration-500 ${activePeriod === 'five_year' ? 'ring-2 ring-purple-100 border-purple-200 shadow-purple-50' : (activePeriod === 'yearly' ? 'ring-2 ring-red-100 border-red-200 shadow-red-50' : '')}`}>
                            {/* Column Header */}
                            <div className={`${hColor} p-5 text-center text-white font-black text-xs uppercase tracking-widest relative`}>
                                {editingTitleId === cat.id ? (
                                    <input 
                                        autoFocus
                                        className="w-full bg-white/20 text-white placeholder-white/70 px-3 py-1.5 rounded-xl outline-none border border-white/30 text-center text-sm"
                                        defaultValue={cat.title}
                                        onBlur={(e) => handleUpdateCategoryTitle(cat.id, e.target.value)}
                                        onKeyDown={(e) => e.key === 'Enter' && handleUpdateCategoryTitle(cat.id, (e.target as HTMLInputElement).value)}
                                    />
                                ) : (
                                    <div className="flex items-center justify-center gap-2">
                                        {cat.type === 'business' ? <IconBriefcase className="w-4 h-4" /> : <IconUsers className="w-4 h-4" />}
                                        <span onClick={() => canEdit && setEditingTitleId(cat.id)} className={canEdit ? "cursor-pointer hover:underline" : ""}>
                                            {cat.title}
                                        </span>
                                        {canEdit && (
                                            <button onClick={() => setEditingTitleId(cat.id)} className="opacity-40 hover:opacity-100 transition-opacity">
                                                <IconEdit className="w-3.5 h-3.5" />
                                            </button>
                                        )}
                                    </div>
                                )}
                            </div>

                            {/* Category Stats */}
                            <div className="bg-gray-50/50 border-b border-gray-100 p-4 grid grid-cols-3 gap-2 text-center">
                                <div><div className="text-[8px] font-black text-gray-400 uppercase mb-1">{t.done}</div><div className="text-sm font-black text-gray-900">{catDone}</div></div>
                                <div><div className="text-[8px] font-black text-gray-400 uppercase mb-1">{t.total}</div><div className="text-sm font-black text-gray-900">{catTotal}</div></div>
                                <div><div className="text-[8px] font-black text-gray-400 uppercase mb-1">{t.progress}</div><div className={`text-sm font-black ${activePeriod === 'five_year' ? 'text-purple-600' : (activePeriod === 'yearly' ? 'text-red-600' : 'text-indigo-600')}`}>{catProgress}%</div></div>
                            </div>

                            {/* Task Items */}
                            <div className="flex-grow overflow-y-auto p-4 space-y-4 custom-scrollbar">
                                {cat.tasks.map((task) => {
                                    const taskProg = calculateTaskProgress(task);
                                    const isExpanded = expandedTaskId === task.id;
                                    const hasSteps = (task.subTasks || []).length > 0;

                                    return (
                                        <div key={task.id} className={`flex flex-col rounded-3xl border transition-all duration-300 ${isExpanded ? `ring-2 ${activePeriod === 'five_year' ? 'ring-purple-200 border-purple-200' : (activePeriod === 'yearly' ? 'ring-red-200 border-red-200' : 'ring-indigo-200 border-indigo-200')}` : 'border-gray-100 shadow-sm'} ${task.isCompleted ? 'bg-gray-50/50' : 'bg-white hover:border-gray-200 hover:shadow-md'}`}>
                                            <div className="flex items-start gap-3 p-4">
                                                <button 
                                                    onClick={() => toggleTask(cat.id, task.id)}
                                                    className={`w-6 h-6 rounded-xl border-2 flex items-center justify-center shrink-0 mt-0.5 transition-all ${task.isCompleted ? (activePeriod === 'five_year' ? 'bg-purple-600 border-purple-600' : (activePeriod === 'yearly' ? 'bg-red-600 border-red-600' : 'bg-indigo-600 border-indigo-600')) + ' text-white shadow-lg' : 'border-gray-200 bg-white hover:border-indigo-400'}`}
                                                >
                                                    {task.isCompleted && <IconCheck className="w-4 h-4" />}
                                                </button>

                                                <div className="flex-grow flex flex-col min-w-0" onClick={() => setExpandedTaskId(isExpanded ? null : task.id)}>
                                                    <span className={`text-[12px] font-black leading-tight cursor-pointer ${task.isCompleted ? 'text-gray-300 line-through' : 'text-gray-800'}`}>
                                                        {task.text}
                                                    </span>

                                                    {(hasSteps || isExpanded) && (
                                                        <div className="mt-3 w-full animate-fade-in">
                                                            <div className="flex justify-between items-center mb-1.5">
                                                                <span className={`text-[9px] font-black uppercase ${activePeriod === 'five_year' ? 'text-purple-400' : (activePeriod === 'yearly' ? 'text-red-400' : 'text-indigo-400')}`}>{t.progress}</span>
                                                                <span className={`text-[9px] font-black ${activePeriod === 'five_year' ? 'text-purple-600' : (activePeriod === 'yearly' ? 'text-red-600' : 'text-indigo-600')}`}>{taskProg}%</span>
                                                            </div>
                                                            <div className="w-full bg-gray-100 h-1.5 rounded-full overflow-hidden">
                                                                <div className={`h-full transition-all duration-700 ${taskProg === 100 ? 'bg-green-500' : (activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-red-600' : 'bg-indigo-600'))}`} style={{ width: `${taskProg}%` }}></div>
                                                            </div>
                                                        </div>
                                                    )}
                                                </div>

                                                <div className="flex flex-col gap-2 shrink-0 opacity-0 group-hover/col:opacity-100 transition-opacity">
                                                     <button onClick={() => removeTask(cat.id, task.id)} className="p-1.5 rounded-full hover:bg-red-50 text-red-200 hover:text-red-600 transition-colors">
                                                         <IconTrash className="w-3.5 h-3.5" />
                                                     </button>
                                                </div>
                                            </div>

                                            {/* Break-down Steps */}
                                            {isExpanded && (
                                                <div className="px-4 pb-5 space-y-3 animate-slide-in">
                                                    <div className="h-px bg-gray-100 mx-1"></div>
                                                    <div className={`space-y-2.5 pl-4 border-r-2 ${activePeriod === 'five_year' ? 'border-purple-200' : (activePeriod === 'yearly' ? 'border-red-200' : 'border-indigo-200')}`}>
                                                        {task.subTasks?.map(st => (
                                                            <div key={st.id} className="flex items-center gap-3 group/step">
                                                                <button 
                                                                    onClick={() => toggleSubTask(cat.id, task.id, st.id)}
                                                                    className={`w-4 h-4 rounded-lg border flex items-center justify-center transition-all ${st.isCompleted ? (activePeriod === 'five_year' ? 'bg-purple-400 border-purple-400' : (activePeriod === 'yearly' ? 'bg-red-400 border-red-400' : 'bg-indigo-400 border-indigo-400')) + ' text-white' : 'border-gray-300 bg-white hover:border-indigo-200'}`}
                                                                >
                                                                    {st.isCompleted && <IconCheck className="w-2.5 h-2.5" />}
                                                                </button>
                                                                <span className={`text-[11px] font-bold flex-grow ${st.isCompleted ? 'text-gray-300 line-through' : 'text-gray-600'}`}>
                                                                    {st.text}
                                                                </span>
                                                                <button onClick={() => {
                                                                    const updated = task.subTasks?.filter(s => s.id !== st.id);
                                                                    const allDone = updated?.every(s => s.isCompleted) || false;
                                                                    const updatedCategories = currentUserGoals.categories.map(c => 
                                                                        c.id === cat.id ? { ...c, tasks: c.tasks.map(t => t.id === task.id ? { ...t, subTasks: updated, isCompleted: allDone } : t) } : c
                                                                    );
                                                                    const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
                                                                    setCurrentUserGoals(updatedGoals);
                                                                    saveUserGoals(updatedGoals);
                                                                }} className="text-red-200 hover:text-red-500 opacity-0 group-hover/step:opacity-100 transition-opacity">✕</button>
                                                            </div>
                                                        ))}
                                                        <input 
                                                            className="w-full bg-gray-50 border border-gray-100 rounded-xl px-4 py-2 text-[10px] font-bold outline-none focus:bg-white focus:ring-1 focus:ring-indigo-100 transition-all"
                                                            placeholder={t.addSubTask}
                                                            onKeyDown={(e) => {
                                                                if (e.key === 'Enter' && (e.target as HTMLInputElement).value.trim()) {
                                                                    handleAddSubTask(cat.id, task.id, (e.target as HTMLInputElement).value);
                                                                    (e.target as HTMLInputElement).value = '';
                                                                }
                                                            }}
                                                        />
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                                {cat.tasks.length === 0 && (
                                    <div className="h-full flex flex-col items-center justify-center text-center py-16 opacity-30">
                                        <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mb-3 border border-dashed border-gray-200">
                                            <IconTarget className="w-8 h-8 text-gray-200" />
                                        </div>
                                        <span className="text-[10px] font-black text-gray-300 uppercase tracking-widest">{t.empty}</span>
                                    </div>
                                )}
                            </div>

                            {/* Column Action */}
                            {canEdit && (
                                <div className="p-5 border-t border-gray-50">
                                    <button 
                                        onClick={() => handleAddTask(cat.id)}
                                        className={`w-full py-3 rounded-[1.5rem] border-2 border-dashed border-gray-200 text-gray-400 font-black text-[11px] uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${activePeriod === 'five_year' ? 'hover:border-purple-300 hover:text-purple-600 hover:bg-purple-50' : (activePeriod === 'yearly' ? 'hover:border-red-300 hover:text-red-600 hover:bg-red-50' : 'hover:border-indigo-300 hover:text-indigo-600 hover:bg-indigo-50')}`}
                                    >
                                        <IconPlus className="w-4 h-4" /> {t.addGoal}
                                    </button>
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>

            {/* Footer Note */}
            <div className="text-center pt-8 border-t border-gray-100 print:hidden">
                <p className="text-[10px] font-black text-gray-300 uppercase tracking-[0.2em] mb-3">{t.smartNote}</p>
                <div className="inline-flex items-center gap-2 bg-gray-100 px-4 py-1.5 rounded-full text-[9px] font-bold text-gray-500">
                    <IconClock className="w-3 h-3" />
                    {t.lastUpdate} {new Date(currentUserGoals?.lastUpdated || '').toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}
                </div>
            </div>

            {/* --- PRINT POSTER VIEW (Hidden on Screen) --- */}
            <div className={`hidden print:flex flex-col h-[297mm] w-[210mm] mx-auto bg-white overflow-hidden p-0 relative border-[10px] ${activePeriod === 'five_year' ? 'border-purple-600' : (activePeriod === 'yearly' ? 'border-red-600' : 'border-indigo-600')}`}>
                 {/* Decorative Circles */}
                 <div className="absolute -top-20 -right-20 w-80 h-80 rounded-full bg-gray-50 -z-10"></div>
                 <div className="absolute -bottom-20 -left-20 w-80 h-80 rounded-full bg-gray-50 -z-10"></div>

                 {/* Banner */}
                 <div className={`p-10 flex items-center justify-between text-white ${activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-red-600' : 'bg-indigo-600')}`}>
                    <div className="flex items-center gap-8">
                        <div className="w-28 h-28 rounded-[2rem] bg-white/20 backdrop-blur-md border-4 border-white/30 overflow-hidden shadow-2xl flex items-center justify-center">
                            {selectedPerson?.avatar ? <img src={selectedPerson.avatar} className="w-full h-full object-cover" /> : <span className="text-4xl font-black">{selectedPerson?.fullName.charAt(0)}</span>}
                        </div>
                        <div>
                            <h1 className="text-3xl font-black mb-2">{selectedPerson?.fullName}</h1>
                            <div className="flex gap-2">
                                {selectedPerson?.roles.map(r => <span className="bg-white/20 px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider border border-white/20">{r}</span>)}
                            </div>
                        </div>
                    </div>
                    <div className="text-left flex flex-col items-end">
                        <div className="text-5xl font-black opacity-30 mb-2">TARGETS</div>
                        <div className="bg-black/10 px-6 py-3 rounded-2xl border border-white/10 text-center">
                            <div className="text-3xl font-black">{stats.percent}%</div>
                            <div className="text-[10px] font-black opacity-70 uppercase tracking-widest">TOTAL PROGRESS</div>
                        </div>
                    </div>
                 </div>

                 {/* Title & Info */}
                 <div className="p-10 pb-0 flex justify-between items-end border-b-2 border-gray-100">
                    <div className="pb-6">
                        <h2 className={`text-2xl font-black mb-1 ${activePeriod === 'five_year' ? 'text-purple-900' : (activePeriod === 'yearly' ? 'text-red-900' : 'text-indigo-900')}`}>{t.reportTitle}</h2>
                        <div className="flex items-center gap-3 text-gray-400 font-black text-xs uppercase tracking-widest">
                            {periodIcons[activePeriod]} {t[activePeriod as keyof typeof t.fa]} • PERIOD 2024-2025
                        </div>
                    </div>
                    <div className="pb-6 text-left">
                        <div className="text-[9px] font-black text-gray-300 mb-1 uppercase">DATE GENERATED</div>
                        <div className="text-sm font-black text-gray-800 dir-ltr">{new Date().toLocaleDateString('fa-IR')}</div>
                    </div>
                 </div>

                 {/* Print Grid */}
                 <div className="flex-grow p-10 grid grid-cols-2 gap-8 bg-gray-50/30">
                    {currentUserGoals?.categories.map((cat) => (
                        <div key={cat.id} className="bg-white rounded-[2rem] border border-gray-200 shadow-sm overflow-hidden flex flex-col max-h-[400px]">
                            <div className={`px-6 py-4 border-b-2 font-black text-xs text-indigo-900 uppercase tracking-widest bg-gray-50 flex justify-between items-center ${activePeriod === 'five_year' ? 'border-purple-500' : (activePeriod === 'yearly' ? 'border-red-500' : 'border-indigo-500')}`}>
                                <span>{cat.title}</span>
                                <span>{Math.round((cat.tasks.filter(t=>t.isCompleted).length / (cat.tasks.length || 1)) * 100)}%</span>
                            </div>
                            <div className="p-6 space-y-4 overflow-y-auto">
                                {cat.tasks.map((task) => (
                                    <div key={task.id} className="flex gap-4">
                                        <div className={`w-4 h-4 rounded-md border mt-1 shrink-0 ${task.isCompleted ? (activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-red-600' : 'bg-indigo-600')) : 'bg-white border-gray-300'}`}></div>
                                        <div>
                                            <div className={`text-[12px] font-black ${task.isCompleted ? 'text-gray-300 line-through' : 'text-gray-800'}`}>{task.text}</div>
                                            {task.subTasks && task.subTasks.length > 0 && (
                                                <div className="mt-2 space-y-1.5 pl-4 border-r-2 border-gray-100">
                                                    {task.subTasks.map(st => (
                                                        <div key={st.id} className="text-[10px] font-bold text-gray-400 flex items-center gap-2">
                                                            <div className={`w-1.5 h-1.5 rounded-full ${st.isCompleted ? 'bg-indigo-400' : 'bg-gray-200'}`}></div>
                                                            <span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    ))}
                 </div>

                 {/* Print Footer */}
                 <div className="p-10 border-t-2 border-gray-100 flex justify-between items-center bg-white shrink-0">
                    <div className="max-w-[70%]">
                        <p className="text-[11px] font-black text-indigo-600 uppercase tracking-[0.2em] mb-2">MOTIVATIONAL VISION</p>
                        <p className="text-xs font-black text-gray-500 italic leading-relaxed">"{t.visionNote}"</p>
                    </div>
                    <div className="text-left flex flex-col items-end">
                        <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-2 shadow-xl ${activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-red-600' : 'bg-indigo-600')}`}>
                            <IconShield className="w-7 h-7 text-white" />
                        </div>
                        <span className="text-[8px] font-black text-gray-300 uppercase tracking-widest">SMART CRM PERFORMANCE</span>
                    </div>
                 </div>
            </div>

            <style>{`
                .no-scrollbar::-webkit-scrollbar { display: none; }
                .custom-scrollbar::-webkit-scrollbar { width: 4px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }

                @media print {
                    @page { size: A4; margin: 0; }
                    html, body { height: 100%; margin: 0 !important; padding: 0 !important; overflow: hidden !important; }
                    #root > div > header, #root > div > footer, #root > div > nav, #root > div > .fixed, .print\\:hidden { 
                        display: none !important; 
                        visibility: hidden !important; 
                    }
                    main { padding: 0 !important; max-width: 100% !important; margin: 0 !important; }
                    .print\\:flex { display: flex !important; }
                    * { -webkit-print-color-adjust: exact !important; color-adjust: exact !important; }
                }
            `}</style>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconCalendar, IconChart, IconShield, IconBrain, IconArrowRight, IconActivity, IconBriefcase, IconUsers, IconPrinter, IconAward, IconTrendingUp, IconClock } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف کاری (Business)', color: 'bg-blue-50 border-blue-200 text-blue-700 header-blue', type: 'business' as const },
    { id: 'cat2', title: 'توسعه فردی (Personal)', color: 'bg-emerald-50 border-emerald-200 text-emerald-700 header-green', type: 'personal' as const },
    { id: 'cat3', title: 'سلامتی و لایف‌استایل', color: 'bg-orange-50 border-orange-200 text-orange-700 header-orange', type: 'personal' as const },
    { id: 'cat4', title: 'اهداف مالی', color: 'bg-rose-50 border-rose-200 text-rose-700 header-rose', type: 'personal' as const },
    { id: 'cat5', title: 'سایر موارد', color: 'bg-purple-50 border-purple-200 text-purple-700 header-purple', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [editingTitleId, setEditingTitleId] = useState<string | null>(null);
    const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

    const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');
    const canEdit = selectedUserId === currentUser.id;

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => {
            c.tasks.forEach(t => {
                total++;
                if (t.isCompleted) done++;
            });
        });
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const t = {
        fa: {
            title: 'ردیاب اهداف هوشمند',
            daily: 'امروز',
            weekly: 'هفتگی',
            monthly: 'ماهانه',
            yearly: 'سالانه',
            five_year: '۵ ساله',
            viewMode: 'درحال مشاهده:',
            business: 'اهداف کاری',
            personal: 'توسعه فردی',
            addGoal: 'افزودن هدف جدید',
            editTitle: 'ویرایش عنوان',
            saveTitle: 'ذخیره',
            done: 'انجام شد',
            total: 'کل',
            progress: 'پیشرفت',
            empty: 'هدفی ثبت نشده است.',
            masterView: 'مشاهده اهداف:',
            lastUpdate: 'آخرین بروزرسانی:',
            smartNote: 'اهداف باید هوشمند (SMART) باشند.',
            addSubTask: 'افزودن گام اجرایی...',
            breakDown: 'خرد کردن هدف',
            print: 'چاپ پستر اهداف (A4)',
            reportTitle: 'برنامه راهبردی و اهداف بلندمدت',
            visionNote: 'رویاهای بزرگ داشته باشید، اما از قدم‌های کوچک شروع کنید.'
        },
        en: {
            title: 'SMART Goal Tracker',
            daily: 'Daily',
            weekly: 'Weekly',
            monthly: 'Monthly',
            yearly: 'Yearly',
            five_year: '5-Year',
            viewMode: 'Current View:',
            business: 'Business Goals',
            personal: 'Personal Development',
            addGoal: 'Add Goal',
            editTitle: 'Edit Title',
            saveTitle: 'Save',
            done: 'Done',
            total: 'Total',
            progress: 'Progress',
            empty: 'No goals set yet.',
            masterView: 'View Staff Goals:',
            lastUpdate: 'Last Updated:',
            smartNote: 'Specific, Measurable, Achievable, Relevant, Time-bound',
            addSubTask: 'Add step...',
            breakDown: 'Break down',
            print: 'Print Poster (A4)',
            reportTitle: 'Strategic Plan & Vision',
            visionNote: 'Dream big, but start small.'
        }
    }[lang];

    const selectedPerson = useMemo(() => personnel.find(p => p.id === selectedUserId), [personnel, selectedUserId]);

    const handleAddTask = (catId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const taskText = window.prompt(lang === 'fa' ? 'عنوان هدف را وارد کنید:' : 'Enter goal title:');
        if (!taskText) return;

        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: taskText, isCompleted: false, subTasks: [] }] };
            }
            return c;
        });

        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.map(t => {
                    if (t.id === taskId) {
                        const newCompleted = !t.isCompleted;
                        const updatedSubTasks = t.subTasks?.map(st => ({ ...st, isCompleted: newCompleted }));
                        return { ...t, isCompleted: newCompleted, subTasks: updatedSubTasks };
                    }
                    return t;
                })};
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleAddSubTask = (catId: string, taskId: string, text: string) => {
        if (!canEdit || !currentUserGoals || !text.trim()) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.map(t => {
                    if (t.id === taskId) {
                        const newSub: GoalSubTask = { id: `st-${Date.now()}`, text, isCompleted: false };
                        return { ...t, subTasks: [...(t.subTasks || []), newSub], isCompleted: false };
                    }
                    return t;
                })};
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleSubTask = (catId: string, taskId: string, subId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.map(t => {
                    if (t.id === taskId) {
                        const updatedSubTasks = t.subTasks?.map(st => st.id === subId ? { ...st, isCompleted: !st.isCompleted } : st);
                        const allDone = updatedSubTasks?.every(st => st.isCompleted) || false;
                        return { ...t, subTasks: updatedSubTasks, isCompleted: allDone };
                    }
                    return t;
                })};
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const removeTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals || !window.confirm('حذف هدف؟')) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.filter(t => t.id !== taskId) };
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleUpdateCategoryTitle = (catId: string, newTitle: string) => {
        if (!canEdit || !currentUserGoals || !newTitle.trim()) {
            setEditingTitleId(null);
            return;
        }
        const updatedCategories = currentUserGoals.categories.map(c => 
            c.id === catId ? { ...c, title: newTitle } : c
        );
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
        setEditingTitleId(null);
    };

    const calculateTaskProgress = (task: GoalTask) => {
        if (!task.subTasks || task.subTasks.length === 0) return task.isCompleted ? 100 : 0;
        const done = task.subTasks.filter(st => st.isCompleted).length;
        return Math.round((done / task.subTasks.length) * 100);
    };

    const handlePrint = () => {
        window.print();
    };

    if (isLoading) return <div className="p-8 text-center animate-pulse text-indigo-600 font-bold">در حال بارگذاری اهداف استراتژیک...</div>;

    const periodIcons: Record<string, React.ReactNode> = {
        daily: <IconClock className="w-4 h-4" />,
        weekly: <IconCalendar className="w-4 h-4" />,
        monthly: <IconActivity className="w-4 h-4" />,
        yearly: <IconAward className="w-4 h-4" />,
        five_year: <IconTrendingUp className="w-4 h-4" />
    };

    const navItems = [
        { id: 'daily', activeColor: 'bg-blue-600 shadow-blue-100', hoverColor: 'hover:text-blue-600' },
        { id: 'weekly', activeColor: 'bg-green-600 shadow-green-100', hoverColor: 'hover:text-green-600' },
        { id: 'monthly', activeColor: 'bg-orange-600 shadow-orange-100', hoverColor: 'hover:text-orange-600' },
        { id: 'yearly', activeColor: 'bg-rose-600 shadow-rose-100', hoverColor: 'hover:text-rose-600' },
        { id: 'five_year', activeColor: 'bg-purple-600 shadow-purple-100', hoverColor: 'hover:text-purple-600' }
    ];

    return (
        <div className="space-y-8 animate-fade-in pb-12">
            {/* --- WEB UI: CONTROL PANEL (HIDDEN ON PRINT) --- */}
            <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-gray-100 flex flex-col lg:flex-row gap-8 items-center relative overflow-hidden print:hidden">
                <div className={`absolute top-0 right-0 w-48 h-48 rounded-bl-full -z-10 opacity-10 transition-colors duration-700 ${activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600' : 'bg-indigo-600')}`}></div>

                <div className="shrink-0 w-full lg:w-1/3">
                    <h2 className="text-3xl font-black text-gray-900 mb-1 uppercase tracking-tight">{t.title}</h2>
                    <div className="flex items-center gap-2 mb-6">
                        <span className="text-xs font-bold text-gray-400">{t.viewMode}</span>
                        <span className={`px-2 py-0.5 rounded-lg text-[10px] font-black text-white ${navItems.find(n => n.id === activePeriod)?.activeColor.split(' ')[0]}`}>
                            {t[activePeriod as keyof typeof t.fa]}
                        </span>
                    </div>

                    {/* PERIOD SWITCHER: FIXED 5 COLUMNS */}
                    <div className="bg-gray-100 p-1.5 rounded-2xl mb-6 grid grid-cols-5 gap-1.5 border border-gray-200 shadow-inner">
                        {navItems.map(btn => (
                            <button 
                                key={btn.id}
                                onClick={() => { setActivePeriod(btn.id as GoalPeriod); setExpandedTaskId(null); }}
                                className={`flex flex-col items-center justify-center py-3 rounded-xl transition-all duration-300 ${activePeriod === btn.id ? `${btn.activeColor} text-white shadow-lg scale-105 z-10` : `text-gray-500 ${btn.hoverColor} hover:bg-white`}`}
                            >
                                <div className="mb-1">{periodIcons[btn.id]}</div>
                                <span className="text-[9px] font-black uppercase whitespace-nowrap">{t[btn.id as keyof typeof t.fa]}</span>
                            </button>
                        ))}
                    </div>

                    <div className="flex flex-col gap-3">
                        {isMaster && (
                            <div className="space-y-1">
                                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-1">{t.masterView}</label>
                                <select 
                                    className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-100"
                                    value={selectedUserId}
                                    onChange={(e) => { setSelectedUserId(e.target.value); setExpandedTaskId(null); }}
                                >
                                    {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                                </select>
                            </div>
                        )}
                        <button 
                            onClick={handlePrint}
                            className={`w-full py-3.5 text-white rounded-2xl text-xs font-black flex items-center justify-center gap-2 transition-all shadow-lg border-b-4 active:border-b-0 active:translate-y-1 ${activePeriod === 'five_year' ? 'bg-purple-600 border-purple-800 shadow-purple-100' : (activePeriod === 'yearly' ? 'bg-rose-600 border-rose-800 shadow-rose-100' : 'bg-indigo-600 border-indigo-800 shadow-indigo-100')}`}
                        >
                            <IconPrinter className="w-4 h-4" /> {t.print}
                        </button>
                    </div>
                </div>

                {/* Overall Gauge */}
                <div className="flex flex-col items-center gap-2 lg:border-r lg:px-10 border-gray-100">
                    <div className="relative w-36 h-36 flex items-center justify-center">
                        <svg className="w-full h-full transform -rotate-90">
                            <circle cx="72" cy="72" r="62" stroke="currentColor" strokeWidth="12" fill="transparent" className="text-gray-100" />
                            <circle cx="72" cy="72" r="62" stroke="currentColor" strokeWidth="12" fill="transparent" strokeDasharray={389.557} strokeDashoffset={389.557 - (stats.percent / 100) * 389.557} className={`transition-all duration-1000 ease-out ${activePeriod === 'five_year' ? 'text-purple-600' : (activePeriod === 'yearly' ? 'text-rose-600' : 'text-indigo-600')}`} />
                        </svg>
                        <div className="absolute inset-0 flex flex-col items-center justify-center">
                            <span className="text-3xl font-black text-gray-900">{stats.percent}%</span>
                            <span className="text-[9px] font-black text-gray-400 uppercase tracking-tighter">{t.progress}</span>
                        </div>
                    </div>
                </div>

                {/* Category Summaries */}
                <div className="flex-grow grid grid-cols-2 sm:grid-cols-3 gap-4 w-full">
                    {currentUserGoals?.categories.map(cat => {
                        const catProgress = cat.tasks.length > 0 ? Math.round((cat.tasks.filter(t => t.isCompleted).length / cat.tasks.length) * 100) : 0;
                        const catColor = cat.color.split(' ')[2].replace('text-', 'bg-');
                        return (
                            <div key={cat.id} className="bg-gray-50 p-4 rounded-3xl flex flex-col justify-center border border-gray-100">
                                <div className="text-[9px] font-black text-gray-400 uppercase truncate mb-2">{cat.title}</div>
                                <div className="flex items-center justify-between gap-3">
                                    <div className="flex-grow bg-gray-200 h-2 rounded-full overflow-hidden">
                                        <div className={`h-full rounded-full transition-all duration-1000 ${catColor}`} style={{ width: `${catProgress}%` }}></div>
                                    </div>
                                    <span className="text-[11px] font-black text-gray-700">{catProgress}%</span>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* --- WEB UI: GOALS GRID (HIDDEN ON PRINT) --- */}
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-5 gap-6 print:hidden">
                {currentUserGoals?.categories.map((cat) => {
                    const catTotal = cat.tasks.length;
                    const catDone = cat.tasks.filter(t => t.isCompleted).length;
                    const catProgress = catTotal > 0 ? Math.round((catDone / catTotal) * 100) : 0;
                    const headerColors: any = { 'header-blue': 'bg-blue-500', 'header-rose': 'bg-rose-500', 'header-green': 'bg-emerald-500', 'header-orange': 'bg-orange-500', 'header-purple': 'bg-purple-500' };
                    const hColor = headerColors[cat.color.split(' ').find(c => c.startsWith('header-')) || ''] || 'bg-indigo-500';

                    return (
                        <div key={cat.id} className={`bg-white rounded-[2.5rem] border border-gray-100 shadow-lg overflow-hidden flex flex-col min-h-[550px] group/col transition-all duration-500 ${activePeriod === 'five_year' ? 'ring-2 ring-purple-100 border-purple-200 shadow-purple-50' : (activePeriod === 'yearly' ? 'ring-2 ring-rose-100 border-rose-200 shadow-rose-50' : '')}`}>
                            <div className={`${hColor} p-5 text-center text-white font-black text-xs uppercase tracking-widest relative`}>
                                {editingTitleId === cat.id ? (
                                    <input autoFocus className="w-full bg-white/20 text-white placeholder-white/70 px-3 py-1.5 rounded-xl outline-none border border-white/30 text-center text-sm" defaultValue={cat.title} onBlur={(e) => handleUpdateCategoryTitle(cat.id, e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleUpdateCategoryTitle(cat.id, (e.target as HTMLInputElement).value)} />
                                ) : (
                                    <div className="flex items-center justify-center gap-2">
                                        {cat.type === 'business' ? <IconBriefcase className="w-4 h-4" /> : <IconUsers className="w-4 h-4" />}
                                        <span onClick={() => canEdit && setEditingTitleId(cat.id)} className={canEdit ? "cursor-pointer hover:underline" : ""}>{cat.title}</span>
                                        {canEdit && <button onClick={() => setEditingTitleId(cat.id)} className="opacity-40 hover:opacity-100 transition-opacity"><IconEdit className="w-3.5 h-3.5" /></button>}
                                    </div>
                                )}
                            </div>
                            <div className="bg-gray-50/50 border-b border-gray-100 p-4 grid grid-cols-3 gap-2 text-center">
                                <div><div className="text-[8px] font-black text-gray-400 uppercase mb-1">{t.done}</div><div className="text-sm font-black text-gray-900">{catDone}</div></div>
                                <div><div className="text-[8px] font-black text-gray-400 uppercase mb-1">{t.total}</div><div className="text-sm font-black text-gray-900">{catTotal}</div></div>
                                <div><div className="text-[8px] font-black text-gray-400 uppercase mb-1">{t.progress}</div><div className={`text-sm font-black ${activePeriod === 'five_year' ? 'text-purple-600' : (activePeriod === 'yearly' ? 'text-rose-600' : 'text-indigo-600')}`}>{catProgress}%</div></div>
                            </div>
                            <div className="flex-grow overflow-y-auto p-4 space-y-4 custom-scrollbar">
                                {cat.tasks.map((task) => {
                                    const taskProg = calculateTaskProgress(task);
                                    const isExpanded = expandedTaskId === task.id;
                                    return (
                                        <div key={task.id} className={`flex flex-col rounded-3xl border transition-all duration-300 ${isExpanded ? `ring-2 ${activePeriod === 'five_year' ? 'ring-purple-200 border-purple-200' : (activePeriod === 'yearly' ? 'ring-rose-200 border-rose-200' : 'ring-indigo-200 border-indigo-200')}` : 'border-gray-100 shadow-sm'} ${task.isCompleted ? 'bg-gray-50/50' : 'bg-white hover:border-gray-200 hover:shadow-md'}`}>
                                            <div className="flex items-start gap-3 p-4">
                                                <button onClick={() => toggleTask(cat.id, task.id)} className={`w-6 h-6 rounded-xl border-2 flex items-center justify-center shrink-0 mt-0.5 transition-all ${task.isCompleted ? (activePeriod === 'five_year' ? 'bg-purple-600 border-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600 border-rose-600' : 'bg-indigo-600 border-indigo-600')) + ' text-white shadow-lg' : 'border-gray-200 bg-white hover:border-indigo-400'}`}>
                                                    {task.isCompleted && <IconCheck className="w-4 h-4" />}
                                                </button>
                                                <div className="flex-grow flex flex-col min-w-0" onClick={() => setExpandedTaskId(isExpanded ? null : task.id)}>
                                                    <span className={`text-[12px] font-black leading-tight cursor-pointer ${task.isCompleted ? 'text-gray-300 line-through' : 'text-gray-800'}`}>{task.text}</span>
                                                    {(task.subTasks?.length || 0 > 0 || isExpanded) && (
                                                        <div className="mt-3 w-full animate-fade-in">
                                                            <div className="flex justify-between items-center mb-1.5"><span className={`text-[9px] font-black uppercase ${activePeriod === 'five_year' ? 'text-purple-400' : (activePeriod === 'yearly' ? 'text-rose-400' : 'text-indigo-400')}`}>{t.progress}</span><span className={`text-[9px] font-black ${activePeriod === 'five_year' ? 'text-purple-600' : (activePeriod === 'yearly' ? 'text-rose-600' : 'text-indigo-600')}`}>{taskProg}%</span></div>
                                                            <div className="w-full bg-gray-100 h-1.5 rounded-full overflow-hidden"><div className={`h-full transition-all duration-700 ${taskProg === 100 ? 'bg-green-500' : (activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600' : 'bg-indigo-600'))}`} style={{ width: `${taskProg}%` }}></div></div>
                                                        </div>
                                                    )}
                                                </div>
                                                <div className="flex flex-col gap-2 shrink-0 opacity-0 group-hover/col:opacity-100 transition-opacity">
                                                     <button onClick={() => removeTask(cat.id, task.id)} className="p-1.5 rounded-full hover:bg-red-50 text-red-200 hover:text-red-600 transition-colors"><IconTrash className="w-3.5 h-3.5" /></button>
                                                </div>
                                            </div>
                                            {isExpanded && (
                                                <div className="px-4 pb-5 space-y-3 animate-slide-in">
                                                    <div className="h-px bg-gray-100 mx-1"></div>
                                                    <div className={`space-y-2.5 pl-4 border-r-2 ${activePeriod === 'five_year' ? 'border-purple-200' : (activePeriod === 'yearly' ? 'border-rose-200' : 'border-indigo-200')}`}>
                                                        {task.subTasks?.map(st => (
                                                            <div key={st.id} className="flex items-center gap-3 group/step">
                                                                <button onClick={() => toggleSubTask(cat.id, task.id, st.id)} className={`w-4 h-4 rounded-lg border flex items-center justify-center transition-all ${st.isCompleted ? (activePeriod === 'five_year' ? 'bg-purple-400 border-purple-400' : (activePeriod === 'yearly' ? 'bg-rose-400 border-rose-400' : 'bg-indigo-400 border-indigo-400')) + ' text-white' : 'border-gray-300 bg-white hover:border-indigo-200'}`}>{st.isCompleted && <IconCheck className="w-2.5 h-2.5" />}</button>
                                                                <span className={`text-[11px] font-bold flex-grow ${st.isCompleted ? 'text-gray-300 line-through' : 'text-gray-600'}`}>{st.text}</span>
                                                                <button onClick={() => { const updated = task.subTasks?.filter(s => s.id !== st.id); const updatedGoals = { ...currentUserGoals, categories: currentUserGoals.categories.map(c => c.id === cat.id ? { ...c, tasks: c.tasks.map(t => t.id === task.id ? { ...t, subTasks: updated } : t) } : c), lastUpdated: new Date().toISOString() }; setCurrentUserGoals(updatedGoals); saveUserGoals(updatedGoals); }} className="text-red-200 hover:text-red-500 opacity-0 group-hover/step:opacity-100 transition-opacity">✕</button>
                                                            </div>
                                                        ))}
                                                        <input className="w-full bg-gray-50 border border-gray-100 rounded-xl px-4 py-2 text-[10px] font-bold outline-none focus:bg-white focus:ring-1 focus:ring-indigo-100 transition-all" placeholder={t.addSubTask} onKeyDown={(e) => { if (e.key === 'Enter' && (e.target as HTMLInputElement).value.trim()) { handleAddSubTask(cat.id, task.id, (e.target as HTMLInputElement).value); (e.target as HTMLInputElement).value = ''; } }} />
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                                {cat.tasks.length === 0 && <div className="h-full flex flex-col items-center justify-center text-center py-16 opacity-30"><IconTarget className="w-8 h-8 text-gray-200 mb-3" /><span className="text-[10px] font-black text-gray-300 uppercase tracking-widest">{t.empty}</span></div>}
                            </div>
                            {canEdit && (
                                <div className="p-5 border-t border-gray-50">
                                    <button onClick={() => handleAddTask(cat.id)} className={`w-full py-3 rounded-[1.5rem] border-2 border-dashed border-gray-200 text-gray-400 font-black text-[11px] uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${activePeriod === 'five_year' ? 'hover:border-purple-300 hover:text-purple-600 hover:bg-purple-50' : (activePeriod === 'yearly' ? 'hover:border-rose-300 hover:text-rose-600 hover:bg-rose-50' : 'hover:border-indigo-300 hover:text-indigo-600 hover:bg-indigo-50')}`}>
                                        <IconPlus className="w-4 h-4" /> {t.addGoal}
                                    </button>
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>

            {/* --- EXCLUSIVE PRINT POSTER: HIGH-AESTHETIC GRID (HIDDEN ON WEB) --- */}
            <div id="goal-poster-print" className={`hidden print:flex flex-col h-[267mm] w-[180mm] mx-auto bg-white overflow-hidden p-0 relative border-[10px] ${activePeriod === 'five_year' ? 'border-purple-600' : (activePeriod === 'yearly' ? 'border-rose-600' : 'border-indigo-600')}`}>
                 <div className="absolute -top-20 -right-20 w-80 h-80 rounded-full bg-gray-50 -z-10 opacity-50"></div>
                 <div className="absolute -bottom-20 -left-20 w-80 h-80 rounded-full bg-gray-50 -z-10 opacity-50"></div>

                 <div className={`p-10 flex items-center justify-between text-white ${activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600' : 'bg-indigo-600')}`}>
                    <div className="flex items-center gap-8">
                        <div className="w-28 h-28 rounded-[2rem] bg-white/20 backdrop-blur-md border-4 border-white/30 overflow-hidden shadow-2xl flex items-center justify-center">
                            {selectedPerson?.avatar ? <img src={selectedPerson.avatar} className="w-full h-full object-cover" /> : <span className="text-4xl font-black">{selectedPerson?.fullName.charAt(0)}</span>}
                        </div>
                        <div>
                            <h1 className="text-3xl font-black mb-2">{selectedPerson?.fullName}</h1>
                            <div className="flex gap-2">
                                {selectedPerson?.roles.map(r => <span key={r} className="bg-white/20 px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider border border-white/20">{r}</span>)}
                            </div>
                        </div>
                    </div>
                    <div className="text-left flex flex-col items-end">
                        <div className="text-5xl font-black opacity-30 mb-2">TARGETS</div>
                        <div className="bg-black/10 px-6 py-3 rounded-2xl border border-white/10 text-center">
                            <div className="text-3xl font-black">{stats.percent}%</div>
                            <div className="text-[10px] font-black opacity-70 uppercase tracking-widest">PERFORMANCE</div>
                        </div>
                    </div>
                 </div>

                 <div className="p-10 pb-4 flex justify-between items-end border-b-2 border-gray-100 bg-white">
                    <div>
                        <h2 className={`text-2xl font-black mb-1 ${activePeriod === 'five_year' ? 'text-purple-900' : (activePeriod === 'yearly' ? 'text-rose-900' : 'text-indigo-900')}`}>{t.reportTitle}</h2>
                        <div className="flex items-center gap-3 text-gray-400 font-black text-xs uppercase tracking-widest">
                            {periodIcons[activePeriod]} {t[activePeriod as keyof typeof t.fa]} • {new Date().getFullYear()}
                        </div>
                    </div>
                    <div className="text-left">
                        <div className="text-[9px] font-black text-gray-300 mb-1 uppercase tracking-tighter">DATE ISSUED</div>
                        <div className="text-sm font-black text-gray-800 dir-ltr">{new Date().toLocaleDateString(lang==='fa'?'fa-IR':'en-US')}</div>
                    </div>
                 </div>

                 <div className="flex-grow p-10 grid grid-cols-2 gap-8 bg-gray-50/20 overflow-hidden">
                    {currentUserGoals?.categories.map((cat) => (
                        <div key={cat.id} className="bg-white rounded-[2rem] border border-gray-200 shadow-sm overflow-hidden flex flex-col max-h-[420px] break-inside-avoid">
                            <div className={`px-6 py-4 border-b-2 font-black text-[11px] text-indigo-900 uppercase tracking-widest bg-gray-50 flex justify-between items-center ${activePeriod === 'five_year' ? 'border-purple-500' : (activePeriod === 'yearly' ? 'border-rose-500' : 'border-indigo-500')}`}>
                                <span>{cat.title}</span>
                                <span className="bg-white px-2 py-0.5 rounded-lg border">{Math.round((cat.tasks.filter(t=>t.isCompleted).length / (cat.tasks.length || 1)) * 100)}%</span>
                            </div>
                            <div className="p-6 space-y-4 overflow-hidden">
                                {cat.tasks.map((task) => (
                                    <div key={task.id} className="flex gap-4">
                                        <div className={`w-4 h-4 rounded-md border mt-1 shrink-0 ${task.isCompleted ? (activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600' : 'bg-indigo-600')) : 'bg-white border-gray-300'}`}></div>
                                        <div className="min-w-0">
                                            <div className={`text-[12px] font-black leading-tight ${task.isCompleted ? 'text-gray-300 line-through' : 'text-gray-800'}`}>{task.text}</div>
                                            {task.subTasks && task.subTasks.length > 0 && (
                                                <div className="mt-2 space-y-1.5 pl-4 border-r-2 border-gray-100">
                                                    {task.subTasks.map(st => (
                                                        <div key={st.id} className="text-[10px] font-bold text-gray-400 flex items-center gap-2">
                                                            <div className={`w-1.5 h-1.5 rounded-full ${st.isCompleted ? 'bg-indigo-400' : 'bg-gray-200'}`}></div>
                                                            <span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                ))}
                                {cat.tasks.length === 0 && <div className="text-[10px] text-gray-300 italic text-center py-4">No goals recorded</div>}
                            </div>
                        </div>
                    ))}
                 </div>

                 <div className="p-10 border-t-2 border-gray-100 flex justify-between items-center bg-white shrink-0">
                    <div className="max-w-[70%]">
                        <p className="text-[11px] font-black text-indigo-600 uppercase tracking-[0.2em] mb-2">MOTIVATIONAL VISION</p>
                        <p className="text-xs font-black text-gray-500 italic leading-relaxed">"{t.visionNote}"</p>
                    </div>
                    <div className="text-left flex flex-col items-end">
                        <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-2 shadow-xl ${activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600' : 'bg-indigo-600')}`}>
                            <IconShield className="w-7 h-7 text-white" />
                        </div>
                        <span className="text-[8px] font-black text-gray-300 uppercase tracking-widest">SMART CRM PERFORMANCE</span>
                    </div>
                 </div>
            </div>

            <style>{`
                .no-scrollbar::-webkit-scrollbar { display: none; }
                .custom-scrollbar::-webkit-scrollbar { width: 4px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }

                @media print {
                    @page { size: A4; margin: 0; }
                    body { margin: 0 !important; padding: 0 !important; background: white !important; }

                    /* HIDE EVERYTHING IN THE APP EXCEPT THE POSTER ID */
                    #root > div, #root > div > header, #root > div > footer, #root > div > nav, 
                    #root > div > .fixed, .print\\:hidden, aside, nav, header, footer { 
                        display: none !important; 
                        visibility: hidden !important; 
                    }

                    /* SHOW THE POSTER AND BRING TO FRONT */
                    #goal-poster-print { 
                        display: flex !important; 
                        visibility: visible !important;
                        position: absolute !important;
                        left: 0 !important;
                        top: 0 !important;
                        width: 100% !important;
                        height: 100% !important;
                        margin: 0 !important;
                        z-index: 9999 !important;
                    }

                    #goal-poster-print * { visibility: visible !important; }
                    * { -webkit-print-color-adjust: exact !important; color-adjust: exact !important; }
                }
            `}</style>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconCalendar, IconChart, IconShield, IconBrain, IconArrowRight, IconActivity, IconBriefcase, IconUsers, IconPrinter, IconAward, IconTrendingUp, IconClock } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف کاری (Business)', color: 'bg-blue-50 border-blue-200 text-blue-700 header-blue', type: 'business' as const },
    { id: 'cat2', title: 'توسعه فردی (Personal)', color: 'bg-emerald-50 border-emerald-200 text-emerald-700 header-green', type: 'personal' as const },
    { id: 'cat3', title: 'سلامتی و لایف‌استایل', color: 'bg-orange-50 border-orange-200 text-orange-700 header-orange', type: 'personal' as const },
    { id: 'cat4', title: 'اهداف مالی', color: 'bg-rose-50 border-rose-200 text-rose-700 header-rose', type: 'personal' as const },
    { id: 'cat5', title: 'سایر موارد', color: 'bg-purple-50 border-purple-200 text-purple-700 header-purple', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [editingTitleId, setEditingTitleId] = useState<string | null>(null);
    const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

    const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');
    const canEdit = selectedUserId === currentUser.id;

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => {
            c.tasks.forEach(t => {
                total++;
                if (t.isCompleted) done++;
            });
        });
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const t = {
        fa: {
            title: 'ردیاب اهداف هوشمند',
            daily: 'امروز',
            weekly: 'هفتگی',
            monthly: 'ماهانه',
            yearly: 'سالانه',
            five_year: '۵ ساله',
            viewMode: 'درحال مشاهده:',
            business: 'اهداف کاری',
            personal: 'توسعه فردی',
            addGoal: 'افزودن هدف جدید',
            editTitle: 'ویرایش عنوان',
            saveTitle: 'ذخیره',
            done: 'انجام شد',
            total: 'کل',
            progress: 'پیشرفت',
            empty: 'هدفی ثبت نشده است.',
            masterView: 'مشاهده اهداف:',
            lastUpdate: 'آخرین بروزرسانی:',
            smartNote: 'اهداف باید هوشمند (SMART) باشند.',
            addSubTask: 'افزودن گام اجرایی...',
            breakDown: 'خرد کردن هدف',
            print: 'چاپ پستر اهداف (A4)',
            reportTitle: 'برنامه راهبردی و اهداف بلندمدت',
            visionNote: 'رویاهای بزرگ داشته باشید، اما از قدم‌های کوچک شروع کنید.'
        },
        en: {
            title: 'SMART Goal Tracker',
            daily: 'Daily',
            weekly: 'Weekly',
            monthly: 'Monthly',
            yearly: 'Yearly',
            five_year: '5-Year',
            viewMode: 'Current View:',
            business: 'Business Goals',
            personal: 'Personal Development',
            addGoal: 'Add Goal',
            editTitle: 'Edit Title',
            saveTitle: 'Save',
            done: 'Done',
            total: 'Total',
            progress: 'Progress',
            empty: 'No goals set yet.',
            masterView: 'View Staff Goals:',
            lastUpdate: 'Last Updated:',
            smartNote: 'Specific, Measurable, Achievable, Relevant, Time-bound',
            addSubTask: 'Add step...',
            breakDown: 'Break down',
            print: 'Print Poster (A4)',
            reportTitle: 'Strategic Plan & Vision',
            visionNote: 'Dream big, but start small.'
        }
    }[lang];

    const selectedPerson = useMemo(() => personnel.find(p => p.id === selectedUserId), [personnel, selectedUserId]);

    const handleAddTask = (catId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const taskText = window.prompt(lang === 'fa' ? 'عنوان هدف را وارد کنید:' : 'Enter goal title:');
        if (!taskText) return;

        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: taskText, isCompleted: false, subTasks: [] }] };
            }
            return c;
        });

        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.map(t => {
                    if (t.id === taskId) {
                        const newCompleted = !t.isCompleted;
                        const updatedSubTasks = t.subTasks?.map(st => ({ ...st, isCompleted: newCompleted }));
                        return { ...t, isCompleted: newCompleted, subTasks: updatedSubTasks };
                    }
                    return t;
                })};
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleAddSubTask = (catId: string, taskId: string, text: string) => {
        if (!canEdit || !currentUserGoals || !text.trim()) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.map(t => {
                    if (t.id === taskId) {
                        const newSub: GoalSubTask = { id: `st-${Date.now()}`, text, isCompleted: false };
                        return { ...t, subTasks: [...(t.subTasks || []), newSub], isCompleted: false };
                    }
                    return t;
                })};
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleSubTask = (catId: string, taskId: string, subId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.map(t => {
                    if (t.id === taskId) {
                        const updatedSubTasks = t.subTasks?.map(st => st.id === subId ? { ...st, isCompleted: !st.isCompleted } : st);
                        const allDone = updatedSubTasks?.every(st => st.isCompleted) || false;
                        return { ...t, subTasks: updatedSubTasks, isCompleted: allDone };
                    }
                    return t;
                })};
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const removeTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals || !window.confirm('حذف هدف؟')) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.filter(t => t.id !== taskId) };
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleUpdateCategoryTitle = (catId: string, newTitle: string) => {
        if (!canEdit || !currentUserGoals || !newTitle.trim()) {
            setEditingTitleId(null);
            return;
        }
        const updatedCategories = currentUserGoals.categories.map(c => 
            c.id === catId ? { ...c, title: newTitle } : c
        );
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
        setEditingTitleId(null);
    };

    const calculateTaskProgress = (task: GoalTask) => {
        if (!task.subTasks || task.subTasks.length === 0) return task.isCompleted ? 100 : 0;
        const done = task.subTasks.filter(st => st.isCompleted).length;
        return Math.round((done / task.subTasks.length) * 100);
    };

    const handlePrint = () => {
        window.print();
    };

    if (isLoading) return <div className="p-8 text-center animate-pulse text-indigo-600 font-bold">در حال بارگذاری اهداف استراتژیک...</div>;

    const periodIcons: Record<string, React.ReactNode> = {
        daily: <IconClock className="w-4 h-4" />,
        weekly: <IconCalendar className="w-4 h-4" />,
        monthly: <IconActivity className="w-4 h-4" />,
        yearly: <IconAward className="w-4 h-4" />,
        five_year: <IconTrendingUp className="w-4 h-4" />
    };

    const navItems = [
        { id: 'daily', activeColor: 'bg-blue-600 shadow-blue-100', hoverColor: 'hover:text-blue-600' },
        { id: 'weekly', activeColor: 'bg-green-600 shadow-green-100', hoverColor: 'hover:text-green-600' },
        { id: 'monthly', activeColor: 'bg-orange-600 shadow-orange-100', hoverColor: 'hover:text-orange-600' },
        { id: 'yearly', activeColor: 'bg-rose-600 shadow-rose-100', hoverColor: 'hover:text-rose-600' },
