                        <span className={`px-2 py-0.5 rounded-lg text-[10px] font-black text-white ${navItems.find(n => n.id === activePeriod)?.activeColor.split(' ')[0]}`}>
                            {t[activePeriod as keyof typeof t.fa]}
                        </span>
                    </div>

                    {/* PERIOD SWITCHER: FIXED GRID + FLEX WRAP FOR MOBILE SAFETY */}
                    <div className="bg-gray-100 p-1.5 rounded-2xl mb-6 grid grid-cols-5 gap-1.5 border border-gray-200 shadow-inner overflow-hidden">
                        {navItems.map(btn => (
                            <button 
                                key={btn.id}
                                onClick={() => { setActivePeriod(btn.id as GoalPeriod); setExpandedTaskId(null); }}
                                className={`flex flex-col items-center justify-center py-3 rounded-xl transition-all duration-300 ${activePeriod === btn.id ? `${btn.activeColor} text-white shadow-lg scale-105 z-10` : `text-gray-500 ${btn.hoverColor} hover:bg-white`}`}
                            >
                                <div className="mb-1">{periodIcons[btn.id]}</div>
                                <span className="text-[9px] font-black uppercase whitespace-nowrap">{t[btn.id as keyof typeof t.fa]}</span>
                            </button>
