                                <div><div className="text-[8px] font-black text-gray-400 uppercase mb-1">{t.total}</div><div className="text-sm font-black text-gray-900">{catTotal}</div></div>
                                <div><div className="text-[8px] font-black text-gray-400 uppercase mb-1">{t.progress}</div><div className={`text-sm font-black ${activePeriod === 'five_year' ? 'text-purple-600' : (activePeriod === 'yearly' ? 'text-rose-600' : 'text-indigo-600')}`}>{catProgress}%</div></div>
                            </div>
                            <div className="flex-grow overflow-y-auto p-4 space-y-4 custom-scrollbar">
                                {cat.tasks.map((task) => {
                                    const taskProg = calculateTaskProgress(task);
                                    const isExpanded = expandedTaskId === task.id;
                                    return (
                                        <div key={task.id} className={`flex flex-col rounded-3xl border transition-all duration-300 ${isExpanded ? `ring-2 ${activePeriod === 'five_year' ? 'ring-purple-200 border-purple-200' : (activePeriod === 'yearly' ? 'ring-rose-200 border-red-200' : 'ring-indigo-200 border-indigo-200')}` : 'border-gray-100 shadow-sm'} ${task.isCompleted ? 'bg-gray-50/50' : 'bg-white hover:border-gray-200 hover:shadow-md'}`}>
                                            <div className="flex items-start gap-3 p-4">
                                                <button onClick={() => toggleTask(cat.id, task.id)} className={`w-6 h-6 rounded-xl border-2 flex items-center justify-center shrink-0 mt-0.5 transition-all ${task.isCompleted ? (activePeriod === 'five_year' ? 'bg-purple-600 border-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600 border-rose-600' : 'bg-indigo-600 border-indigo-600')) + ' text-white shadow-lg' : 'border-gray-200 bg-white hover:border-indigo-400'}`}>
                                                    {task.isCompleted && <IconCheck className="w-4 h-4" />}
                                                </button>
                                                <div className="flex-grow flex flex-col min-w-0" onClick={() => setExpandedTaskId(isExpanded ? null : task.id)}>
                                                    <span className={`text-[12px] font-black leading-tight cursor-pointer ${task.isCompleted ? 'text-gray-300 line-through' : 'text-gray-800'}`}>{task.text}</span>
                                                    {(task.subTasks?.length || 0 > 0 || isExpanded) && (
                                                        <div className="mt-3 w-full animate-fade-in">
                                                            <div className="flex justify-between items-center mb-1.5"><span className={`text-[9px] font-black uppercase ${activePeriod === 'five_year' ? 'text-purple-400' : (activePeriod === 'yearly' ? 'text-rose-400' : 'text-indigo-400')}`}>{t.progress}</span><span className={`text-[9px] font-black ${activePeriod === 'five_year' ? 'text-purple-600' : (activePeriod === 'yearly' ? 'text-rose-600' : 'text-indigo-600')}`}>{taskProg}%</span></div>
                                                            <div className="w-full bg-gray-100 h-1.5 rounded-full overflow-hidden"><div className={`h-full transition-all duration-700 ${taskProg === 100 ? 'bg-green-500' : (activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600' : 'bg-indigo-600'))}`} style={{ width: `${taskProg}%` }}></div></div>
                                                        </div>
                                                    )}
                                                </div>
                                                <div className="flex flex-col gap-2 shrink-0 opacity-0 group-hover/col:opacity-100 transition-opacity">
                                                     <button onClick={() => removeTask(cat.id, task.id)} className="p-1.5 rounded-full hover:bg-red-50 text-red-200 hover:text-red-600 transition-colors"><IconTrash className="w-3.5 h-3.5" /></button>
                                                </div>
                                            </div>
                                            {isExpanded && (
                                                <div className="px-4 pb-5 space-y-3 animate-slide-in">
                                                    <div className="h-px bg-gray-100 mx-1"></div>
                                                    <div className={`space-y-2.5 pl-4 border-r-2 ${activePeriod === 'five_year' ? 'border-purple-200' : (activePeriod === 'yearly' ? 'border-rose-200' : 'border-indigo-200')}`}>
                                                        {task.subTasks?.map(st => (
                                                            <div key={st.id} className="flex items-center gap-3 group/step">
                                                                <button onClick={() => toggleSubTask(cat.id, task.id, st.id)} className={`w-4 h-4 rounded-lg border flex items-center justify-center transition-all ${st.isCompleted ? (activePeriod === 'five_year' ? 'bg-purple-400 border-purple-400' : (activePeriod === 'yearly' ? 'bg-rose-400 border-rose-400' : 'bg-indigo-400 border-indigo-400')) + ' text-white' : 'border-gray-300 bg-white hover:border-indigo-200'}`}>{st.isCompleted && <IconCheck className="w-2.5 h-2.5" />}</button>
                                                                <span className={`text-[11px] font-bold flex-grow ${st.isCompleted ? 'text-gray-300 line-through' : 'text-gray-600'}`}>{st.text}</span>
                                                                <button onClick={() => { const updated = task.subTasks?.filter(s => s.id !== st.id); const updatedGoals = { ...currentUserGoals, categories: currentUserGoals.categories.map(c => c.id === cat.id ? { ...c, tasks: c.tasks.map(t => t.id === task.id ? { ...t, subTasks: updated } : t) } : c), lastUpdated: new Date().toISOString() }; setCurrentUserGoals(updatedGoals); saveUserGoals(updatedGoals); }} className="text-red-200 hover:text-red-500 opacity-0 group-hover/step:opacity-100 transition-opacity">✕</button>
                                                            </div>
                                                        ))}
                                                        <input className="w-full bg-gray-50 border border-gray-100 rounded-xl px-4 py-2 text-[10px] font-bold outline-none focus:bg-white focus:ring-1 focus:ring-indigo-100 transition-all" placeholder={t.addSubTask} onKeyDown={(e) => { if (e.key === 'Enter' && (e.target as HTMLInputElement).value.trim()) { handleAddSubTask(cat.id, task.id, (e.target as HTMLInputElement).value); (e.target as HTMLInputElement).value = ''; } }} />
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                                {cat.tasks.length === 0 && <div className="h-full flex flex-col items-center justify-center text-center py-16 opacity-30"><IconTarget className="w-8 h-8 text-gray-200 mb-3" /><span className="text-[10px] font-black text-gray-300 uppercase tracking-widest">{t.empty}</span></div>}
                            </div>
                            {canEdit && (
                                <div className="p-5 border-t border-gray-50">
                                    <button onClick={() => handleAddTask(cat.id)} className={`w-full py-3 rounded-[1.5rem] border-2 border-dashed border-gray-200 text-gray-400 font-black text-[11px] uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${activePeriod === 'five_year' ? 'hover:border-purple-300 hover:text-purple-600 hover:bg-purple-50' : (activePeriod === 'yearly' ? 'hover:border-rose-300 hover:text-rose-600 hover:bg-rose-50' : 'hover:border-indigo-300 hover:text-indigo-600 hover:bg-indigo-50')}`}>
                                        <IconPlus className="w-4 h-4" /> {t.addGoal}
                                    </button>
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>

            {/* --- EXCLUSIVE PRINT POSTER (REDESIGNED FOR VISIBILITY) --- */}
            <div id="goal-poster-print" className="hidden print:flex flex-col h-[287mm] w-[200mm] mx-auto bg-white overflow-hidden p-0 relative border-[12px] print-container shadow-none">
                 {/* Decorative background for print */}
                 <div className="absolute top-0 right-0 w-80 h-80 rounded-bl-full bg-gray-50 -z-10 opacity-50"></div>
                 <div className="absolute bottom-0 left-0 w-64 h-64 rounded-tr-full bg-gray-50 -z-10 opacity-50"></div>

                 {/* Banner */}
                 <div className={`p-10 flex items-center justify-between text-white ${activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600' : 'bg-indigo-600')}`}>
                    <div className="flex items-center gap-8">
                        <div className="w-28 h-28 rounded-[2rem] bg-white border-4 border-white/50 overflow-hidden shadow-2xl flex items-center justify-center">
                            {selectedPerson?.avatar ? <img src={selectedPerson.avatar} className="w-full h-full object-cover" /> : <span className="text-4xl font-black text-gray-300">{selectedPerson?.fullName.charAt(0)}</span>}
                        </div>
                        <div>
                            <h1 className="text-3xl font-black mb-2">{selectedPerson?.fullName}</h1>
                            <div className="flex gap-2">
                                {selectedPerson?.roles.map(r => <span key={r} className="bg-white/20 px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider border border-white/20">{r}</span>)}
                            </div>
                        </div>
                    </div>
                    <div className="text-left flex flex-col items-end">
                        <div className="text-5xl font-black opacity-30 mb-2">TARGETS</div>
                        <div className="bg-black/10 px-6 py-3 rounded-2xl border border-white/10 text-center">
                            <div className="text-3xl font-black">{stats.percent}%</div>
                            <div className="text-[10px] font-black opacity-70 uppercase tracking-widest">PERFORMANCE</div>
                        </div>
                    </div>
                 </div>

                 {/* Title Row */}
                 <div className="p-10 pb-4 flex justify-between items-end border-b-2 border-gray-100 bg-white">
                    <div>
                        <h2 className={`text-2xl font-black mb-1 ${activePeriod === 'five_year' ? 'text-purple-900' : (activePeriod === 'yearly' ? 'text-rose-900' : 'text-indigo-900')}`}>{t.reportTitle}</h2>
                        <div className="flex items-center gap-3 text-gray-400 font-black text-xs uppercase tracking-widest">
                            {periodIcons[activePeriod]} {t[activePeriod as keyof typeof t.fa]} • {new Date().getFullYear()}
                        </div>
                    </div>
                    <div className="text-left">
                        <div className="text-[9px] font-black text-gray-300 mb-1 uppercase tracking-tighter">DATE ISSUED</div>
                        <div className="text-sm font-black text-gray-800 dir-ltr">{new Date().toLocaleDateString(lang==='fa'?'fa-IR':'en-US')}</div>
                    </div>
                 </div>

                 {/* Grid Content */}
                 <div className="flex-grow p-10 grid grid-cols-2 gap-8 bg-gray-50/20 overflow-hidden">
                    {currentUserGoals?.categories.map((cat) => (
                        <div key={cat.id} className="bg-white rounded-[2rem] border border-gray-200 shadow-sm overflow-hidden flex flex-col max-h-[440px] break-inside-avoid">
                            <div className={`px-6 py-4 border-b-2 font-black text-[11px] text-indigo-900 uppercase tracking-widest bg-gray-50 flex justify-between items-center ${activePeriod === 'five_year' ? 'border-purple-500' : (activePeriod === 'yearly' ? 'border-rose-500' : 'border-indigo-500')}`}>
                                <span>{cat.title}</span>
                                <span className="bg-white px-2 py-0.5 rounded-lg border">{Math.round((cat.tasks.filter(t=>t.isCompleted).length / (cat.tasks.length || 1)) * 100)}%</span>
                            </div>
                            <div className="p-6 space-y-4 overflow-hidden">
                                {cat.tasks.map((task) => (
                                    <div key={task.id} className="flex gap-4">
                                        <div className={`w-4 h-4 rounded-md border mt-1 shrink-0 ${task.isCompleted ? (activePeriod === 'five_year' ? 'bg-purple-600 border-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600 border-rose-600' : 'bg-indigo-600 border-indigo-600')) : 'bg-white border-gray-300'}`}>
                                            {task.isCompleted && <IconCheck className="w-3 h-3 text-white" />}
                                        </div>
                                        <div className="min-w-0">
                                            <div className={`text-[12px] font-black leading-tight ${task.isCompleted ? 'text-gray-300 line-through' : 'text-gray-800'}`}>{task.text}</div>
                                            {task.subTasks && task.subTasks.length > 0 && (
                                                <div className="mt-2 space-y-1.5 pl-4 border-r-2 border-gray-100">
                                                    {task.subTasks.map(st => (
                                                        <div key={st.id} className="text-[10px] font-bold text-gray-400 flex items-center gap-2">
                                                            <div className={`w-1.5 h-1.5 rounded-full ${st.isCompleted ? (activePeriod === 'five_year' ? 'bg-purple-400' : (activePeriod === 'yearly' ? 'bg-rose-400' : 'bg-indigo-400')) : 'bg-gray-200'}`}></div>
                                                            <span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                ))}
                                {cat.tasks.length === 0 && <div className="text-[10px] text-gray-300 italic text-center py-4">No goals recorded</div>}
                            </div>
                        </div>
                    ))}
                 </div>

                 {/* Footer */}
                 <div className="p-10 border-t-2 border-gray-100 flex justify-between items-center bg-white shrink-0">
                    <div className="max-w-[70%]">
                        <p className="text-[11px] font-black text-indigo-600 uppercase tracking-[0.2em] mb-2">MOTIVATIONAL VISION</p>
                        <p className="text-xs font-black text-gray-500 italic leading-relaxed">"{t.visionNote}"</p>
                    </div>
                    <div className="text-left flex flex-col items-end">
                        <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-2 shadow-xl ${activePeriod === 'five_year' ? 'bg-purple-600 shadow-purple-200' : (activePeriod === 'yearly' ? 'bg-rose-600 shadow-rose-200' : 'bg-indigo-600 shadow-indigo-200')}`}>
                            <IconShield className="w-7 h-7 text-white" />
                        </div>
                        <span className="text-[8px] font-black text-gray-300 uppercase tracking-widest">SMART CRM PERFORMANCE</span>
                    </div>
                 </div>
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 4px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }

                @media print {
                    @page { size: A4; margin: 0; }

                    /* NEW PRINT STRATEGY: Hide body visibility, force visible for target */
                    body { 
                        visibility: hidden !important; 
                        background: white !important; 
                        margin: 0 !important; 
                        padding: 0 !important;
                    }

                    /* Hide root container completely from print flow */
                    .print\\:hidden, #root > div:not(.goal-tracker-root), header, nav, aside, footer {
                        display: none !important;
                    }

                    /* BRUTE FORCE POSTER VISIBILITY */
                    #goal-poster-print { 
                        visibility: visible !important;
                        display: flex !important;
                        position: fixed !important;
                        left: 0 !important;
                        top: 0 !important;
                        width: 210mm !important; /* Force A4 width */
                        height: 297mm !important; /* Force A4 height */
                        margin: 0 !important;
                        z-index: 99999 !important;
                        border: 15px solid currentColor !important;
                    }

                    #goal-poster-print * { 
                        visibility: visible !important; 
                        -webkit-print-color-adjust: exact !important;
                        print-color-adjust: exact !important;
                    }

                    /* Special hack for Tailwind background colors in print */
                    .bg-purple-600 { background-color: #9333ea !important; }
                    .bg-rose-600 { background-color: #e11d48 !important; }
                    .bg-indigo-600 { background-color: #4f46e5 !important; }
                    .bg-gray-50 { background-color: #f9fafb !important; }
                }
            `}</style>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconCalendar, IconChart, IconShield, IconBrain, IconArrowRight, IconActivity, IconBriefcase, IconUsers, IconPrinter, IconAward, IconTrendingUp, IconClock } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف کاری (Business)', color: 'bg-blue-50 border-blue-200 text-blue-700 header-blue', type: 'business' as const },
    { id: 'cat2', title: 'توسعه فردی (Personal)', color: 'bg-emerald-50 border-emerald-200 text-emerald-700 header-green', type: 'personal' as const },
    { id: 'cat3', title: 'سلامتی و لایف‌استایل', color: 'bg-orange-50 border-orange-200 text-orange-700 header-orange', type: 'personal' as const },
    { id: 'cat4', title: 'اهداف مالی', color: 'bg-rose-50 border-rose-200 text-rose-700 header-rose', type: 'personal' as const },
    { id: 'cat5', title: 'سایر موارد', color: 'bg-purple-50 border-purple-200 text-purple-700 header-purple', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [editingTitleId, setEditingTitleId] = useState<string | null>(null);
    const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

    const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');
    const canEdit = selectedUserId === currentUser.id;

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => {
            c.tasks.forEach(t => {
                total++;
                if (t.isCompleted) done++;
            });
        });
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const t = {
        fa: {
            title: 'ردیاب اهداف هوشمند',
            daily: 'امروز',
            weekly: 'هفتگی',
            monthly: 'ماهانه',
            yearly: 'سالانه',
            five_year: '۵ ساله',
            viewMode: 'درحال مشاهده:',
            business: 'اهداف کاری',
            personal: 'توسعه فردی',
            addGoal: 'افزودن هدف جدید',
            editTitle: 'ویرایش عنوان',
            saveTitle: 'ذخیره',
            done: 'انجام شد',
            total: 'کل',
            progress: 'پیشرفت',
            empty: 'هدفی ثبت نشده است.',
            masterView: 'مشاهده اهداف:',
            lastUpdate: 'آخرین بروزرسانی:',
            smartNote: 'اهداف باید هوشمند (SMART) باشند.',
            addSubTask: 'افزودن گام اجرایی...',
            breakDown: 'خرد کردن هدف',
            print: 'چاپ پستر اختصاصی (A4)',
            reportTitle: 'برنامه راهبردی و اهداف بلندمدت',
            visionNote: 'رویاهای بزرگ داشته باشید، اما از قدم‌های کوچک شروع کنید.'
        },
        en: {
            title: 'SMART Goal Tracker',
            daily: 'Daily',
            weekly: 'Weekly',
            monthly: 'Monthly',
            yearly: 'Yearly',
            five_year: '5-Year',
            viewMode: 'Current View:',
            business: 'Business Goals',
            personal: 'Personal Development',
            addGoal: 'Add Goal',
            editTitle: 'Edit Title',
            saveTitle: 'Save',
            done: 'Done',
            total: 'Total',
            progress: 'Progress',
            empty: 'No goals set yet.',
            masterView: 'View Staff Goals:',
            lastUpdate: 'Last Updated:',
            smartNote: 'Specific, Measurable, Achievable, Relevant, Time-bound',
            addSubTask: 'Add step...',
            breakDown: 'Break down',
            print: 'Print Goal Poster',
            reportTitle: 'Strategic Plan & Vision',
            visionNote: 'Dream big, but start small.'
        }
    }[lang];

    const selectedPerson = useMemo(() => personnel.find(p => p.id === selectedUserId), [personnel, selectedUserId]);

    const handleAddTask = (catId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const taskText = window.prompt(lang === 'fa' ? 'عنوان هدف را وارد کنید:' : 'Enter goal title:');
        if (!taskText) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: taskText, isCompleted: false, subTasks: [] }] } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const newCompleted = !t.isCompleted; return { ...t, isCompleted: newCompleted, subTasks: t.subTasks?.map(st => ({ ...st, isCompleted: newCompleted })) }; } return t; }) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleAddSubTask = (catId: string, taskId: string, text: string) => {
        if (!canEdit || !currentUserGoals || !text.trim()) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, subTasks: [...(t.subTasks || []), { id: `st-${Date.now()}`, text, isCompleted: false }], isCompleted: false } : t) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleSubTask = (catId: string, taskId: string, subId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const updatedSubTasks = t.subTasks?.map(st => st.id === subId ? { ...st, isCompleted: !st.isCompleted } : st); return { ...t, subTasks: updatedSubTasks, isCompleted: updatedSubTasks?.every(st => st.isCompleted) || false }; } return t; }) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const removeTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals || !window.confirm('حذف هدف؟')) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.filter(t => t.id !== taskId) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleUpdateCategoryTitle = (catId: string, newTitle: string) => {
        if (!canEdit || !currentUserGoals || !newTitle.trim()) { setEditingTitleId(null); return; }
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, title: newTitle } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
        setEditingTitleId(null);
    };

    const calculateTaskProgress = (task: GoalTask) => {
        if (!task.subTasks || task.subTasks.length === 0) return task.isCompleted ? 100 : 0;
        return Math.round((task.subTasks.filter(st => st.isCompleted).length / task.subTasks.length) * 100);
    };

    const handlePrint = () => {
        window.print();
    };

    if (isLoading) return <div className="p-8 text-center animate-pulse text-indigo-600 font-bold">در حال بارگذاری اهداف...</div>;

    const periodIcons: Record<string, React.ReactNode> = {
        daily: <IconClock className="w-4 h-4" />,
        weekly: <IconCalendar className="w-4 h-4" />,
        monthly: <IconActivity className="w-4 h-4" />,
        yearly: <IconAward className="w-4 h-4" />,
        five_year: <IconTrendingUp className="w-4 h-4" />
    };

    const navItems = [
        { id: 'daily', activeColor: 'bg-blue-600', hoverColor: 'hover:text-blue-600' },
        { id: 'weekly', activeColor: 'bg-green-600', hoverColor: 'hover:text-green-600' },
        { id: 'monthly', activeColor: 'bg-orange-600', hoverColor: 'hover:text-orange-600' },
        { id: 'yearly', activeColor: 'bg-rose-600', hoverColor: 'hover:text-rose-600' },
        { id: 'five_year', activeColor: 'bg-purple-600', hoverColor: 'hover:text-purple-600' }
    ];

    return (
        <div className="space-y-8 goal-tracker-wrapper">
            {/* --- WEB UI (HIDDEN ON PRINT) --- */}
            <div className="space-y-8 animate-fade-in print:hidden">
                <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-gray-100 flex flex-col lg:flex-row gap-8 items-center relative overflow-hidden">
                    <div className={`absolute top-0 right-0 w-48 h-48 rounded-bl-full -z-10 opacity-10 ${activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600' : 'bg-indigo-600')}`}></div>
                    <div className="shrink-0 w-full lg:w-1/3">
                        <h2 className="text-3xl font-black text-gray-900 mb-1 uppercase tracking-tight">{t.title}</h2>
                        <div className="flex items-center gap-2 mb-6">
                            <span className="text-xs font-bold text-gray-400">{t.viewMode}</span>
                            <span className={`px-2 py-0.5 rounded-lg text-[10px] font-black text-white ${navItems.find(n => n.id === activePeriod)?.activeColor}`}>
                                {t[activePeriod as keyof typeof t.fa]}
                            </span>
                        </div>
                        <div className="bg-gray-100 p-1.5 rounded-2xl mb-6 grid grid-cols-5 gap-1.5 border border-gray-200 shadow-inner">
                            {navItems.map(btn => (
                                <button key={btn.id} onClick={() => { setActivePeriod(btn.id as GoalPeriod); setExpandedTaskId(null); }} className={`flex flex-col items-center justify-center py-3 rounded-xl transition-all duration-300 ${activePeriod === btn.id ? `${btn.activeColor} text-white shadow-lg scale-105 z-10` : `text-gray-500 ${btn.hoverColor} hover:bg-white`}`}>
                                    <div className="mb-1">{periodIcons[btn.id]}</div>
                                    <span className="text-[9px] font-black uppercase whitespace-nowrap">{t[btn.id as keyof typeof t.fa]}</span>
                                </button>
                            ))}
                        </div>
                        <div className="flex flex-col gap-3">
                            {isMaster && (
                                <select className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm font-bold" value={selectedUserId} onChange={(e) => setSelectedUserId(e.target.value)}>
                                    {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                                </select>
                            )}
                            <button onClick={handlePrint} className={`w-full py-3.5 text-white rounded-2xl text-xs font-black flex items-center justify-center gap-2 transition-all shadow-lg ${activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600' : 'bg-indigo-600')}`}>
                                <IconPrinter className="w-4 h-4" /> {t.print}
                            </button>
                        </div>
                    </div>
                    <div className="flex flex-col items-center gap-2 lg:border-r lg:px-10 border-gray-100">
                        <div className="relative w-36 h-36 flex items-center justify-center">
                            <svg className="w-full h-full transform -rotate-90"><circle cx="72" cy="72" r="62" stroke="currentColor" strokeWidth="12" fill="transparent" className="text-gray-100" /><circle cx="72" cy="72" r="62" stroke="currentColor" strokeWidth="12" fill="transparent" strokeDasharray={389.557} strokeDashoffset={389.557 - (stats.percent / 100) * 389.557} className={`transition-all duration-1000 ease-out ${activePeriod === 'five_year' ? 'text-purple-600' : (activePeriod === 'yearly' ? 'text-rose-600' : 'text-indigo-600')}`} /></svg>
                            <div className="absolute inset-0 flex flex-col items-center justify-center"><span className="text-3xl font-black text-gray-900">{stats.percent}%</span><span className="text-[9px] font-black text-gray-400 uppercase">{t.progress}</span></div>
                        </div>
                    </div>
                    <div className="flex-grow grid grid-cols-2 sm:grid-cols-3 gap-4 w-full">
                        {currentUserGoals?.categories.map(cat => {
                            const catProgress = cat.tasks.length > 0 ? Math.round((cat.tasks.filter(t => t.isCompleted).length / cat.tasks.length) * 100) : 0;
                            return (
                                <div key={cat.id} className="bg-gray-50 p-4 rounded-3xl flex flex-col justify-center border border-gray-100">
                                    <div className="text-[9px] font-black text-gray-400 uppercase truncate mb-2">{cat.title}</div>
                                    <div className="flex items-center justify-between gap-3"><div className="flex-grow bg-gray-200 h-2 rounded-full overflow-hidden"><div className={`h-full rounded-full bg-indigo-500`} style={{ width: `${catProgress}%` }}></div></div><span className="text-[11px] font-black text-gray-700">{catProgress}%</span></div>
                                </div>
                            );
                        })}
                    </div>
                </div>

                {/* Goals Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-5 gap-6">
                    {currentUserGoals?.categories.map((cat) => (
                        <div key={cat.id} className={`bg-white rounded-[2.5rem] border border-gray-100 shadow-lg overflow-hidden flex flex-col min-h-[500px] transition-all duration-500 ${activePeriod === 'five_year' ? 'ring-2 ring-purple-100' : (activePeriod === 'yearly' ? 'ring-2 ring-rose-100' : '')}`}>
                            <div className={`p-5 text-center text-white font-black text-xs uppercase tracking-widest ${cat.color.split(' ').find(c => c.startsWith('header-')) === 'header-purple' ? 'bg-purple-500' : (cat.color.split(' ').find(c => c.startsWith('header-')) === 'header-rose' ? 'bg-rose-500' : 'bg-indigo-500')}`}>
                                {editingTitleId === cat.id ? <input autoFocus className="w-full bg-white/20 px-2 py-1 rounded" defaultValue={cat.title} onBlur={e => handleUpdateCategoryTitle(cat.id, e.target.value)} /> : <span onClick={() => canEdit && setEditingTitleId(cat.id)}>{cat.title}</span>}
                            </div>
                            <div className="flex-grow overflow-y-auto p-4 space-y-4">
                                {cat.tasks.map((task) => (
                                    <div key={task.id} className={`flex flex-col rounded-3xl border p-4 ${task.isCompleted ? 'bg-gray-50/50 opacity-60' : 'bg-white shadow-sm'}`}>
                                        <div className="flex items-start gap-3">
                                            <button onClick={() => toggleTask(cat.id, task.id)} className={`w-6 h-6 rounded-xl border-2 flex items-center justify-center shrink-0 ${task.isCompleted ? 'bg-indigo-600 border-indigo-600 text-white' : 'border-gray-200'}`}>{task.isCompleted && <IconCheck className="w-4 h-4" />}</button>
                                            <span onClick={() => setExpandedTaskId(expandedTaskId === task.id ? null : task.id)} className={`text-[12px] font-black cursor-pointer ${task.isCompleted ? 'line-through text-gray-400' : 'text-gray-800'}`}>{task.text}</span>
                                        </div>
                                        {expandedTaskId === task.id && (
                                            <div className="mt-4 space-y-2 pl-4 border-r-2 border-gray-100">
                                                {task.subTasks?.map(st => (
                                                    <div key={st.id} className="flex items-center gap-2 text-[11px] font-bold text-gray-600"><button onClick={() => toggleSubTask(cat.id, task.id, st.id)} className={`w-4 h-4 rounded border flex items-center justify-center ${st.isCompleted ? 'bg-indigo-400 text-white' : 'bg-white'}`}>{st.isCompleted && <IconCheck className="w-3 h-3" />}</button><span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span></div>
                                                ))}
                                                <input className="w-full text-[10px] p-2 bg-gray-50 rounded-lg outline-none" placeholder={t.addSubTask} onKeyDown={e => { if (e.key === 'Enter' && (e.target as HTMLInputElement).value.trim()) { handleAddSubTask(cat.id, task.id, (e.target as HTMLInputElement).value); (e.target as HTMLInputElement).value = ''; } }} />
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                            {canEdit && (
                                <div className="p-4 border-t"><button onClick={() => handleAddTask(cat.id)} className="w-full py-2 border-2 border-dashed rounded-xl text-gray-400 text-[11px] font-black hover:text-indigo-600 hover:border-indigo-300 transition-colors flex items-center justify-center gap-2"><IconPlus className="w-4 h-4" /> {t.addGoal}</button></div>
                            )}
                        </div>
                    ))}
                </div>
            </div>

            {/* --- EXCLUSIVE PRINT POSTER (SHOWN ONLY ON PRINT) --- */}
            <div id="goal-poster-print" className={`hidden print:flex flex-col bg-white overflow-hidden relative border-[15px] ${activePeriod === 'five_year' ? 'border-purple-600' : (activePeriod === 'yearly' ? 'border-rose-600' : 'border-indigo-600')}`}>
                 {/* Print Header */}
                 <div className={`p-12 flex items-center justify-between text-white ${activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600' : 'bg-indigo-600')}`} style={{ printColorAdjust: 'exact', WebkitPrintColorAdjust: 'exact' }}>
                    <div className="flex items-center gap-8">
                        <div className="w-32 h-32 rounded-[2.5rem] bg-white border-4 border-white/50 flex items-center justify-center overflow-hidden shadow-2xl">
                            {selectedPerson?.avatar ? <img src={selectedPerson.avatar} className="w-full h-full object-cover" /> : <span className="text-5xl font-black text-gray-300">{selectedPerson?.fullName.charAt(0)}</span>}
                        </div>
                        <div>
                            <h1 className="text-4xl font-black mb-3">{selectedPerson?.fullName}</h1>
                            <div className="flex gap-2">
                                {selectedPerson?.roles.map(r => <span key={r} className="bg-white/20 px-4 py-1.5 rounded-xl text-[12px] font-black uppercase border border-white/20">{r}</span>)}
                            </div>
                        </div>
                    </div>
                    <div className="text-right flex flex-col items-end">
                        <div className="text-6xl font-black opacity-30 mb-2">TARGETS</div>
                        <div className="bg-black/10 px-8 py-4 rounded-3xl border border-white/10 text-center">
                            <div className="text-4xl font-black">{stats.percent}%</div>
                            <div className="text-[11px] font-black opacity-70 uppercase tracking-widest">OVERALL PERFORMANCE</div>
                        </div>
                    </div>
                 </div>

                 {/* Sub Header */}
                 <div className="p-12 pb-6 flex justify-between items-end border-b-4 border-gray-100">
                    <div>
                        <h2 className={`text-3xl font-black mb-2 ${activePeriod === 'five_year' ? 'text-purple-900' : (activePeriod === 'yearly' ? 'text-rose-900' : 'text-indigo-900')}`}>{t.reportTitle}</h2>
                        <div className="flex items-center gap-4 text-gray-400 font-black text-sm uppercase tracking-widest">
                            {periodIcons[activePeriod]} {t[activePeriod as keyof typeof t.fa]} STRATEGY • {new Date().getFullYear()}
                        </div>
                    </div>
                    <div className="text-right">
                        <div className="text-[10px] font-black text-gray-300 mb-1 uppercase">DATE GENERATED</div>
                        <div className="text-lg font-black text-gray-800 dir-ltr">{new Date().toLocaleDateString(lang==='fa'?'fa-IR':'en-US')}</div>
                    </div>
                 </div>

                 {/* Print Content Grid */}
                 <div className="flex-grow p-12 grid grid-cols-2 gap-10 bg-gray-50/30 overflow-hidden">
                    {currentUserGoals?.categories.map((cat) => (
                        <div key={cat.id} className="bg-white rounded-[3rem] border border-gray-200 shadow-sm flex flex-col overflow-hidden break-inside-avoid">
                            <div className={`px-8 py-5 border-b-4 font-black text-[13px] text-gray-700 uppercase tracking-widest bg-gray-50 flex justify-between items-center ${activePeriod === 'five_year' ? 'border-purple-600' : (activePeriod === 'yearly' ? 'border-rose-600' : 'border-indigo-600')}`} style={{ printColorAdjust: 'exact', WebkitPrintColorAdjust: 'exact' }}>
                                <span>{cat.title}</span>
                                <span className="bg-white px-3 py-1 rounded-xl border font-black">{Math.round((cat.tasks.filter(t=>t.isCompleted).length / (cat.tasks.length || 1)) * 100)}%</span>
                            </div>
                            <div className="p-8 space-y-6">
                                {cat.tasks.map((task) => (
                                    <div key={task.id} className="flex gap-5">
                                        <div className={`w-5 h-5 rounded-lg border-2 mt-1 shrink-0 flex items-center justify-center ${task.isCompleted ? (activePeriod === 'five_year' ? 'bg-purple-600 border-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600 border-rose-600' : 'bg-indigo-600 border-indigo-600')) : 'bg-white border-gray-300'}`} style={{ printColorAdjust: 'exact', WebkitPrintColorAdjust: 'exact' }}>
                                            {task.isCompleted && <IconCheck className="w-4 h-4 text-white" />}
                                        </div>
                                        <div className="flex-grow min-w-0">
                                            <div className={`text-sm font-black leading-snug ${task.isCompleted ? 'text-gray-300 line-through' : 'text-gray-800'}`}>{task.text}</div>
                                            {task.subTasks && task.subTasks.length > 0 && (
                                                <div className="mt-3 space-y-2 pl-6 border-r-2 border-gray-100">
                                                    {task.subTasks.map(st => (
                                                        <div key={st.id} className="text-[12px] font-bold text-gray-400 flex items-center gap-3">
                                                            <div className={`w-2 h-2 rounded-full ${st.isCompleted ? 'bg-indigo-400' : 'bg-gray-200'}`} style={{ printColorAdjust: 'exact', WebkitPrintColorAdjust: 'exact' }}></div>
                                                            <span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    ))}
                 </div>

                 {/* Print Footer */}
                 <div className="p-12 border-t-4 border-gray-100 flex justify-between items-center bg-white shrink-0">
                    <div className="max-w-[70%]">
                        <p className="text-[13px] font-black text-indigo-600 uppercase tracking-[0.3em] mb-3">MOTIVATIONAL VISION</p>
                        <p className="text-sm font-black text-gray-500 italic leading-relaxed">"{t.visionNote}"</p>
                    </div>
                    <div className="text-right flex flex-col items-end">
                        <div className={`w-16 h-16 rounded-3xl flex items-center justify-center mb-3 shadow-2xl ${activePeriod === 'five_year' ? 'bg-purple-600 shadow-purple-200' : (activePeriod === 'yearly' ? 'bg-rose-600 shadow-rose-200' : 'bg-indigo-600 shadow-indigo-200')}`} style={{ printColorAdjust: 'exact', WebkitPrintColorAdjust: 'exact' }}>
                            <IconShield className="w-8 h-8 text-white" />
                        </div>
                        <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.2em]">SMART CRM PERFORMANCE</span>
                    </div>
                 </div>
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 4px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }

                @media print {
                    @page { 
                        size: A4; 
                        margin: 0; 
                    }

                    /* Hide EVERYTHING in the DOM except our specific wrapper */
                    body > *:not(.goal-tracker-wrapper) {
                        display: none !important;
                    }

                    /* If inside a deep React tree, hide all parents' siblings */
                    #root, #root > div, main {
                        display: block !important;
                        margin: 0 !important;
                        padding: 0 !important;
                        overflow: visible !important;
                    }

                    header, nav, footer, .fixed, .print\\:hidden {
                        display: none !important;
                        visibility: hidden !important;
                    }

                    /* THE POSTER ITSELF - FORCE A4 DIMENSIONS */
                    #goal-poster-print { 
                        display: flex !important; 
                        visibility: visible !important;
                        width: 210mm !important;
                        height: 297mm !important;
                        margin: 0 auto !important;
                        padding: 0 !important;
                        border: none !important;
                        overflow: hidden !important;
                        page-break-after: always;
                    }

                    #goal-poster-print * { 
                        visibility: visible !important; 
                        -webkit-print-color-adjust: exact !important;
                        print-color-adjust: exact !important;
                    }

                    /* Force colors for common backgrounds */
                    .bg-purple-600 { background-color: #9333ea !important; }
                    .bg-rose-600 { background-color: #e11d48 !important; }
                    .bg-indigo-600 { background-color: #4f46e5 !important; }
                    .bg-gray-50 { background-color: #f9fafb !important; }
                    .bg-indigo-50 { background-color: #eef2ff !important; }
                    .bg-black\\/10 { background-color: rgba(0,0,0,0.1) !important; }
                }
            `}</style>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconCalendar, IconChart, IconShield, IconBrain, IconArrowRight, IconActivity, IconBriefcase, IconUsers, IconPrinter, IconAward, IconTrendingUp, IconClock } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف کاری (Business)', color: 'bg-blue-50 border-blue-200 text-blue-700 header-blue', type: 'business' as const },
    { id: 'cat2', title: 'توسعه فردی (Personal)', color: 'bg-emerald-50 border-emerald-200 text-emerald-700 header-green', type: 'personal' as const },
    { id: 'cat3', title: 'سلامتی و لایف‌استایل', color: 'bg-orange-50 border-orange-200 text-orange-700 header-orange', type: 'personal' as const },
    { id: 'cat4', title: 'اهداف مالی', color: 'bg-rose-50 border-rose-200 text-rose-700 header-rose', type: 'personal' as const },
    { id: 'cat5', title: 'سایر موارد', color: 'bg-purple-50 border-purple-200 text-purple-700 header-purple', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [editingTitleId, setEditingTitleId] = useState<string | null>(null);
    const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

    const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');
    const canEdit = selectedUserId === currentUser.id;

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => {
            c.tasks.forEach(t => {
                total++;
                if (t.isCompleted) done++;
            });
        });
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const t = {
        fa: {
            title: 'ردیاب اهداف هوشمند',
            daily: 'امروز',
            weekly: 'هفتگی',
            monthly: 'ماهانه',
            yearly: 'سالانه',
            five_year: '۵ ساله',
            viewMode: 'درحال مشاهده:',
            business: 'اهداف کاری',
            personal: 'توسعه فردی',
            addGoal: 'افزودن هدف جدید',
            editTitle: 'ویرایش عنوان',
            saveTitle: 'ذخیره',
            done: 'انجام شد',
            total: 'کل',
            progress: 'پیشرفت',
            empty: 'هدفی ثبت نشده است.',
            masterView: 'مشاهده اهداف:',
            lastUpdate: 'آخرین بروزرسانی:',
            smartNote: 'اهداف باید هوشمند (SMART) باشند.',
            addSubTask: 'افزودن گام اجرایی...',
            breakDown: 'خرد کردن هدف',
            print: 'دریافت خروجی پستر (A4)',
            reportTitle: 'سند استراتژیک و اهداف کلیدی',
            visionNote: 'رویاهای بزرگ داشته باشید، اما از قدم‌های کوچک شروع کنید.'
        },
        en: {
            title: 'SMART Goal Tracker',
            daily: 'Daily',
            weekly: 'Weekly',
            monthly: 'Monthly',
            yearly: 'Yearly',
            five_year: '5-Year',
            viewMode: 'Current View:',
            business: 'Business Goals',
            personal: 'Personal Development',
            addGoal: 'Add Goal',
            editTitle: 'Edit Title',
            saveTitle: 'Save',
            done: 'Done',
            total: 'Total',
            progress: 'Progress',
            empty: 'No goals set yet.',
            masterView: 'View Staff Goals:',
            lastUpdate: 'Last Updated:',
            smartNote: 'Specific, Measurable, Achievable, Relevant, Time-bound',
            addSubTask: 'Add step...',
            breakDown: 'Break down',
            print: 'Export Poster (A4)',
            reportTitle: 'Strategic Vision & Goals',
            visionNote: 'Dream big, but start small.'
        }
    }[lang];

    const selectedPerson = useMemo(() => personnel.find(p => p.id === selectedUserId), [personnel, selectedUserId]);

    const handleAddTask = (catId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const taskText = window.prompt(lang === 'fa' ? 'عنوان هدف را وارد کنید:' : 'Enter goal title:');
        if (!taskText) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: taskText, isCompleted: false, subTasks: [] }] } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const newCompleted = !t.isCompleted; return { ...t, isCompleted: newCompleted, subTasks: t.subTasks?.map(st => ({ ...st, isCompleted: newCompleted })) }; } return t; }) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleAddSubTask = (catId: string, taskId: string, text: string) => {
        if (!canEdit || !currentUserGoals || !text.trim()) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, subTasks: [...(t.subTasks || []), { id: `st-${Date.now()}`, text, isCompleted: false }], isCompleted: false } : t) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleSubTask = (catId: string, taskId: string, subId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const updatedSubTasks = t.subTasks?.map(st => st.id === subId ? { ...st, isCompleted: !st.isCompleted } : st); return { ...t, subTasks: updatedSubTasks, isCompleted: updatedSubTasks?.every(st => st.isCompleted) || false }; } return t; }) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const removeTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals || !window.confirm('حذف هدف؟')) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.filter(t => t.id !== taskId) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleUpdateCategoryTitle = (catId: string, newTitle: string) => {
        if (!canEdit || !currentUserGoals || !newTitle.trim()) { setEditingTitleId(null); return; }
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, title: newTitle } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
        setEditingTitleId(null);
    };

    const calculateTaskProgress = (task: GoalTask) => {
        if (!task.subTasks || task.subTasks.length === 0) return task.isCompleted ? 100 : 0;
        return Math.round((task.subTasks.filter(st => st.isCompleted).length / task.subTasks.length) * 100);
    };

    const handlePrint = () => {
        window.print();
    };

    if (isLoading) return <div className="p-8 text-center animate-pulse text-indigo-600 font-bold">در حال بارگذاری سیستم اهداف...</div>;

    const periodIcons: Record<string, React.ReactNode> = {
        daily: <IconClock className="w-4 h-4" />,
        weekly: <IconCalendar className="w-4 h-4" />,
        monthly: <IconActivity className="w-4 h-4" />,
        yearly: <IconAward className="w-4 h-4" />,
        five_year: <IconTrendingUp className="w-4 h-4" />
    };

    const navItems = [
        { id: 'daily', activeColor: 'bg-blue-600', hoverColor: 'hover:text-blue-600' },
        { id: 'weekly', activeColor: 'bg-green-600', hoverColor: 'hover:text-green-600' },
        { id: 'monthly', activeColor: 'bg-orange-600', hoverColor: 'hover:text-orange-600' },
        { id: 'yearly', activeColor: 'bg-rose-600', hoverColor: 'hover:text-rose-600' },
        { id: 'five_year', activeColor: 'bg-purple-600', hoverColor: 'hover:text-purple-600' }
    ];

    return (
        <div className="goal-tracker-main-container">
            {/* --- WEB INTERFACE (HIDDEN ON PRINT) --- */}
            <div className="space-y-8 animate-fade-in print:hidden pb-12">
                <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-gray-100 flex flex-col lg:flex-row gap-8 items-center relative overflow-hidden">
                    <div className={`absolute top-0 right-0 w-48 h-48 rounded-bl-full -z-10 opacity-10 ${activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600' : 'bg-indigo-600')}`}></div>
                    <div className="shrink-0 w-full lg:w-1/3">
                        <h2 className="text-3xl font-black text-gray-900 mb-1 uppercase tracking-tight">{t.title}</h2>
                        <div className="flex items-center gap-2 mb-6">
                            <span className="text-xs font-bold text-gray-400">{t.viewMode}</span>
                            <span className={`px-2 py-0.5 rounded-lg text-[10px] font-black text-white ${navItems.find(n => n.id === activePeriod)?.activeColor}`}>
                                {t[activePeriod as keyof typeof t.fa]}
                            </span>
                        </div>
                        <div className="bg-gray-100 p-1.5 rounded-2xl mb-6 grid grid-cols-5 gap-1.5 border border-gray-200 shadow-inner">
                            {navItems.map(btn => (
                                <button key={btn.id} onClick={() => { setActivePeriod(btn.id as GoalPeriod); setExpandedTaskId(null); }} className={`flex flex-col items-center justify-center py-3 rounded-xl transition-all duration-300 ${activePeriod === btn.id ? `${btn.activeColor} text-white shadow-lg scale-105 z-10` : `text-gray-500 ${btn.hoverColor} hover:bg-white`}`}>
                                    <div className="mb-1">{periodIcons[btn.id]}</div>
                                    <span className="text-[9px] font-black uppercase whitespace-nowrap">{t[btn.id as keyof typeof t.fa]}</span>
                                </button>
                            ))}
                        </div>
                        <div className="flex flex-col gap-3">
                            {isMaster && (
                                <select className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm font-bold" value={selectedUserId} onChange={(e) => setSelectedUserId(e.target.value)}>
                                    {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                                </select>
                            )}
                            <button onClick={handlePrint} className={`w-full py-3.5 text-white rounded-2xl text-xs font-black flex items-center justify-center gap-2 transition-all shadow-lg hover:brightness-110 active:scale-[0.98] ${activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600' : 'bg-indigo-600')}`}>
                                <IconPrinter className="w-4 h-4" /> {t.print}
                            </button>
                        </div>
                    </div>
                    <div className="flex flex-col items-center gap-2 lg:border-r lg:px-10 border-gray-100">
                        <div className="relative w-36 h-36 flex items-center justify-center">
                            <svg className="w-full h-full transform -rotate-90"><circle cx="72" cy="72" r="62" stroke="currentColor" strokeWidth="12" fill="transparent" className="text-gray-100" /><circle cx="72" cy="72" r="62" stroke="currentColor" strokeWidth="12" fill="transparent" strokeDasharray={389.557} strokeDashoffset={389.557 - (stats.percent / 100) * 389.557} className={`transition-all duration-1000 ease-out ${activePeriod === 'five_year' ? 'text-purple-600' : (activePeriod === 'yearly' ? 'text-rose-600' : 'text-indigo-600')}`} /></svg>
                            <div className="absolute inset-0 flex flex-col items-center justify-center"><span className="text-3xl font-black text-gray-900">{stats.percent}%</span><span className="text-[9px] font-black text-gray-400 uppercase">{t.progress}</span></div>
                        </div>
                    </div>
                    <div className="flex-grow grid grid-cols-2 sm:grid-cols-3 gap-4 w-full">
                        {currentUserGoals?.categories.map(cat => {
                            const catProgress = cat.tasks.length > 0 ? Math.round((cat.tasks.filter(t => t.isCompleted).length / cat.tasks.length) * 100) : 0;
                            return (
                                <div key={cat.id} className="bg-gray-50 p-4 rounded-3xl flex flex-col justify-center border border-gray-100">
                                    <div className="text-[9px] font-black text-gray-400 uppercase truncate mb-2">{cat.title}</div>
                                    <div className="flex items-center justify-between gap-3"><div className="flex-grow bg-gray-200 h-2 rounded-full overflow-hidden"><div className={`h-full rounded-full bg-indigo-500`} style={{ width: `${catProgress}%` }}></div></div><span className="text-[11px] font-black text-gray-700">{catProgress}%</span></div>
                                </div>
                            );
                        })}
                    </div>
                </div>

                {/* Goals Cards (Web) */}
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-5 gap-6">
                    {currentUserGoals?.categories.map((cat) => (
                        <div key={cat.id} className={`bg-white rounded-[2.5rem] border border-gray-100 shadow-lg overflow-hidden flex flex-col min-h-[500px] transition-all duration-500 ${activePeriod === 'five_year' ? 'ring-2 ring-purple-100' : (activePeriod === 'yearly' ? 'ring-2 ring-rose-100' : '')}`}>
                            <div className={`p-5 text-center text-white font-black text-xs uppercase tracking-widest ${cat.color.split(' ').find(c => c.startsWith('header-')) === 'header-purple' ? 'bg-purple-500' : (cat.color.split(' ').find(c => c.startsWith('header-')) === 'header-rose' ? 'bg-rose-500' : 'bg-indigo-500')}`}>
                                {editingTitleId === cat.id ? <input autoFocus className="w-full bg-white/20 px-2 py-1 rounded" defaultValue={cat.title} onBlur={e => handleUpdateCategoryTitle(cat.id, e.target.value)} /> : <span onClick={() => canEdit && setEditingTitleId(cat.id)} className="cursor-pointer hover:underline">{cat.title}</span>}
                            </div>
                            <div className="flex-grow overflow-y-auto p-4 space-y-4">
                                {cat.tasks.map((task) => (
                                    <div key={task.id} className={`flex flex-col rounded-3xl border p-4 ${task.isCompleted ? 'bg-gray-50/50 opacity-60' : 'bg-white shadow-sm'}`}>
                                        <div className="flex items-start gap-3">
                                            <button onClick={() => toggleTask(cat.id, task.id)} className={`w-6 h-6 rounded-xl border-2 flex items-center justify-center shrink-0 ${task.isCompleted ? 'bg-indigo-600 border-indigo-600 text-white' : 'border-gray-200'}`}>{task.isCompleted && <IconCheck className="w-4 h-4" />}</button>
                                            <span onClick={() => setExpandedTaskId(expandedTaskId === task.id ? null : task.id)} className={`text-[12px] font-black cursor-pointer ${task.isCompleted ? 'line-through text-gray-400' : 'text-gray-800'}`}>{task.text}</span>
                                        </div>
                                        {expandedTaskId === task.id && (
                                            <div className="mt-4 space-y-2 pl-4 border-r-2 border-gray-100 animate-slide-in">
                                                {task.subTasks?.map(st => (
                                                    <div key={st.id} className="flex items-center gap-2 text-[11px] font-bold text-gray-600"><button onClick={() => toggleSubTask(cat.id, task.id, st.id)} className={`w-4 h-4 rounded border flex items-center justify-center ${st.isCompleted ? 'bg-indigo-400 text-white' : 'bg-white'}`}>{st.isCompleted && <IconCheck className="w-3 h-3" />}</button><span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span></div>
                                                ))}
                                                <input className="w-full text-[10px] p-2 bg-gray-50 rounded-lg outline-none" placeholder={t.addSubTask} onKeyDown={e => { if (e.key === 'Enter' && (e.target as HTMLInputElement).value.trim()) { handleAddSubTask(cat.id, task.id, (e.target as HTMLInputElement).value); (e.target as HTMLInputElement).value = ''; } }} />
                                            </div>
                                        )}
                                    </div>
                                ))}
                                {cat.tasks.length === 0 && <div className="text-center py-10 opacity-20"><IconTarget className="w-10 h-10 mx-auto" /></div>}
                            </div>
                            {canEdit && (
                                <div className="p-4 border-t bg-gray-50/50"><button onClick={() => handleAddTask(cat.id)} className="w-full py-3 border-2 border-dashed rounded-2xl text-gray-400 text-[11px] font-black hover:text-indigo-600 hover:border-indigo-300 transition-colors flex items-center justify-center gap-2"><IconPlus className="w-4 h-4" /> {t.addGoal}</button></div>
                            )}
                        </div>
                    ))}
                </div>
            </div>

            {/* --- EXCLUSIVE PRINTABLE POSTER (HIDDEN ON WEB) --- */}
            <div id="FINAL_POSTER_PRINT_ID" className="hidden print:flex flex-col bg-white overflow-hidden relative print-a4-canvas">
                {/* Visual Background Decoration */}
                <div className="absolute top-0 right-0 w-96 h-96 bg-gray-50 rounded-bl-full -z-10 opacity-50"></div>
                <div className="absolute bottom-0 left-0 w-80 h-80 bg-gray-50 rounded-tr-full -z-10 opacity-50"></div>

                {/* Poster Header */}
                <div className={`p-16 flex items-center justify-between text-white ${activePeriod === 'five_year' ? 'bg-purple-700' : (activePeriod === 'yearly' ? 'bg-rose-700' : 'bg-indigo-700')}`} style={{ WebkitPrintColorAdjust: 'exact', printColorAdjust: 'exact' }}>
                    <div className="flex items-center gap-10">
                        <div className="w-36 h-36 rounded-[3rem] bg-white p-1 shadow-2xl border-8 border-white/30 overflow-hidden flex items-center justify-center">
                            {selectedPerson?.avatar ? <img src={selectedPerson.avatar} className="w-full h-full object-cover rounded-[2.5rem]" /> : <span className="text-6xl font-black text-gray-300 uppercase">{selectedPerson?.fullName.charAt(0)}</span>}
                        </div>
                        <div>
                            <h1 className="text-5xl font-black mb-3 tracking-tight">{selectedPerson?.fullName}</h1>
                            <div className="flex gap-3">
                                {selectedPerson?.roles.map(r => <span key={r} className="bg-white/20 px-5 py-2 rounded-2xl text-xs font-black uppercase tracking-widest border border-white/20">{r}</span>)}
                            </div>
                        </div>
                    </div>
                    <div className="text-right flex flex-col items-end">
                        <div className="text-[100px] leading-none font-black opacity-10 absolute -right-4 top-0">VISION</div>
                        <div className="bg-black/20 backdrop-blur-md px-10 py-6 rounded-[2.5rem] border border-white/10 text-center relative z-10">
                            <div className="text-5xl font-black leading-none mb-2">{stats.percent}%</div>
                            <div className="text-[10px] font-black opacity-80 uppercase tracking-[0.3em]">OVERALL PROGRESS</div>
                        </div>
                    </div>
                </div>

                {/* Sub Header / Info Bar */}
                <div className="px-16 py-10 flex justify-between items-end border-b-8 border-gray-100 bg-white">
                    <div>
                        <h2 className={`text-4xl font-black mb-2 ${activePeriod === 'five_year' ? 'text-purple-900' : (activePeriod === 'yearly' ? 'text-rose-900' : 'text-indigo-900')}`}>{t.reportTitle}</h2>
                        <div className="flex items-center gap-4 text-gray-400 font-black text-sm uppercase tracking-widest">
                            <div className="bg-gray-100 p-2 rounded-xl">{periodIcons[activePeriod]}</div>
                            <span>PERIOD: {t[activePeriod as keyof typeof t.fa]}</span>
                            <span className="opacity-30">|</span>
                            <span>YEAR: {new Date().getFullYear()}</span>
                        </div>
                    </div>
                    <div className="text-right">
                        <div className="text-[10px] font-black text-gray-300 mb-1 uppercase tracking-tighter">PUBLISHED ON</div>
                        <div className="text-xl font-black text-gray-800 dir-ltr">{new Date().toLocaleDateString(lang==='fa'?'fa-IR':'en-US')}</div>
                    </div>
                </div>

                {/* Poster Content Grid */}
                <div className="flex-grow p-16 grid grid-cols-2 gap-12 bg-gray-50/20 overflow-hidden content-start">
                    {currentUserGoals?.categories.map((cat) => {
                        const progress = Math.round((cat.tasks.filter(t=>t.isCompleted).length / (cat.tasks.length || 1)) * 100);
                        return (
                            <div key={cat.id} className="bg-white rounded-[3.5rem] border-4 border-gray-100 shadow-sm flex flex-col overflow-hidden break-inside-avoid h-fit">
                                <div className={`px-10 py-6 border-b-4 font-black text-[15px] uppercase tracking-widest bg-gray-50 flex justify-between items-center ${activePeriod === 'five_year' ? 'border-purple-600 text-purple-900' : (activePeriod === 'yearly' ? 'border-rose-600 text-rose-900' : 'border-indigo-600 text-indigo-900')}`} style={{ WebkitPrintColorAdjust: 'exact', printColorAdjust: 'exact' }}>
                                    <span>{cat.title}</span>
                                    <div className="bg-white px-4 py-1 rounded-2xl border-2 text-sm">{progress}%</div>
                                </div>
                                <div className="p-10 space-y-8">
                                    {cat.tasks.map((task) => (
                                        <div key={task.id} className="flex gap-6">
                                            <div className={`w-6 h-6 rounded-xl border-4 mt-1 shrink-0 flex items-center justify-center ${task.isCompleted ? (activePeriod === 'five_year' ? 'bg-purple-600 border-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600 border-rose-600' : 'bg-indigo-600 border-indigo-600')) : 'bg-white border-gray-200'}`} style={{ WebkitPrintColorAdjust: 'exact', printColorAdjust: 'exact' }}>
                                                {task.isCompleted && <IconCheck className="w-4 h-4 text-white" />}
                                            </div>
                                            <div className="flex-grow min-w-0">
                                                <div className={`text-base font-black leading-tight ${task.isCompleted ? 'text-gray-300 line-through' : 'text-gray-800'}`}>{task.text}</div>
                                                {task.subTasks && task.subTasks.length > 0 && (
                                                    <div className="mt-4 space-y-2.5 pl-8 border-r-4 border-gray-50">
                                                        {task.subTasks.map(st => (
                                                            <div key={st.id} className="text-xs font-bold text-gray-400 flex items-center gap-3">
                                                                <div className={`w-2.5 h-2.5 rounded-full border-2 ${st.isCompleted ? 'bg-indigo-400 border-indigo-400' : 'bg-white border-gray-200'}`} style={{ WebkitPrintColorAdjust: 'exact', printColorAdjust: 'exact' }}></div>
                                                                <span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span>
                                                            </div>
                                                        ))}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                    {cat.tasks.length === 0 && <div className="text-sm text-gray-300 italic text-center py-6">No records found for this category.</div>}
                                </div>
                            </div>
                        );
                    })}
                </div>

                {/* Poster Footer */}
                <div className="p-16 border-t-8 border-gray-100 flex justify-between items-center bg-white shrink-0">
                    <div className="max-w-[75%]">
                        <p className="text-[15px] font-black text-indigo-600 uppercase tracking-[0.4em] mb-4">MOTIVATIONAL VISION</p>
                        <p className="text-lg font-black text-gray-400 italic leading-relaxed">"{t.visionNote}"</p>
                    </div>
                    <div className="text-left flex flex-col items-end">
                        <div className={`w-20 h-20 rounded-3xl flex items-center justify-center mb-4 shadow-2xl ${activePeriod === 'five_year' ? 'bg-purple-600 shadow-purple-200' : (activePeriod === 'yearly' ? 'bg-rose-600 shadow-rose-200' : 'bg-indigo-600 shadow-indigo-200')}`} style={{ WebkitPrintColorAdjust: 'exact', printColorAdjust: 'exact' }}>
                            <IconShield className="w-10 h-10 text-white" />
                        </div>
                        <span className="text-[9px] font-black text-gray-300 uppercase tracking-[0.3em]">SMART PERFORMANCE POSTER</span>
                    </div>
                </div>
            </div>

            <style>{`
                @media print {
                    @page { 
                        size: A4 portrait; 
                        margin: 0; 
                    }

                    /* THE ULTIMATE FIX: Hide everything in the body except the goal tracker container */
                    body > *:not(.goal-tracker-main-container),
                    #root > *:not(.goal-tracker-main-container),
                    .print\\:hidden, header, nav, footer, aside, .fixed {
                        display: none !important;
                        visibility: hidden !important;
                        height: 0 !important;
                        overflow: hidden !important;
                    }

                    body {
                        margin: 0 !important;
                        padding: 0 !important;
                        background: white !important;
                        width: 210mm !important;
                        height: 297mm !important;
                    }

                    .goal-tracker-main-container {
                        display: block !important;
                        visibility: visible !important;
                        width: 210mm !important;
                        height: 297mm !important;
                        margin: 0 !important;
                        padding: 0 !important;
                    }

                    .print-a4-canvas {
                        display: flex !important;
                        visibility: visible !important;
                        width: 210mm !important;
                        height: 297mm !important;
                        position: absolute !important;
                        left: 0 !important;
                        top: 0 !important;
                        z-index: 99999 !important;
                        border: none !important;
                        -webkit-print-color-adjust: exact !important;
                        print-color-adjust: exact !important;
                    }

                    /* Forcing backgrounds and colors for all browsers */
                    .bg-purple-700 { background-color: #6e21d2 !important; }
                    .bg-rose-700 { background-color: #be123c !important; }
                    .bg-indigo-700 { background-color: #4338ca !important; }
                    .bg-gray-50 { background-color: #f9fafb !important; }
                    .bg-purple-600 { background-color: #9333ea !important; }
                    .bg-rose-600 { background-color: #e11d48 !important; }
                    .bg-indigo-600 { background-color: #4f46e5 !important; }
                    .text-white { color: #ffffff !important; }
                }
            `}</style>
        </div>
    );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconCalendar, IconChart, IconShield, IconBrain, IconArrowRight, IconActivity, IconBriefcase, IconUsers, IconPrinter, IconAward, IconTrendingUp, IconClock } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';
import * as htmlToImage from 'html-to-image';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف کاری (Business)', color: 'bg-blue-50 border-blue-200 text-blue-700 header-blue', type: 'business' as const },
    { id: 'cat2', title: 'توسعه فردی (Personal)', color: 'bg-emerald-50 border-emerald-200 text-emerald-700 header-green', type: 'personal' as const },
    { id: 'cat3', title: 'سلامتی و لایف‌استایل', color: 'bg-orange-50 border-orange-200 text-orange-700 header-orange', type: 'personal' as const },
    { id: 'cat4', title: 'اهداف مالی', color: 'bg-rose-50 border-rose-200 text-rose-700 header-rose', type: 'personal' as const },
    { id: 'cat5', title: 'سایر موارد', color: 'bg-purple-50 border-purple-200 text-purple-700 header-purple', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isExporting, setIsExporting] = useState(false);
    const [editingTitleId, setEditingTitleId] = useState<string | null>(null);
    const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

    const posterRef = useRef<HTMLDivElement>(null);
    const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');
    const canEdit = selectedUserId === currentUser.id;

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => {
            c.tasks.forEach(t => {
                total++;
                if (t.isCompleted) done++;
            });
        });
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const t = {
        fa: {
            title: 'ردیاب اهداف هوشمند',
            daily: 'امروز',
            weekly: 'هفتگی',
            monthly: 'ماهانه',
            yearly: 'سالانه',
            five_year: '۵ ساله',
            viewMode: 'درحال مشاهده:',
            business: 'اهداف کاری',
            personal: 'توسعه فردی',
            addGoal: 'افزودن هدف جدید',
            editTitle: 'ویرایش عنوان',
            saveTitle: 'ذخیره',
            done: 'انجام شد',
            total: 'کل',
            progress: 'پیشرفت',
            empty: 'هدفی ثبت نشده است.',
            masterView: 'مشاهده اهداف:',
            lastUpdate: 'آخرین بروزرسانی:',
            smartNote: 'اهداف باید هوشمند (SMART) باشند.',
            addSubTask: 'افزودن گام اجرایی...',
            breakDown: 'خرد کردن هدف',
            print: 'دریافت فایل پستر (عکس A4)',
            exporting: 'در حال تولید عکس...',
            reportTitle: 'سند استراتژیک و اهداف کلیدی',
            visionNote: 'رویاهای بزرگ داشته باشید، اما از قدم‌های کوچک شروع کنید.'
        },
        en: {
            title: 'SMART Goal Tracker',
            daily: 'Daily',
            weekly: 'Weekly',
            monthly: 'Monthly',
            yearly: 'Yearly',
            five_year: '5-Year',
            viewMode: 'Current View:',
            business: 'Business Goals',
            personal: 'Personal Development',
            addGoal: 'Add Goal',
            editTitle: 'Edit Title',
            saveTitle: 'Save',
            done: 'Done',
            total: 'Total',
            progress: 'Progress',
            empty: 'No goals set yet.',
            masterView: 'View Staff Goals:',
            lastUpdate: 'Last Updated:',
            smartNote: 'Specific, Measurable, Achievable, Relevant, Time-bound',
            addSubTask: 'Add step...',
            breakDown: 'Break down',
            print: 'Download Poster (PNG)',
            exporting: 'Generating Image...',
            reportTitle: 'Strategic Vision & Goals',
            visionNote: 'Dream big, but start small.'
        }
    }[lang];

    const selectedPerson = useMemo(() => personnel.find(p => p.id === selectedUserId), [personnel, selectedUserId]);

    const handleExportImage = async () => {
        if (!posterRef.current || isExporting) return;
        setIsExporting(true);
        try {
            // Give time for styles to settle
            await new Promise(r => setTimeout(r, 500));
            const dataUrl = await htmlToImage.toPng(posterRef.current, {
                quality: 1,
                pixelRatio: 2, // High DPI for quality
                backgroundColor: '#ffffff'
            });

            const link = document.createElement('a');
            link.download = `Goal-Poster-${selectedPerson?.fullName || 'User'}-${activePeriod}.png`;
            link.href = dataUrl;
            link.click();
        } catch (err) {
            console.error('Export failed', err);
            alert('خطا در تولید عکس. لطفاً دوباره تلاش کنید.');
        } finally {
            setIsExporting(false);
        }
    };

    const handleAddTask = (catId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const taskText = window.prompt(lang === 'fa' ? 'عنوان هدف را وارد کنید:' : 'Enter goal title:');
        if (!taskText) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: taskText, isCompleted: false, subTasks: [] }] } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const newCompleted = !t.isCompleted; return { ...t, isCompleted: newCompleted, subTasks: t.subTasks?.map(st => ({ ...st, isCompleted: newCompleted })) }; } return t; }) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleAddSubTask = (catId: string, taskId: string, text: string) => {
        if (!canEdit || !currentUserGoals || !text.trim()) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, subTasks: [...(t.subTasks || []), { id: `st-${Date.now()}`, text, isCompleted: false }], isCompleted: false } : t) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleSubTask = (catId: string, taskId: string, subId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const updatedSubTasks = t.subTasks?.map(st => st.id === subId ? { ...st, isCompleted: !st.isCompleted } : st); return { ...t, subTasks: updatedSubTasks, isCompleted: updatedSubTasks?.every(st => st.isCompleted) || false }; } return t; }) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const removeTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals || !window.confirm('حذف هدف؟')) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.filter(t => t.id !== taskId) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleUpdateCategoryTitle = (catId: string, newTitle: string) => {
        if (!canEdit || !currentUserGoals || !newTitle.trim()) { setEditingTitleId(null); return; }
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, title: newTitle } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
        setEditingTitleId(null);
    };

    const calculateTaskProgress = (task: GoalTask) => {
        if (!task.subTasks || task.subTasks.length === 0) return task.isCompleted ? 100 : 0;
        return Math.round((task.subTasks.filter(st => st.isCompleted).length / task.subTasks.length) * 100);
    };

    if (isLoading) return <div className="p-8 text-center animate-pulse text-indigo-600 font-bold">در حال بارگذاری سیستم اهداف...</div>;

    const periodIcons: Record<string, React.ReactNode> = {
        daily: <IconClock className="w-4 h-4" />,
        weekly: <IconCalendar className="w-4 h-4" />,
        monthly: <IconActivity className="w-4 h-4" />,
        yearly: <IconAward className="w-4 h-4" />,
        five_year: <IconTrendingUp className="w-4 h-4" />
    };

    const navItems = [
        { id: 'daily', activeColor: 'bg-blue-600', hoverColor: 'hover:text-blue-600' },
        { id: 'weekly', activeColor: 'bg-green-600', hoverColor: 'hover:text-green-600' },
        { id: 'monthly', activeColor: 'bg-orange-600', hoverColor: 'hover:text-orange-600' },
        { id: 'yearly', activeColor: 'bg-rose-600', hoverColor: 'hover:text-rose-600' },
        { id: 'five_year', activeColor: 'bg-purple-600', hoverColor: 'hover:text-purple-600' }
    ];

    return (
        <div className="relative">
            {/* --- WEB INTERFACE --- */}
            <div className="space-y-8 animate-fade-in pb-12">
                <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-gray-100 flex flex-col lg:flex-row gap-8 items-center relative overflow-hidden">
                    <div className={`absolute top-0 right-0 w-48 h-48 rounded-bl-full -z-10 opacity-10 ${activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600' : 'bg-indigo-600')}`}></div>
                    <div className="shrink-0 w-full lg:w-1/3">
                        <h2 className="text-3xl font-black text-gray-900 mb-1 uppercase tracking-tight">{t.title}</h2>
                        <div className="flex items-center gap-2 mb-6">
                            <span className="text-xs font-bold text-gray-400">{t.viewMode}</span>
                            <span className={`px-2 py-0.5 rounded-lg text-[10px] font-black text-white ${navItems.find(n => n.id === activePeriod)?.activeColor}`}>
                                {t[activePeriod as keyof typeof t.fa]}
                            </span>
                        </div>
                        <div className="bg-gray-100 p-1.5 rounded-2xl mb-6 grid grid-cols-5 gap-1.5 border border-gray-200 shadow-inner">
                            {navItems.map(btn => (
                                <button key={btn.id} onClick={() => { setActivePeriod(btn.id as GoalPeriod); setExpandedTaskId(null); }} className={`flex flex-col items-center justify-center py-3 rounded-xl transition-all duration-300 ${activePeriod === btn.id ? `${btn.activeColor} text-white shadow-lg scale-105 z-10` : `text-gray-500 ${btn.hoverColor} hover:bg-white`}`}>
                                    <div className="mb-1">{periodIcons[btn.id]}</div>
                                    <span className="text-[9px] font-black uppercase whitespace-nowrap">{t[btn.id as keyof typeof t.fa]}</span>
                                </button>
                            ))}
                        </div>
                        <div className="flex flex-col gap-3">
                            {isMaster && (
                                <select className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm font-bold" value={selectedUserId} onChange={(e) => setSelectedUserId(e.target.value)}>
                                    {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                                </select>
                            )}
                            <button 
                                onClick={handleExportImage} 
                                disabled={isExporting}
                                className={`w-full py-3.5 text-white rounded-2xl text-xs font-black flex items-center justify-center gap-2 transition-all shadow-lg hover:brightness-110 active:scale-[0.98] ${isExporting ? 'bg-gray-400' : (activePeriod === 'five_year' ? 'bg-purple-600' : (activePeriod === 'yearly' ? 'bg-rose-600' : 'bg-indigo-600'))}`}
                            >
                                {isExporting ? (
                                    <div className="flex items-center gap-2">
                                        <svg className="animate-spin h-4 w-4 text-white" viewBox="0 0 24 24">
                                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                        </svg>
                                        {t.exporting}
                                    </div>
                                ) : (
                                    <><IconPrinter className="w-4 h-4" /> {t.print}</>
                                )}
                            </button>
                        </div>
                    </div>
                    <div className="flex flex-col items-center gap-2 lg:border-r lg:px-10 border-gray-100">
                        <div className="relative w-36 h-36 flex items-center justify-center">
                            <svg className="w-full h-full transform -rotate-90"><circle cx="72" cy="72" r="62" stroke="currentColor" strokeWidth="12" fill="transparent" className="text-gray-100" /><circle cx="72" cy="72" r="62" stroke="currentColor" strokeWidth="12" fill="transparent" strokeDasharray={389.557} strokeDashoffset={389.557 - (stats.percent / 100) * 389.557} className={`transition-all duration-1000 ease-out ${activePeriod === 'five_year' ? 'text-purple-600' : (activePeriod === 'yearly' ? 'text-rose-600' : 'text-indigo-600')}`} /></svg>
                            <div className="absolute inset-0 flex flex-col items-center justify-center"><span className="text-3xl font-black text-gray-900">{stats.percent}%</span><span className="text-[9px] font-black text-gray-400 uppercase">{t.progress}</span></div>
                        </div>
                    </div>
                    <div className="flex-grow grid grid-cols-2 sm:grid-cols-3 gap-4 w-full">
                        {currentUserGoals?.categories.map(cat => {
                            const catProgress = cat.tasks.length > 0 ? Math.round((cat.tasks.filter(t => t.isCompleted).length / cat.tasks.length) * 100) : 0;
                            return (
                                <div key={cat.id} className="bg-gray-50 p-4 rounded-3xl flex flex-col justify-center border border-gray-100">
                                    <div className="text-[9px] font-black text-gray-400 uppercase truncate mb-2">{cat.title}</div>
                                    <div className="flex items-center justify-between gap-3"><div className="flex-grow bg-gray-200 h-2 rounded-full overflow-hidden"><div className={`h-full rounded-full bg-indigo-500`} style={{ width: `${catProgress}%` }}></div></div><span className="text-[11px] font-black text-gray-700">{catProgress}%</span></div>
                                </div>
                            );
                        })}
                    </div>
                </div>

                {/* Goals Grid (Web) */}
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-5 gap-6">
                    {currentUserGoals?.categories.map((cat) => (
                        <div key={cat.id} className={`bg-white rounded-[2.5rem] border border-gray-100 shadow-lg overflow-hidden flex flex-col min-h-[500px] transition-all duration-500 ${activePeriod === 'five_year' ? 'ring-2 ring-purple-100' : (activePeriod === 'yearly' ? 'ring-2 ring-rose-100' : '')}`}>
                            <div className={`p-5 text-center text-white font-black text-xs uppercase tracking-widest ${cat.color.split(' ').find(c => c.startsWith('header-')) === 'header-purple' ? 'bg-purple-500' : (cat.color.split(' ').find(c => c.startsWith('header-')) === 'header-rose' ? 'bg-rose-500' : 'bg-indigo-500')}`}>
                                {editingTitleId === cat.id ? <input autoFocus className="w-full bg-white/20 px-2 py-1 rounded" defaultValue={cat.title} onBlur={e => handleUpdateCategoryTitle(cat.id, e.target.value)} /> : <span onClick={() => canEdit && setEditingTitleId(cat.id)} className="cursor-pointer hover:underline">{cat.title}</span>}
                            </div>
                            <div className="flex-grow overflow-y-auto p-4 space-y-4">
                                {cat.tasks.map((task) => (
                                    <div key={task.id} className={`flex flex-col rounded-3xl border p-4 ${task.isCompleted ? 'bg-gray-50/50 opacity-60' : 'bg-white shadow-sm'}`}>
                                        <div className="flex items-start gap-3">
                                            <button onClick={() => toggleTask(cat.id, task.id)} className={`w-6 h-6 rounded-xl border-2 flex items-center justify-center shrink-0 ${task.isCompleted ? 'bg-indigo-600 border-indigo-600 text-white' : 'border-gray-200'}`}>{task.isCompleted && <IconCheck className="w-4 h-4" />}</button>
                                            <span onClick={() => setExpandedTaskId(expandedTaskId === task.id ? null : task.id)} className={`text-[12px] font-black cursor-pointer ${task.isCompleted ? 'line-through text-gray-400' : 'text-gray-800'}`}>{task.text}</span>
                                        </div>
                                        {expandedTaskId === task.id && (
                                            <div className="mt-4 space-y-2 pl-4 border-r-2 border-gray-100 animate-slide-in">
                                                {task.subTasks?.map(st => (
                                                    <div key={st.id} className="flex items-center gap-2 text-[11px] font-bold text-gray-600"><button onClick={() => toggleSubTask(cat.id, task.id, st.id)} className={`w-4 h-4 rounded border flex items-center justify-center ${st.isCompleted ? 'bg-indigo-400 text-white' : 'bg-white'}`}>{st.isCompleted && <IconCheck className="w-3 h-3" />}</button><span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span></div>
                                                ))}
                                                <input className="w-full text-[10px] p-2 bg-gray-50 rounded-lg outline-none" placeholder={t.addSubTask} onKeyDown={e => { if (e.key === 'Enter' && (e.target as HTMLInputElement).value.trim()) { handleAddSubTask(cat.id, task.id, (e.target as HTMLInputElement).value); (e.target as HTMLInputElement).value = ''; } }} />
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                            {canEdit && (
                                <div className="p-4 border-t bg-gray-50/50"><button onClick={() => handleAddTask(cat.id)} className="w-full py-3 border-2 border-dashed rounded-2xl text-gray-400 text-[11px] font-black hover:text-indigo-600 hover:border-indigo-300 transition-colors flex items-center justify-center gap-2"><IconPlus className="w-4 h-4" /> {t.addGoal}</button></div>
                            )}
                        </div>
                    ))}
                </div>
            </div>

            {/* --- EXCLUSIVE POSTER CANVAS (HIDDEN BUT PRESENT FOR IMAGE EXPORT) --- */}
            <div style={{ position: 'fixed', left: '-9999px', top: 0 }}>
                <div ref={posterRef} className="flex flex-col bg-white overflow-hidden relative border-[20px]" style={{ width: '794px', height: '1123px', borderColor: activePeriod === 'five_year' ? '#9333ea' : (activePeriod === 'yearly' ? '#e11d48' : '#4f46e5') }}>
                    {/* Visual Decorations */}
                    <div className="absolute top-0 right-0 w-96 h-96 bg-gray-50 rounded-bl-full -z-10 opacity-50"></div>

                    {/* Header */}
                    <div className="p-12 flex items-center justify-between text-white" style={{ backgroundColor: activePeriod === 'five_year' ? '#9333ea' : (activePeriod === 'yearly' ? '#e11d48' : '#4f46e5') }}>
                        <div className="flex items-center gap-8">
                            <div className="w-28 h-28 rounded-[2.5rem] bg-white p-1 shadow-xl border-4 border-white/30 flex items-center justify-center overflow-hidden">
                                {selectedPerson?.avatar ? <img src={selectedPerson.avatar} className="w-full h-full object-cover" /> : <span className="text-5xl font-black text-gray-300 uppercase">{selectedPerson?.fullName.charAt(0)}</span>}
                            </div>
                            <div>
                                <h1 className="text-4xl font-black mb-2 tracking-tight">{selectedPerson?.fullName}</h1>
                                <div className="flex gap-2">
                                    {selectedPerson?.roles.map(r => <span key={r} className="bg-white/20 px-3 py-1 rounded-xl text-[10px] font-black uppercase tracking-widest border border-white/20">{r}</span>)}
                                </div>
                            </div>
                        </div>
                        <div className="text-right">
                            <div className="bg-black/20 backdrop-blur-md px-8 py-5 rounded-[2rem] border border-white/10 text-center">
                                <div className="text-4xl font-black leading-none mb-1">{stats.percent}%</div>
                                <div className="text-[8px] font-black opacity-80 uppercase tracking-[0.2em]">PERFORMANCE</div>
                            </div>
                        </div>
                    </div>

                    {/* Sub Header */}
                    <div className="px-12 py-8 flex justify-between items-end border-b-4 border-gray-100 bg-white">
                        <div>
                            <h2 className="text-3xl font-black mb-1" style={{ color: activePeriod === 'five_year' ? '#581c87' : (activePeriod === 'yearly' ? '#9f1239' : '#1e1b4b') }}>{t.reportTitle}</h2>
                            <div className="flex items-center gap-3 text-gray-400 font-black text-xs uppercase tracking-widest">
                                <span>PERIOD: {t[activePeriod as keyof typeof t.fa]}</span>
                                <span className="opacity-30">|</span>
                                <span>YEAR: {new Date().getFullYear()}</span>
                            </div>
                        </div>
                        <div className="text-right">
                            <div className="text-[10px] font-black text-gray-800 dir-ltr">{new Date().toLocaleDateString(lang === 'fa' ? 'fa-IR' : 'en-US')}</div>
                        </div>
                    </div>

                    {/* Grid */}
                    <div className="flex-grow p-12 grid grid-cols-2 gap-8 bg-gray-50/10 content-start">
                        {currentUserGoals?.categories.map((cat) => (
                            <div key={cat.id} className="bg-white rounded-[2.5rem] border-2 border-gray-100 shadow-sm flex flex-col overflow-hidden h-fit">
                                <div className="px-6 py-4 border-b-2 font-black text-[11px] uppercase tracking-widest bg-gray-50 flex justify-between items-center" style={{ borderBottomColor: activePeriod === 'five_year' ? '#9333ea' : (activePeriod === 'yearly' ? '#e11d48' : '#4f46e5') }}>
                                    <span>{cat.title}</span>
                                    <div className="bg-white px-2 py-0.5 rounded-lg border text-[10px]">{Math.round((cat.tasks.filter(t=>t.isCompleted).length / (cat.tasks.length || 1)) * 100)}%</div>
                                </div>
                                <div className="p-6 space-y-4">
                                    {cat.tasks.map((task) => (
                                        <div key={task.id} className="flex gap-4">
                                            <div className="w-4 h-4 rounded-md border-2 mt-0.5 shrink-0 flex items-center justify-center" style={{ 
                                                backgroundColor: task.isCompleted ? (activePeriod === 'five_year' ? '#9333ea' : (activePeriod === 'yearly' ? '#e11d48' : '#4f46e5')) : 'white',
                                                borderColor: task.isCompleted ? (activePeriod === 'five_year' ? '#9333ea' : (activePeriod === 'yearly' ? '#e11d48' : '#4f46e5')) : '#d1d5db'
                                            }}>
                                                {task.isCompleted && <IconCheck className="w-2.5 h-2.5 text-white" />}
                                            </div>
                                            <div className="min-w-0">
                                                <div className={`text-[12px] font-black leading-tight ${task.isCompleted ? 'text-gray-300 line-through' : 'text-gray-800'}`}>{task.text}</div>
                                                {task.subTasks && task.subTasks.length > 0 && (
                                                    <div className="mt-2 space-y-1 pl-4 border-r-2 border-gray-50">
                                                        {task.subTasks.map(st => (
                                                            <div key={st.id} className="text-[9px] font-bold text-gray-400 flex items-center gap-2">
                                                                <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: st.isCompleted ? '#818cf8' : '#e5e7eb' }}></div>
                                                                <span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span>
                                                            </div>
                                                        ))}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Footer */}
                    <div className="p-12 border-t-2 border-gray-100 flex justify-between items-center bg-white">
                        <div className="max-w-[70%]">
                            <p className="text-[12px] font-black text-indigo-600 uppercase tracking-[0.3em] mb-2">MOTIVATIONAL VISION</p>
                            <p className="text-xs font-black text-gray-400 italic">"{t.visionNote}"</p>
                        </div>
                        <div className="text-right flex flex-col items-end">
                            <div className="w-14 h-14 rounded-2xl flex items-center justify-center mb-2 shadow-lg" style={{ backgroundColor: activePeriod === 'five_year' ? '#9333ea' : (activePeriod === 'yearly' ? '#e11d48' : '#4f46e5') }}>
                                <IconShield className="w-8 h-8 text-white" />
                            </div>
                            <span className="text-[8px] font-black text-gray-300 uppercase tracking-[0.2em]">SMART CRM POSTER</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconCalendar, IconChart, IconShield, IconBrain, IconArrowRight, IconActivity, IconBriefcase, IconUsers, IconPrinter, IconAward, IconTrendingUp, IconClock, IconStar, IconTrophy } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';
import * as htmlToImage from 'html-to-image';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف کاری (Business)', color: 'bg-blue-600', type: 'business' as const },
    { id: 'cat2', title: 'توسعه فردی (Personal)', color: 'bg-emerald-600', type: 'personal' as const },
    { id: 'cat3', title: 'سلامتی و لایف‌استایل', color: 'bg-orange-600', type: 'personal' as const },
    { id: 'cat4', title: 'اهداف مالی', color: 'bg-rose-600', type: 'personal' as const },
    { id: 'cat5', title: 'سایر موارد', color: 'bg-purple-600', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isExporting, setIsExporting] = useState(false);
    const [editingTitleId, setEditingTitleId] = useState<string | null>(null);
    const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

    const posterRef = useRef<HTMLDivElement>(null);
    const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');
    const canEdit = selectedUserId === currentUser.id;

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    // Split goals into Active and Success History
    const { activeCategories, successHistory } = useMemo(() => {
        if (!currentUserGoals) return { activeCategories: [], successHistory: [] };

        const history: (GoalTask & { catTitle: string, catColor: string })[] = [];
        const active = currentUserGoals.categories.map(cat => {
            const activeTasks = cat.tasks.filter(t => !t.isCompleted);
            const completedTasks = cat.tasks.filter(t => t.isCompleted);

            completedTasks.forEach(ct => {
                history.push({ ...ct, catTitle: cat.title, catColor: cat.color });
            });

            return { ...cat, tasks: activeTasks };
        });

        return { activeCategories: active, successHistory: history };
    }, [currentUserGoals]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => {
            c.tasks.forEach(t => {
                total++;
                if (t.isCompleted) done++;
            });
        });
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const t = {
        fa: {
            title: 'مهندسی اهداف هوشمند',
            daily: 'امروز',
            weekly: 'هفتگی',
            monthly: 'ماهانه',
            yearly: 'سالانه',
            five_year: '۵ ساله',
            viewMode: 'برنامه زمانی:',
            addGoal: 'افزودن هدف جدید',
            done: 'انجام شد',
            progress: 'سطح پیشرفت کل',
            empty: 'لیست اهداف جاری خالی است.',
            print: 'دریافت پستر استراتژیک (نسخه لوکس)',
            exporting: 'در حال رندر حرفه‌ای...',
            reportTitle: 'سند راهبردی و نقشه راه موفقیت',
            visionNote: 'رویاهای بزرگ، اراده‌های پولادین می‌سازند. هر تیک، یک گام به جلوست.',
            historyTitle: 'تالار افتخارات و موفقیت‌ها',
            historySub: 'اهداف محقق شده در این دوره زمانی',
            achieved: 'محقق شده'
        },
        en: {
            title: 'SMART Goals Engineering',
            daily: 'Daily',
            weekly: 'Weekly',
            monthly: 'Monthly',
            yearly: 'Yearly',
            five_year: '5-Year',
            viewMode: 'Timeline:',
            addGoal: 'Add Goal',
            done: 'Done',
            progress: 'Overall Performance',
            empty: 'No active goals.',
            print: 'Export Strategic Poster',
            exporting: 'Rendering Pro Version...',
            reportTitle: 'Strategic Vision & Performance Roadmap',
            visionNote: 'Big dreams build steel wills. Every checkmark is a step forward.',
            historyTitle: 'Hall of Fame & Achievements',
            historySub: 'Goals achieved during this period',
            achieved: 'Achieved'
        }
    }[lang];

    const selectedPerson = useMemo(() => personnel.find(p => p.id === selectedUserId), [personnel, selectedUserId]);

    const handleExportImage = async () => {
        if (!posterRef.current || isExporting) return;
        setIsExporting(true);
        try {
            await new Promise(r => setTimeout(r, 800));
            const dataUrl = await htmlToImage.toPng(posterRef.current, {
                quality: 1,
                pixelRatio: 3, 
                backgroundColor: '#0f172a' 
            });

            const link = document.createElement('a');
            link.download = `Strategic-Poster-${selectedPerson?.fullName}-${activePeriod}.png`;
            link.href = dataUrl;
            link.click();
        } catch (err) {
            alert('خطا در تولید پستر.');
        } finally {
            setIsExporting(false);
        }
    };

    const handleAddTask = (catId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const taskText = window.prompt(lang === 'fa' ? 'عنوان هدف جدید:' : 'New Goal Title:');
        if (!taskText) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: taskText, isCompleted: false, subTasks: [] }] } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const newCompleted = !t.isCompleted; return { ...t, isCompleted: newCompleted, subTasks: t.subTasks?.map(st => ({ ...st, isCompleted: newCompleted })) }; } return t; }) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleAddSubTask = (catId: string, taskId: string, text: string) => {
        if (!canEdit || !currentUserGoals || !text.trim()) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, subTasks: [...(t.subTasks || []), { id: `st-${Date.now()}`, text, isCompleted: false }], isCompleted: false } : t) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleSubTask = (catId: string, taskId: string, subId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const updatedSubTasks = t.subTasks?.map(st => st.id === subId ? { ...st, isCompleted: !st.isCompleted } : st); return { ...t, subTasks: updatedSubTasks, isCompleted: updatedSubTasks?.every(st => st.isCompleted) || false }; } return t; }) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    if (isLoading) return <div className="p-20 text-center animate-pulse text-indigo-600 font-black text-xl">در حال آماده‌سازی بستر اهداف...</div>;

    const periodIcons: Record<string, React.ReactNode> = {
        daily: <IconClock className="w-4 h-4" />,
        weekly: <IconCalendar className="w-4 h-4" />,
        monthly: <IconActivity className="w-4 h-4" />,
        yearly: <IconAward className="w-4 h-4" />,
        five_year: <IconTrendingUp className="w-4 h-4" />
    };

    return (
        <div className="space-y-10 pb-20">
            {/* --- WEB UI --- */}
            <div className="space-y-10 animate-fade-in">
                {/* Dashboard Header */}
                <div className="bg-white p-10 rounded-[3rem] shadow-2xl border border-gray-100 flex flex-col lg:flex-row gap-10 items-center relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-64 h-64 bg-indigo-600/5 rounded-full -translate-x-1/2 -translate-y-1/2"></div>
                    <div className="shrink-0 w-full lg:w-1/3 z-10">
                        <h2 className="text-4xl font-black text-gray-900 mb-2 uppercase tracking-tighter">{t.title}</h2>
                        <div className="flex items-center gap-3 mb-8">
                            <span className="text-xs font-black text-gray-400 uppercase tracking-widest">{t.viewMode}</span>
                            <span className="px-3 py-1 bg-indigo-600 text-white rounded-full text-[10px] font-black uppercase shadow-lg shadow-indigo-200">
                                {t[activePeriod as keyof typeof t.fa]}
                            </span>
                        </div>
                        <div className="bg-gray-100 p-2 rounded-3xl mb-8 grid grid-cols-5 gap-2 border border-gray-200 shadow-inner">
                            {['daily', 'weekly', 'monthly', 'yearly', 'five_year'].map(p => (
                                <button key={p} onClick={() => { setActivePeriod(p as GoalPeriod); setExpandedTaskId(null); }} className={`flex flex-col items-center justify-center py-4 rounded-2xl transition-all duration-500 ${activePeriod === p ? `bg-white text-indigo-600 shadow-xl scale-110 z-10` : `text-gray-400 hover:text-gray-600 hover:bg-white/50`}`}>
                                    {periodIcons[p]}
                                    <span className="text-[8px] font-black mt-1 uppercase">{t[p as keyof typeof t.fa]}</span>
                                </button>
                            ))}
                        </div>
                        <button onClick={handleExportImage} disabled={isExporting} className="w-full py-4 bg-gray-900 text-white rounded-[1.5rem] text-sm font-black flex items-center justify-center gap-3 transition-all hover:bg-black hover:scale-[1.02] shadow-2xl active:scale-95 disabled:opacity-50">
                            {isExporting ? <><div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> {t.exporting}</> : <><IconPrinter className="w-5 h-5" /> {t.print}</>}
                        </button>
                    </div>
                    <div className="flex flex-col items-center gap-4 lg:border-r lg:px-12 border-gray-100 z-10">
                        <div className="relative w-44 h-44 flex items-center justify-center">
                            <svg className="w-full h-full transform -rotate-90"><circle cx="88" cy="88" r="78" stroke="currentColor" strokeWidth="14" fill="transparent" className="text-gray-100" /><circle cx="88" cy="88" r="78" stroke="currentColor" strokeWidth="14" fill="transparent" strokeDasharray={490} strokeDashoffset={490 - (stats.percent / 100) * 490} className="transition-all duration-1000 ease-out text-indigo-600" strokeLinecap="round" /></svg>
                            <div className="absolute inset-0 flex flex-col items-center justify-center"><span className="text-4xl font-black text-gray-900">{stats.percent}%</span><span className="text-[9px] font-black text-gray-400 uppercase tracking-widest mt-1">{t.progress}</span></div>
                        </div>
                    </div>
                    {isMaster && (
                        <div className="w-full lg:w-1/4 p-6 bg-indigo-50 rounded-[2rem] border border-indigo-100">
                            <label className="text-[10px] font-black text-indigo-400 uppercase block mb-3">مشاهده اهداف پرسنل:</label>
                            <select className="w-full bg-white border border-indigo-100 rounded-xl px-4 py-3 text-sm font-bold shadow-sm outline-none" value={selectedUserId} onChange={(e) => setSelectedUserId(e.target.value)}>
                                {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                            </select>
                        </div>
                    )}
                </div>

                {/* Main Goals Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-5 gap-8">
                    {activeCategories.map((cat) => (
                        <div key={cat.id} className="bg-white rounded-[2.5rem] border border-gray-100 shadow-xl overflow-hidden flex flex-col min-h-[500px] group transition-all hover:shadow-2xl">
                            <div className={`p-6 text-center text-white font-black text-xs uppercase tracking-[0.2em] ${cat.color} shadow-lg`}>
                                {cat.title}
                            </div>
                            <div className="flex-grow p-5 space-y-5 overflow-y-auto custom-scrollbar">
                                {cat.tasks.map((task) => (
                                    <div key={task.id} className="flex flex-col bg-gray-50/50 rounded-3xl border border-gray-100 p-4 hover:bg-white hover:shadow-md transition-all">
                                        <div className="flex items-start gap-3">
                                            <button onClick={() => toggleTask(cat.id, task.id)} className="w-6 h-6 rounded-xl border-2 border-indigo-200 bg-white flex items-center justify-center shrink-0 transition-all hover:border-indigo-600">
                                                {task.isCompleted && <IconCheck className="w-4 h-4 text-indigo-600" />}
                                            </button>
                                            <span onClick={() => setExpandedTaskId(expandedTaskId === task.id ? null : task.id)} className="text-[13px] font-bold text-gray-800 cursor-pointer leading-tight">{task.text}</span>
                                        </div>
                                        {expandedTaskId === task.id && (
                                            <div className="mt-4 space-y-2.5 pl-5 border-r-2 border-indigo-100 animate-slide-in">
                                                {task.subTasks?.map(st => (
                                                    <div key={st.id} className="flex items-center gap-3 text-[11px] font-bold text-gray-500">
                                                        <button onClick={() => toggleSubTask(cat.id, task.id, st.id)} className={`w-4 h-4 rounded-md border flex items-center justify-center ${st.isCompleted ? 'bg-indigo-500 border-indigo-500 text-white' : 'bg-white border-gray-200'}`}>{st.isCompleted && <IconCheck className="w-3 h-3" />}</button>
                                                        <span>{st.text}</span>
                                                    </div>
                                                ))}
                                                {canEdit && (
                                                    <input className="w-full text-[10px] p-2 bg-white rounded-lg outline-none border border-gray-100 focus:border-indigo-300" placeholder="گام اجرایی..." onKeyDown={e => { if (e.key === 'Enter' && (e.target as HTMLInputElement).value.trim()) { handleAddSubTask(cat.id, task.id, (e.target as HTMLInputElement).value); (e.target as HTMLInputElement).value = ''; } }} />
                                                )}
                                            </div>
                                        )}
                                    </div>
                                ))}
                                {cat.tasks.length === 0 && <div className="text-center py-10 opacity-10"><IconTarget className="w-12 h-12 mx-auto" /></div>}
                            </div>
                            {canEdit && (
                                <div className="p-5 border-t bg-gray-50/30"><button onClick={() => handleAddTask(cat.id)} className="w-full py-3 bg-white border border-gray-200 rounded-2xl text-gray-400 text-[11px] font-black hover:text-indigo-600 hover:border-indigo-600 transition-all flex items-center justify-center gap-2 shadow-sm"><IconPlus className="w-4 h-4" /> {t.addGoal}</button></div>
                            )}
                        </div>
                    ))}
                </div>

                {/* Success History (Hall of Fame) */}
                {successHistory.length > 0 && (
                    <div className="mt-12 bg-white p-10 rounded-[3rem] border border-gray-100 shadow-xl animate-fade-in">
                        <div className="flex items-center justify-between mb-8 pb-6 border-b border-gray-50">
                            <div className="flex items-center gap-4">
                                <div className="p-3 bg-amber-100 text-amber-600 rounded-2xl shadow-lg shadow-amber-100"><IconTrophy className="w-6 h-6" /></div>
                                <div>
                                    <h3 className="text-2xl font-black text-gray-900">{t.historyTitle}</h3>
                                    <p className="text-sm text-gray-400 font-bold">{t.historySub}</p>
                                </div>
                            </div>
                            <div className="px-6 py-2 bg-amber-50 text-amber-700 rounded-full font-black text-sm border border-amber-100">
                                {successHistory.length} {t.achieved}
                            </div>
                        </div>
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                            {successHistory.map((goal, idx) => (
                                <div key={idx} className="bg-gray-50 p-4 rounded-3xl border border-gray-200 flex items-center gap-4 relative overflow-hidden group">
                                    <div className={`absolute top-0 right-0 w-1 h-full ${goal.catColor}`}></div>
                                    <div className="w-10 h-10 rounded-2xl bg-white shadow-sm flex items-center justify-center text-amber-500 shrink-0"><IconStar className="w-5 h-5 fill-current" /></div>
                                    <div className="min-w-0">
                                        <h4 className="text-[13px] font-black text-gray-800 truncate line-through opacity-50">{goal.text}</h4>
                                        <p className="text-[9px] font-black text-gray-400 uppercase tracking-tighter mt-0.5">{goal.catTitle}</p>
                                    </div>
                                    <button onClick={() => toggleTask(INITIAL_CATEGORIES.find(c=>c.title===goal.catTitle)?.id || '', goal.id)} className="absolute left-4 opacity-0 group-hover:opacity-100 transition-opacity text-indigo-600 text-[10px] font-black underline">بازگرداندن</button>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>

            {/* --- EXCLUSIVE STRATEGIC POSTER (HIDDEN FROM VIEW) --- */}
            <div style={{ position: 'fixed', left: '-9999px', top: 0 }}>
                <div ref={posterRef} className="flex flex-col bg-[#0f172a] overflow-hidden relative" style={{ width: '840px', height: '1188px', color: 'white' }}>
                    {/* Visual Art Background */}
                    <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-indigo-600/20 rounded-full blur-[120px] -translate-y-1/2 translate-x-1/2"></div>
                    <div className="absolute bottom-0 left-0 w-[400px] h-[400px] bg-purple-600/10 rounded-full blur-[100px] translate-y-1/2 -translate-x-1/2"></div>
                    <div className="absolute top-1/2 left-1/2 w-full h-full bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-[0.03] -translate-x-1/2 -translate-y-1/2 pointer-events-none"></div>

                    {/* Header: Dark/Elite Style */}
                    <div className="p-16 flex justify-between items-center bg-white/5 backdrop-blur-xl border-b border-white/10">
                        <div className="flex items-center gap-10">
                            <div className="w-36 h-36 rounded-[3.5rem] p-1 bg-gradient-to-br from-indigo-500 to-purple-600 shadow-2xl">
                                <div className="w-full h-full rounded-[3.2rem] bg-[#0f172a] p-1 overflow-hidden">
                                    {selectedPerson?.avatar ? <img src={selectedPerson.avatar} className="w-full h-full object-cover rounded-[3rem]" /> : <div className="w-full h-full flex items-center justify-center text-6xl font-black text-white/20 uppercase">{selectedPerson?.fullName.charAt(0)}</div>}
                                </div>
                            </div>
                            <div>
                                <h1 className="text-5xl font-black mb-3 tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-white to-gray-400">{selectedPerson?.fullName}</h1>
                                <div className="flex gap-3">
                                    {selectedPerson?.roles.map(r => <span key={r} className="bg-indigo-600/30 text-indigo-300 px-5 py-2 rounded-2xl text-[11px] font-black uppercase tracking-widest border border-indigo-500/30">{r}</span>)}
                                </div>
                            </div>
                        </div>
                        <div className="text-right">
                            <div className="text-7xl font-black text-indigo-500 leading-none mb-2">{stats.percent}%</div>
                            <div className="text-[10px] font-black text-white/40 uppercase tracking-[0.4em]">{t.progress}</div>
                        </div>
                    </div>

                    {/* Report Label Bar */}
                    <div className="px-16 py-8 flex justify-between items-center bg-indigo-600 shadow-2xl">
                        <div className="flex items-center gap-4">
                            <IconShield className="w-6 h-6 text-white" />
                            <h2 className="text-2xl font-black uppercase tracking-tight">{t.reportTitle}</h2>
                        </div>
                        <div className="text-[12px] font-black opacity-80 uppercase tracking-widest dir-ltr">
                           PERIOD: {activePeriod.toUpperCase()} / YEAR: {new Date().getFullYear()}
                        </div>
                    </div>

                    {/* Content Grid: Two Columns for Active Goals */}
                    <div className="flex-grow p-16 grid grid-cols-2 gap-10 content-start">
                        {activeCategories.map((cat) => (
                            <div key={cat.id} className="bg-white/5 border border-white/10 rounded-[3rem] p-10 flex flex-col gap-8 shadow-inner">
                                <div className="flex justify-between items-center border-b border-white/5 pb-6">
                                    <h3 className="text-xl font-black uppercase tracking-widest text-indigo-400">{cat.title}</h3>
                                    <span className="text-[10px] font-black bg-white/10 px-3 py-1 rounded-full text-white/60">{cat.tasks.length} ACTIVE</span>
                                </div>
                                <div className="space-y-8">
                                    {cat.tasks.map((task) => (
                                        <div key={task.id} className="flex gap-6">
                                            <div className="w-6 h-6 rounded-xl border-2 border-indigo-500/50 mt-1 shrink-0"></div>
                                            <div className="flex-grow min-w-0">
                                                <div className="text-lg font-bold text-gray-200 leading-tight mb-3">{task.text}</div>
                                                {task.subTasks && task.subTasks.length > 0 && (
                                                    <div className="space-y-3 pl-8 border-r-2 border-indigo-500/20">
                                                        {task.subTasks.map(st => (
                                                            <div key={st.id} className="text-xs font-bold text-white/40 flex items-center gap-3">
                                                                <div className={`w-2 h-2 rounded-full ${st.isCompleted ? 'bg-indigo-500' : 'bg-white/10'}`}></div>
                                                                <span className={st.isCompleted ? 'line-through' : ''}>{st.text}</span>
                                                            </div>
                                                        ))}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                    {cat.tasks.length === 0 && <div className="text-white/20 italic text-sm">NO PENDING GOALS IN THIS SECTOR</div>}
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Success History Footer Section on Poster */}
                    {successHistory.length > 0 && (
                        <div className="mx-16 mb-16 p-10 bg-white/5 border border-amber-500/20 rounded-[3rem] relative overflow-hidden">
                            <div className="absolute top-0 right-0 p-8 opacity-10"><IconTrophy className="w-32 h-32" /></div>
                            <h3 className="text-xl font-black text-amber-400 mb-8 uppercase tracking-[0.3em] flex items-center gap-3"><IconAward className="w-6 h-6" /> {t.historyTitle}</h3>
                            <div className="grid grid-cols-3 gap-6">
                                {successHistory.slice(0, 9).map((goal, i) => (
                                    <div key={i} className="flex items-center gap-3 bg-white/5 p-4 rounded-2xl border border-white/5">
                                        <div className="text-amber-500"><IconCheck className="w-4 h-4" /></div>
                                        <span className="text-[11px] font-bold text-white/80 truncate leading-none">{goal.text}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Poster Final Footer */}
                    <div className="p-16 border-t border-white/10 bg-black/40 flex justify-between items-center shrink-0">
                        <div className="max-w-[70%]">
                            <p className="text-[13px] font-black text-indigo-400 uppercase tracking-[0.5em] mb-4">LEADERSHIP VISION</p>
                            <p className="text-xl font-black text-white/60 italic leading-relaxed">"{t.visionNote}"</p>
                        </div>
                        <div className="text-right flex flex-col items-end">
                            <div className="w-20 h-20 rounded-3xl bg-indigo-600 flex items-center justify-center mb-4 shadow-[0_0_40px_rgba(79,70,229,0.3)]">
                                <IconShield className="w-10 h-10 text-white" />
                            </div>
                            <span className="text-[10px] font-black text-white/20 uppercase tracking-[0.3em]">STRATEGIC PERFORMANCE CERTIFIED</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconCalendar, IconChart, IconShield, IconBrain, IconArrowRight, IconActivity, IconBriefcase, IconUsers, IconPrinter, IconAward, IconTrendingUp, IconClock, IconStar, IconTrophy } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';
import * as htmlToImage from 'html-to-image';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف کاری (Business)', color: 'from-blue-600 to-indigo-700', type: 'business' as const },
    { id: 'cat2', title: 'توسعه فردی (Personal)', color: 'from-emerald-500 to-teal-700', type: 'personal' as const },
    { id: 'cat3', title: 'سلامتی و لایف‌استایل', color: 'from-orange-500 to-rose-600', type: 'personal' as const },
    { id: 'cat4', title: 'اهداف مالی', color: 'from-amber-400 to-yellow-600', type: 'personal' as const },
    { id: 'cat5', title: 'سایر موارد', color: 'from-purple-500 to-indigo-800', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isExporting, setIsExporting] = useState(false);
    const [editingTitleId, setEditingTitleId] = useState<string | null>(null);
    const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

    const posterRef = useRef<HTMLDivElement>(null);
    const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');
    const canEdit = selectedUserId === currentUser.id;

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    // Data Transformation: Separate Active and Achieved
    const { activeView, historyView } = useMemo(() => {
        if (!currentUserGoals) return { activeView: [], historyView: [] };

        const history: (GoalTask & { categoryName: string, categoryColor: string })[] = [];
        const active = currentUserGoals.categories.map(cat => {
            const activeTasks = cat.tasks.filter(t => !t.isCompleted);
            const completedTasks = cat.tasks.filter(t => t.isCompleted);

            completedTasks.forEach(ct => {
                history.push({ ...ct, categoryName: cat.title, categoryColor: cat.color });
            });

            return { ...cat, tasks: activeTasks };
        });

        return { activeView: active, historyView: history };
    }, [currentUserGoals]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => {
            c.tasks.forEach(t => {
                total++;
                if (t.isCompleted) done++;
            });
        });
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const t = {
      fa: {
        title: 'مهندسی اهداف و دستاوردها',
        daily: 'امروز', weekly: 'هفتگی', monthly: 'ماهانه', yearly: 'سالانه', five_year: '۵ ساله',
        viewMode: 'تایم‌لاین جاری:',
        addGoal: 'افزودن هدف جدید',
        progress: 'بهره‌وری کل',
        empty: 'هدف فعالی در این بخش ندارید.',
        print: 'خروجی پستر استراتژیک (PNG)',
        exporting: 'در حال رندر محتوا...',
        reportTitle: 'سند راهبردی و نقشه راه موفقیت',
        visionNote: 'تمرکز بر اهداف، تفاوت میان افراد موفق و افراد بسیار موفق است.',
        historyTitle: 'تالار موفقیت و تاریخچه پیروزی‌ها',
        historySub: 'اهدافی که با تلاش شما محقق شدند',
        achieved: 'هدف فتح شده',
        restore: 'بازگشت به لیست جاری',
        breakDown: 'Break Down (خرد کردن)'
      },
      en: {
        title: 'Goals & Achievements Eng.',
        daily: 'Daily', weekly: 'Weekly', monthly: 'Monthly', yearly: 'Yearly', five_year: '5-Year',
        viewMode: 'Active Timeline:',
        addGoal: 'Add New Goal',
        progress: 'Total Performance',
        empty: 'No active goals here.',
        print: 'Export Strategic Poster',
        exporting: 'Rendering Content...',
        reportTitle: 'Strategic Performance Roadmap',
        visionNote: 'Discipline is the bridge between goals and accomplishment.',
        historyTitle: 'Hall of Fame & Victory History',
        historySub: 'Goals achieved through your efforts',
        achieved: 'Goals Achieved',
        restore: 'Restore to Active',
        breakDown: 'Break Down'
      }
    }[lang];

    const selectedPerson = useMemo(() => personnel.find(p => p.id === selectedUserId), [personnel, selectedUserId]);

    const handleExportImage = async () => {
        if (!posterRef.current || isExporting) return;
        setIsExporting(true);
        try {
            await new Promise(r => setTimeout(r, 1000));
            const dataUrl = await htmlToImage.toPng(posterRef.current, {
                quality: 1,
                pixelRatio: 4, // Ultra high quality
                backgroundColor: '#020617' 
            });

            const link = document.createElement('a');
            link.download = `Strategic-Performance-${selectedPerson?.fullName}-${activePeriod}.png`;
            link.href = dataUrl;
            link.click();
        } catch (err) {
            console.error(err);
            alert('خطا در تولید عکس.');
        } finally {
            setIsExporting(false);
        }
    };

    const handleAddTask = (catId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const taskText = window.prompt(lang === 'fa' ? 'عنوان هدف جدید:' : 'New Goal Title:');
        if (!taskText) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: taskText, isCompleted: false, subTasks: [] }] } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const newCompleted = !t.isCompleted; return { ...t, isCompleted: newCompleted, subTasks: t.subTasks?.map(st => ({ ...st, isCompleted: newCompleted })) }; } return t; }) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleAddSubTask = (catId: string, taskId: string, text: string) => {
        if (!canEdit || !currentUserGoals || !text.trim()) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, subTasks: [...(t.subTasks || []), { id: `st-${Date.now()}`, text, isCompleted: false }], isCompleted: false } : t) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleSubTask = (catId: string, taskId: string, subId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const updatedSubTasks = t.subTasks?.map(st => st.id === subId ? { ...st, isCompleted: !st.isCompleted } : st); return { ...t, subTasks: updatedSubTasks, isCompleted: updatedSubTasks?.every(st => st.isCompleted) || false }; } return t; }) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    if (isLoading) return <div className="p-20 text-center animate-pulse text-indigo-600 font-black text-xl">در حال همگام‌سازی اهداف استراتژیک...</div>;

    const periodIcons: Record<string, React.ReactNode> = {
        daily: <IconClock className="w-4 h-4" />,
        weekly: <IconCalendar className="w-4 h-4" />,
        monthly: <IconActivity className="w-4 h-4" />,
        yearly: <IconAward className="w-4 h-4" />,
        five_year: <IconTrendingUp className="w-4 h-4" />
    };

    return (
        <div className="space-y-12 pb-32">
            {/* --- DASHBOARD UI --- */}
            <div className="space-y-12 animate-fade-in">
                {/* Header Widget */}
                <div className="bg-white p-10 rounded-[3.5rem] shadow-2xl border border-gray-100 flex flex-col lg:flex-row gap-12 items-center relative overflow-hidden ring-1 ring-black/5">
                    <div className="absolute top-0 left-0 w-80 h-80 bg-indigo-500/5 rounded-full blur-3xl -translate-x-1/2 -translate-y-1/2"></div>
                    <div className="shrink-0 w-full lg:w-1/3 z-10">
                        <h2 className="text-4xl font-black text-gray-900 mb-3 tracking-tighter">{t.title}</h2>
                        <div className="flex items-center gap-3 mb-8">
                            <span className="text-xs font-black text-gray-400 uppercase tracking-widest">{t.viewMode}</span>
                            <span className="px-4 py-1.5 bg-indigo-600 text-white rounded-full text-[10px] font-black uppercase shadow-lg shadow-indigo-200">
                                {t[activePeriod as keyof typeof t.fa]}
                            </span>
                        </div>
                        <div className="bg-gray-100 p-2 rounded-[2rem] mb-8 grid grid-cols-5 gap-2 border border-gray-200 shadow-inner">
                            {['daily', 'weekly', 'monthly', 'yearly', 'five_year'].map(p => (
                                <button key={p} onClick={() => { setActivePeriod(p as GoalPeriod); setExpandedTaskId(null); }} className={`flex flex-col items-center justify-center py-4 rounded-2xl transition-all duration-500 ${activePeriod === p ? `bg-white text-indigo-600 shadow-xl scale-110 z-10` : `text-gray-400 hover:text-gray-600 hover:bg-white/50`}`}>
                                    {periodIcons[p]}
                                    <span className="text-[8px] font-black mt-1 uppercase">{t[p as keyof typeof t.fa]}</span>
                                </button>
                            ))}
                        </div>
                        <button onClick={handleExportImage} disabled={isExporting} className="w-full py-5 bg-slate-900 text-white rounded-3xl text-sm font-black flex items-center justify-center gap-4 transition-all hover:bg-black hover:scale-[1.02] shadow-2xl active:scale-95 disabled:opacity-50">
                            {isExporting ? <><div className="w-5 h-5 border-3 border-white/30 border-t-white rounded-full animate-spin"></div> {t.exporting}</> : <><IconPrinter className="w-6 h-6" /> {t.print}</>}
                        </button>
                    </div>

                    <div className="flex flex-col items-center gap-4 lg:border-r lg:px-14 border-gray-100 z-10">
                        <div className="relative w-48 h-48 flex items-center justify-center">
                            <svg className="w-full h-full transform -rotate-90"><circle cx="96" cy="96" r="84" stroke="currentColor" strokeWidth="16" fill="transparent" className="text-gray-100" /><circle cx="96" cy="96" r="84" stroke="currentColor" strokeWidth="16" fill="transparent" strokeDasharray={527} strokeDashoffset={527 - (stats.percent / 100) * 527} className="transition-all duration-1000 ease-out text-indigo-600" strokeLinecap="round" /></svg>
                            <div className="absolute inset-0 flex flex-col items-center justify-center"><span className="text-5xl font-black text-gray-900">{stats.percent}%</span><span className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-2">{t.progress}</span></div>
                        </div>
                    </div>

                    <div className="flex-grow space-y-4 w-full">
                        {isMaster && (
                            <div className="p-6 bg-indigo-50 rounded-[2.5rem] border border-indigo-100 mb-4">
                                <label className="text-[10px] font-black text-indigo-400 uppercase block mb-3">نمایش اهداف پرسنل:</label>
                                <select className="w-full bg-white border border-indigo-100 rounded-2xl px-5 py-3 text-sm font-bold shadow-sm outline-none focus:ring-2 focus:ring-indigo-500" value={selectedUserId} onChange={(e) => setSelectedUserId(e.target.value)}>
                                    {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                                </select>
                            </div>
                        )}
                        <div className="grid grid-cols-2 gap-3">
                            <div className="bg-gray-50 p-4 rounded-3xl border border-gray-100"><span className="text-[10px] font-black text-gray-400 uppercase block mb-1">دستاوردها</span><span className="text-xl font-black text-indigo-600">{stats.done}</span></div>
