                    <div className="p-16 flex justify-between items-center bg-white/[0.03] backdrop-blur-3xl border-b border-white/10">
                        <div className="flex items-center gap-10">
                            <div className="w-40 h-40 rounded-[3.5rem] p-1 bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 shadow-[0_0_50px_rgba(79,70,229,0.3)]">
                                <div className="w-full h-full rounded-[3.3rem] bg-[#020617] p-1 overflow-hidden">
                                    {selectedPerson?.avatar ? <img src={selectedPerson.avatar} className="w-full h-full object-cover rounded-[3rem]" /> : <div className="w-full h-full flex items-center justify-center text-7xl font-black text-white/10 uppercase">{selectedPerson?.fullName.charAt(0)}</div>}
