                    </div>

                    {/* Strategic Data Banner */}
                    <div className="px-16 py-10 flex justify-between items-center bg-gradient-to-r from-indigo-600 to-blue-700 shadow-[0_10px_40px_rgba(0,0,0,0.3)]">
                        <div className="flex items-center gap-6">
                            <div className="w-14 h-14 rounded-2xl bg-white/10 backdrop-blur-md flex items-center justify-center border border-white/20"><IconShield className="w-7 h-7 text-white" /></div>
                            <h2 className="text-3xl font-black uppercase tracking-tight">{t.reportTitle}</h2>
                        </div>
                        <div className="text-right font-black uppercase tracking-widest text-xs opacity-90 dir-ltr">
                           PERIOD: {activePeriod.toUpperCase()} // CYCLE: {new Date().getFullYear()}
                        </div>
                    </div>

                    {/* Main Content: Two Columns of Active Goals */}
                    <div className="flex-grow p-16 grid grid-cols-2 gap-12 content-start">
                        {activeView.map((cat) => (
                            <div key={cat.id} className="bg-white/[0.03] border border-white/5 rounded-[3.5rem] p-10 flex flex-col gap-10 shadow-inner relative overflow-hidden backdrop-blur-sm">
                                <div className={`absolute top-0 right-0 w-2 h-full bg-gradient-to-b ${cat.color} opacity-40`}></div>
