                                    <div className="bg-white/5 px-4 py-1.5 rounded-full border border-white/10 text-[11px] font-black text-indigo-400">{cat.tasks.length} ACTIVE</div>
                                </div>
                                <div className="space-y-10">
                                    {cat.tasks.map((task) => (
                                        <div key={task.id} className="flex gap-8 relative">
                                            <div className="w-7 h-7 rounded-xl border-2 border-indigo-500/40 mt-1.5 shrink-0 shadow-[0_0_15px_rgba(79,70,229,0.2)]"></div>
                                            <div className="flex-grow min-w-0">
                                                <div className="text-xl font-bold text-gray-100 leading-tight mb-4">{task.text}</div>
                                                {task.subTasks && task.subTasks.length > 0 && (
                                                    <div className="space-y-4 pl-10 border-r-2 border-indigo-500/20 py-1">
                                                        {task.subTasks.map(st => (
                                                            <div key={st.id} className="text-sm font-bold text-white/40 flex items-center gap-4">
                                                                <div className={`w-2.5 h-2.5 rounded-full ${st.isCompleted ? 'bg-indigo-500 shadow-[0_0_8px_rgba(79,70,229,0.8)]' : 'bg-white/10'}`}></div>
                                                                <span className={st.isCompleted ? 'line-through opacity-20' : ''}>{st.text}</span>
                                                            </div>
                                                        ))}
                                                    </div>
                                                )}
                                            </div>
