                                    ))}
                                    {cat.tasks.length === 0 && <div className="text-white/10 italic text-center py-10 tracking-widest text-sm">NO PENDING OBJECTIVES</div>}
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Hall of Fame Footer: Success Section on Poster */}
                    {historyView.length > 0 && (
                        <div className="mx-16 mb-16 p-12 bg-indigo-500/5 border border-amber-500/30 rounded-[4rem] relative overflow-hidden backdrop-blur-md">
                            <div className="absolute -right-10 -top-10 opacity-[0.03] rotate-12"><IconTrophy className="w-64 h-64 text-amber-500" /></div>
                            <h3 className="text-2xl font-black text-amber-400 mb-10 uppercase tracking-[0.4em] flex items-center gap-4">
                                <div className="p-3 bg-amber-400/20 rounded-2xl"><IconAward className="w-8 h-8" /></div>
                                {t.historyTitle}
                            </h3>
                            <div className="grid grid-cols-3 gap-8">
                                {historyView.slice(0, 9).map((goal, i) => (
                                    <div key={i} className="flex items-center gap-5 bg-white/5 p-6 rounded-[2rem] border border-white/5 shadow-sm">
