                    {/* Final Footer Bar */}
                    <div className="p-16 border-t border-white/10 bg-black/60 flex justify-between items-center shrink-0">
                        <div className="max-w-[70%]">
                            <p className="text-[14px] font-black text-indigo-400 uppercase tracking-[0.6em] mb-4">CORE LEADERSHIP PHILOSOPHY</p>
                            <p className="text-2xl font-black text-white/60 italic leading-relaxed">"{t.visionNote}"</p>
                        </div>
                        <div className="text-right flex flex-col items-end">
                            <div className="w-24 h-24 rounded-[2.5rem] bg-indigo-600 flex items-center justify-center mb-5 shadow-[0_0_50px_rgba(79,70,229,0.4)] border border-white/20">
                                <IconShield className="w-12 h-12 text-white" />
                            </div>
                            <span className="text-[11px] font-black text-white/30 uppercase tracking-[0.4em]">VERIFIED STRATEGIC PERFORMANCE</span>
