        </div>
    );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconCalendar, IconChart, IconShield, IconBrain, IconArrowRight, IconActivity, IconBriefcase, IconUsers, IconPrinter, IconAward, IconTrendingUp, IconClock, IconStar, IconTrophy } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';
import * as htmlToImage from 'html-to-image';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف کاری (Business)', color: 'from-blue-600 to-indigo-700', type: 'business' as const },
    { id: 'cat2', title: 'توسعه فردی (Personal)', color: 'from-emerald-500 to-teal-700', type: 'personal' as const },
    { id: 'cat3', title: 'سلامتی و لایف‌استایل', color: 'from-orange-500 to-rose-600', type: 'personal' as const },
    { id: 'cat4', title: 'اهداف مالی', color: 'from-amber-400 to-yellow-600', type: 'personal' as const },
    { id: 'cat5', title: 'سایر موارد', color: 'from-purple-500 to-indigo-800', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isExporting, setIsExporting] = useState(false);
    const [editingTitleId, setEditingTitleId] = useState<string | null>(null);
    const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

    const posterRef = useRef<HTMLDivElement>(null);
    const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');
    const canEdit = selectedUserId === currentUser.id;

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    // Split goals: Active and Achieved (preserving subtasks)
    const { activeView, historyView } = useMemo(() => {
        if (!currentUserGoals) return { activeView: [], historyView: [] };

        const history: (GoalTask & { categoryName: string, categoryColor: string })[] = [];
        const active = currentUserGoals.categories.map(cat => {
            const activeTasks = cat.tasks.filter(t => !t.isCompleted);
            const completedTasks = cat.tasks.filter(t => t.isCompleted);

            completedTasks.forEach(ct => {
                history.push({ ...ct, categoryName: cat.title, categoryColor: cat.color });
            });

            return { ...cat, tasks: activeTasks };
        });

        return { activeView: active, historyView: history };
    }, [currentUserGoals]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => {
            c.tasks.forEach(t => {
                total++;
                if (t.isCompleted) done++;
            });
        });
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const t = {
      fa: {
        title: 'مهندسی اهداف و دستاوردها',
        daily: 'امروز', weekly: 'هفتگی', monthly: 'ماهانه', yearly: 'سالانه', five_year: '۵ ساله',
        viewMode: 'تایم‌لاین جاری:',
        addGoal: 'افزودن هدف جدید',
        progress: 'بهره‌وری کل',
        empty: 'هدف فعالی در این بخش ندارید.',
        print: 'خروجی پستر استراتژیک (PNG)',
        exporting: 'در حال رندر محتوا...',
        reportTitle: 'سند راهبردی و نقشه راه موفقیت',
        visionNote: 'نظم و تمرکز بر اهداف، مرز میان رویا و واقعیت است.',
        historyTitle: 'تالار موفقیت و تاریخچه پیروزی‌ها',
        historySub: 'اهدافی که با تلاش شما محقق شدند',
        achieved: 'هدف فتح شده',
        restore: 'بازگشت به لیست جاری',
        breakDown: 'Break Down (خرد کردن هدف)'
      },
      en: {
        title: 'Goals & Achievements Eng.',
        daily: 'Daily', weekly: 'Weekly', monthly: 'Monthly', yearly: 'Yearly', five_year: '5-Year',
        viewMode: 'Active Timeline:',
        addGoal: 'Add New Goal',
        progress: 'Total Performance',
        empty: 'No active goals here.',
        print: 'Export Strategic Poster',
        exporting: 'Rendering Content...',
        reportTitle: 'Strategic Performance Roadmap',
        visionNote: 'Discipline is the bridge between goals and accomplishment.',
        historyTitle: 'Hall of Fame & Victory History',
        historySub: 'Goals achieved through your efforts',
        achieved: 'Goals Achieved',
        restore: 'Restore to Active',
        breakDown: 'Break Down'
      }
    }[lang];

    const selectedPerson = useMemo(() => personnel.find(p => p.id === selectedUserId), [personnel, selectedUserId]);

    const handleExportImage = async () => {
        if (!posterRef.current || isExporting) return;
        setIsExporting(true);
        try {
            await new Promise(r => setTimeout(r, 1200));
            const dataUrl = await htmlToImage.toPng(posterRef.current, {
                quality: 1,
                pixelRatio: 4, 
                backgroundColor: '#020617' 
            });

            const link = document.createElement('a');
            link.download = `Strategic-Poster-${selectedPerson?.fullName}-${activePeriod}.png`;
            link.href = dataUrl;
            link.click();
        } catch (err) {
            alert('خطا در تولید تصویر.');
        } finally {
            setIsExporting(false);
        }
    };

    const handleAddTask = (catId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const taskText = window.prompt(lang === 'fa' ? 'عنوان هدف جدید:' : 'New Goal Title:');
        if (!taskText) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: taskText, isCompleted: false, subTasks: [] }] } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleTask = (catIdOrTitle: string, taskId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            // Match by ID or Title (for history restore logic)
            if (c.id === catIdOrTitle || c.title === catIdOrTitle) {
                return { 
                    ...c, 
                    tasks: c.tasks.map(t => { 
                        if (t.id === taskId) { 
                            const newCompleted = !t.isCompleted; 
                            return { ...t, isCompleted: newCompleted, subTasks: t.subTasks?.map(st => ({ ...st, isCompleted: newCompleted })) }; 
                        } 
                        return t; 
                    }) 
                };
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleAddSubTask = (catId: string, taskId: string, text: string) => {
        if (!canEdit || !currentUserGoals || !text.trim()) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, subTasks: [...(t.subTasks || []), { id: `st-${Date.now()}`, text, isCompleted: false }], isCompleted: false } : t) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleSubTask = (catId: string, taskId: string, subId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const updatedSubTasks = t.subTasks?.map(st => st.id === subId ? { ...st, isCompleted: !st.isCompleted } : st); return { ...t, subTasks: updatedSubTasks, isCompleted: updatedSubTasks?.every(st => st.isCompleted) || false }; } return t; }) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    if (isLoading) return <div className="p-20 text-center animate-pulse text-indigo-600 font-black text-xl">در حال همگام‌سازی اهداف استراتژیک...</div>;

    const periodIcons: Record<string, React.ReactNode> = {
        daily: <IconClock className="w-4 h-4" />,
        weekly: <IconCalendar className="w-4 h-4" />,
        monthly: <IconActivity className="w-4 h-4" />,
        yearly: <IconAward className="w-4 h-4" />,
        five_year: <IconTrendingUp className="w-4 h-4" />
    };

    return (
        <div className="space-y-12 pb-32">
            {/* --- WEB UI --- */}
            <div className="space-y-12 animate-fade-in">
                {/* Header Widget */}
                <div className="bg-white p-10 rounded-[3.5rem] shadow-2xl border border-gray-100 flex flex-col lg:flex-row gap-12 items-center relative overflow-hidden ring-1 ring-black/5">
                    <div className="absolute top-0 left-0 w-80 h-80 bg-indigo-500/5 rounded-full blur-3xl -translate-x-1/2 -translate-y-1/2"></div>
                    <div className="shrink-0 w-full lg:w-1/3 z-10">
                        <h2 className="text-4xl font-black text-gray-900 mb-3 tracking-tighter">{t.title}</h2>
                        <div className="flex items-center gap-3 mb-8">
                            <span className="text-xs font-black text-gray-400 uppercase tracking-widest">{t.viewMode}</span>
                            <span className="px-4 py-1.5 bg-indigo-600 text-white rounded-full text-[10px] font-black uppercase shadow-lg shadow-indigo-200">
                                {t[activePeriod as keyof typeof t.fa]}
                            </span>
                        </div>
                        <div className="bg-gray-100 p-2 rounded-[2rem] mb-8 grid grid-cols-5 gap-2 border border-gray-200 shadow-inner">
                            {['daily', 'weekly', 'monthly', 'yearly', 'five_year'].map(p => (
                                <button key={p} onClick={() => { setActivePeriod(p as GoalPeriod); setExpandedTaskId(null); }} className={`flex flex-col items-center justify-center py-4 rounded-2xl transition-all duration-500 ${activePeriod === p ? `bg-white text-indigo-600 shadow-xl scale-110 z-10` : `text-gray-400 hover:text-gray-600 hover:bg-white/50`}`}>
                                    {periodIcons[p]}
                                    <span className="text-[8px] font-black mt-1 uppercase">{t[p as keyof typeof t.fa]}</span>
                                </button>
                            ))}
                        </div>
                        <button onClick={handleExportImage} disabled={isExporting} className="w-full py-5 bg-slate-900 text-white rounded-3xl text-sm font-black flex items-center justify-center gap-4 transition-all hover:bg-black hover:scale-[1.02] shadow-2xl active:scale-95 disabled:opacity-50">
                            {isExporting ? <><div className="w-5 h-5 border-3 border-white/30 border-t-white rounded-full animate-spin"></div> {t.exporting}</> : <><IconPrinter className="w-6 h-6" /> {t.print}</>}
                        </button>
                    </div>

                    <div className="flex flex-col items-center gap-4 lg:border-r lg:px-14 border-gray-100 z-10">
                        <div className="relative w-48 h-48 flex items-center justify-center">
                            <svg className="w-full h-full transform -rotate-90"><circle cx="96" cy="96" r="84" stroke="currentColor" strokeWidth="16" fill="transparent" className="text-gray-100" /><circle cx="96" cy="96" r="84" stroke="currentColor" strokeWidth="16" fill="transparent" strokeDasharray={527} strokeDashoffset={527 - (stats.percent / 100) * 527} className="transition-all duration-1000 ease-out text-indigo-600" strokeLinecap="round" /></svg>
                            <div className="absolute inset-0 flex flex-col items-center justify-center"><span className="text-5xl font-black text-gray-900">{stats.percent}%</span><span className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-2">{t.progress}</span></div>
                        </div>
                    </div>

                    <div className="flex-grow space-y-4 w-full">
                        {isMaster && (
