                        </div>
                    </div>
                </div>

                {/* Active Categories Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-5 gap-8">
                    {activeView.map((cat) => (
                        <div key={cat.id} className="bg-white rounded-[3rem] border border-gray-100 shadow-xl overflow-hidden flex flex-col min-h-[550px] group transition-all hover:shadow-2xl">
