                                    <button onClick={() => toggleTask(goal.categoryName, goal.id)} className="mt-2 self-end opacity-0 group-hover:opacity-100 transition-all text-indigo-600 text-[10px] font-black underline hover:text-indigo-800">{t.restore}</button>
