                    </div>
                )}
            </div>

            {/* --- ULTRA-PREMIUM STRATEGIC POSTER CANVAS (HIDDEN) --- */}
            <div style={{ position: 'fixed', left: '-9999px', top: 0 }}>
                <div ref={posterRef} className="flex flex-col bg-[#020617] overflow-hidden relative" style={{ width: '840px', height: '1188px', color: 'white' }}>
                    {/* Visual Art Accents */}
                    <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-indigo-600/30 rounded-full blur-[140px] -translate-y-1/2 translate-x-1/2"></div>
                    <div className="absolute bottom-0 left-0 w-[500px] h-[500px] bg-purple-600/20 rounded-full blur-[120px] translate-y-1/2 -translate-x-1/2"></div>
                    <div className="absolute top-1/4 right-1/4 w-[1px] h-[400px] bg-gradient-to-b from-transparent via-white/10 to-transparent rotate-45"></div>
                    <div className="absolute top-1/2 left-0 w-full h-full bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-[0.05] pointer-events-none"></div>

                    {/* Poster Header */}
                    <div className="p-16 flex justify-between items-center bg-white/[0.03] backdrop-blur-3xl border-b border-white/10">
