import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconCalendar, IconChart, IconShield, IconBrain, IconArrowRight, IconActivity, IconBriefcase, IconUsers, IconPrinter, IconAward, IconTrendingUp, IconClock, IconStar, IconTrophy, IconList } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';
import * as htmlToImage from 'html-to-image';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف تجاری و مالی', color: 'bg-indigo-600', type: 'business' as const },
    { id: 'cat2', title: 'توسعه فردی و مهارت', color: 'bg-emerald-600', type: 'personal' as const },
    { id: 'cat3', title: 'سلامتی و سبک زندگی', color: 'bg-rose-500', type: 'personal' as const },
    { id: 'cat4', title: 'پروژه‌های استراتژیک', color: 'bg-blue-500', type: 'business' as const },
    { id: 'cat5', title: 'سایر اولویت‌ها', color: 'bg-slate-600', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isExporting, setIsExporting] = useState(false);
    const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

    const posterRef = useRef<HTMLDivElement>(null);
    const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');
    const canEdit = selectedUserId === currentUser.id;

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    // Logical Separation for UI and Poster
    const { activeView, historyView } = useMemo(() => {
        if (!currentUserGoals) return { activeView: [], historyView: [] };

        const history: (GoalTask & { categoryTitle: string, categoryColor: string })[] = [];
        const active = currentUserGoals.categories.map(cat => {
            const activeTasks = cat.tasks.filter(t => !t.isCompleted);
            const completedTasks = cat.tasks.filter(t => t.isCompleted);

            completedTasks.forEach(ct => {
                history.push({ ...ct, categoryTitle: cat.title, categoryColor: cat.color });
            });

            return { ...cat, tasks: activeTasks };
        });

        return { activeView: active, historyView: history };
    }, [currentUserGoals]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => {
            c.tasks.forEach(t => {
                total++;
                if (t.isCompleted) done++;
            });
        });
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const t = {
        fa: {
            title: 'برنامه راهبردی عملکرد',
            daily: 'امروز', weekly: 'هفتگی', monthly: 'ماهانه', yearly: 'سالانه', five_year: '۵ ساله',
            viewMode: 'بازه زمانی:',
            addGoal: 'افزودن هدف جدید',
            progress: 'میزان تحقق اهداف',
            empty: 'لیست اهداف جاری خالی است.',
            print: 'دریافت نسخه چاپی (Poster)',
            exporting: 'در حال آماده‌سازی فایل...',
            reportTitle: 'سند استراتژیک و نقشه راه موفقیت',
            visionNote: 'نظم در اجرا، تفاوت میان سازمان‌های خوب و سازمان‌های عالی است.',
            historyTitle: 'تاریخچه موفقیت (Hall of Fame)',
            historySub: 'دستاوردها و اهداف محقق شده شما',
            achieved: 'موفقیت ثبت شده',
            restore: 'بازگشت به لیست',
            breakDown: 'گام‌های اجرایی (Breakdown)'
        },
        en: {
            title: 'Strategic Performance Roadmap',
            daily: 'Daily', weekly: 'Weekly', monthly: 'Monthly', yearly: 'Yearly', five_year: '5-Year',
            viewMode: 'Timeframe:',
            addGoal: 'Add New Objective',
            progress: 'Goal Completion Rate',
            empty: 'No active objectives.',
            print: 'Export Strategic Poster',
            exporting: 'Preparing File...',
            reportTitle: 'Strategic Plan & Achievement Roadmap',
            visionNote: 'Discipline in execution is what separates good organizations from great ones.',
            historyTitle: 'Success History (Hall of Fame)',
            historySub: 'Your achieved milestones and goals',
            achieved: 'Successes',
            restore: 'Restore to List',
            breakDown: 'Action Steps (Breakdown)'
        }
    }[lang];

    const handleExportImage = async () => {
        if (!posterRef.current || isExporting) return;
        setIsExporting(true);
        try {
            await new Promise(r => setTimeout(r, 1000));
            const dataUrl = await htmlToImage.toPng(posterRef.current, {
                quality: 1,
                pixelRatio: 3, 
                backgroundColor: '#ffffff' 
            });

            const link = document.createElement('a');
            link.download = `Strategic-Roadmap-${activePeriod}.png`;
            link.href = dataUrl;
            link.click();
        } catch (err) {
            alert('خطا در تولید تصویر.');
        } finally {
            setIsExporting(false);
        }
    };

    const handleAddTask = (catId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const taskText = window.prompt(lang === 'fa' ? 'عنوان هدف جدید را وارد کنید:' : 'Enter New Goal Title:');
        if (!taskText) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: taskText, isCompleted: false, subTasks: [] }] } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleTask = (catIdOrTitle: string, taskId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catIdOrTitle || c.title === catIdOrTitle) {
                return { 
                    ...c, 
                    tasks: c.tasks.map(t => { 
                        if (t.id === taskId) { 
                            const newCompleted = !t.isCompleted; 
                            return { ...t, isCompleted: newCompleted, subTasks: t.subTasks?.map(st => ({ ...st, isCompleted: newCompleted })) }; 
                        } 
                        return t; 
                    }) 
                };
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleAddSubTask = (catId: string, taskId: string, text: string) => {
        if (!canEdit || !currentUserGoals || !text.trim()) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, subTasks: [...(t.subTasks || []), { id: `st-${Date.now()}`, text, isCompleted: false }], isCompleted: false } : t) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleSubTask = (catId: string, taskId: string, subId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const updatedSubTasks = t.subTasks?.map(st => st.id === subId ? { ...st, isCompleted: !st.isCompleted } : st); return { ...t, subTasks: updatedSubTasks, isCompleted: updatedSubTasks?.every(st => st.isCompleted) || false }; } return t; }) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    if (isLoading) return <div className="p-20 text-center animate-pulse text-indigo-600 font-bold text-lg">در حال بارگذاری اهداف...</div>;

    return (
        <div className="space-y-10 pb-20">
            {/* --- WEB UI --- */}
            <div className="space-y-10 animate-fade-in">
                {/* Clean White Dashboard Header */}
                <div className="bg-white p-8 rounded-[2rem] shadow-xl border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-8">
                    <div className="flex items-center gap-6">
                        <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center text-white shadow-lg shadow-indigo-100">
                            <IconTarget className="w-10 h-10" />
                        </div>
                        <div>
                            <h2 className="text-3xl font-black text-gray-900 tracking-tight">{t.title}</h2>
                            <div className="flex items-center gap-2 mt-2">
                                <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{t.viewMode}</span>
                                <span className="px-3 py-1 bg-gray-100 text-gray-600 rounded-full text-[10px] font-black">{t[activePeriod as keyof typeof t.fa]}</span>
                            </div>
                        </div>
                    </div>

                    <div className="flex bg-gray-100 p-1.5 rounded-2xl">
                        {['daily', 'weekly', 'monthly', 'yearly', 'five_year'].map(p => (
                            <button key={p} onClick={() => setActivePeriod(p as GoalPeriod)} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${activePeriod === p ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>
                                {t[p as keyof typeof t.fa]}
                            </button>
                        ))}
                    </div>

                    <div className="flex items-center gap-6">
                        <div className="text-center">
                            <div className="text-3xl font-black text-indigo-600">{stats.percent}%</div>
                            <div className="text-[10px] font-bold text-gray-400 uppercase">{t.progress}</div>
                        </div>
                        <button onClick={handleExportImage} disabled={isExporting} className="bg-slate-900 text-white px-6 py-3 rounded-2xl text-sm font-bold flex items-center gap-3 hover:bg-black transition-all shadow-xl active:scale-95 disabled:opacity-50">
                            {isExporting ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : <IconPrinter className="w-5 h-5" />}
                            {t.print}
                        </button>
                    </div>
                </div>

                {isMaster && (
                    <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm flex items-center gap-4">
                        <span className="text-xs font-bold text-gray-500">نمایش اهداف:</span>
                        <select className="bg-gray-50 border-none rounded-xl px-4 py-2 text-sm font-bold text-indigo-600 outline-none" value={selectedUserId} onChange={(e) => setSelectedUserId(e.target.value)}>
                            {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                        </select>
                    </div>
                )}

                {/* Categories Grid (Active) */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
                    {activeView.map((cat) => (
                        <div key={cat.id} className="bg-white rounded-[2rem] border border-gray-100 shadow-lg flex flex-col min-h-[500px] overflow-hidden group">
                            <div className={`p-5 text-center text-white font-black text-xs uppercase tracking-widest ${cat.color}`}>
                                {cat.title}
                            </div>
                            <div className="flex-grow p-4 space-y-4 overflow-y-auto custom-scrollbar">
                                {cat.tasks.map((task) => (
                                    <div key={task.id} className="bg-gray-50/50 rounded-2xl border border-gray-100 p-4 hover:bg-white transition-all shadow-sm">
                                        <div className="flex items-start gap-3">
                                            <button onClick={() => toggleTask(cat.id, task.id)} className="w-6 h-6 rounded-lg border-2 border-indigo-200 bg-white flex items-center justify-center shrink-0 transition-all hover:border-indigo-600">
                                                {task.isCompleted && <IconCheck className="w-4 h-4 text-indigo-600" />}
                                            </button>
                                            <div className="flex-grow">
                                                <span onClick={() => setExpandedTaskId(expandedTaskId === task.id ? null : task.id)} className="text-[13px] font-bold text-gray-800 cursor-pointer block leading-tight">{task.text}</span>
                                                {task.subTasks && task.subTasks.length > 0 && (
                                                    <span className="text-[9px] font-black text-gray-400 mt-1 block">{(task.subTasks.filter(s=>s.isCompleted).length)} از {task.subTasks.length} گام انجام شده</span>
                                                )}
                                            </div>
                                        </div>

                                        {expandedTaskId === task.id && (
                                            <div className="mt-4 space-y-2 border-r-2 border-indigo-100 pr-3 mr-2 animate-slide-in">
                                                {task.subTasks?.map(st => (
                                                    <div key={st.id} className="flex items-center gap-3 text-[11px] font-bold text-gray-500">
                                                        <button onClick={() => toggleSubTask(cat.id, task.id, st.id)} className={`w-4 h-4 rounded border flex items-center justify-center ${st.isCompleted ? 'bg-indigo-500 border-indigo-500 text-white' : 'bg-white border-gray-200'}`}>{st.isCompleted && <IconCheck className="w-3 h-3" />}</button>
                                                        <span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span>
                                                    </div>
                                                ))}
                                                {canEdit && (
                                                    <input className="w-full text-[10px] p-2 bg-white rounded-lg outline-none border border-gray-100 focus:border-indigo-200" placeholder="Break Down (اینتر)..." onKeyDown={e => { if (e.key === 'Enter' && (e.target as HTMLInputElement).value.trim()) { handleAddSubTask(cat.id, task.id, (e.target as HTMLInputElement).value); (e.target as HTMLInputElement).value = ''; } }} />
                                                )}
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                            {canEdit && (
                                <div className="p-4 border-t border-gray-50"><button onClick={() => handleAddTask(cat.id)} className="w-full py-2.5 bg-gray-50 text-gray-400 text-[11px] font-black rounded-xl hover:bg-indigo-50 hover:text-indigo-600 transition-all flex items-center justify-center gap-2"><IconPlus className="w-4 h-4" /> {t.addGoal}</button></div>
                            )}
                        </div>
                    ))}
                </div>

                {/* Success History Section */}
                {historyView.length > 0 && (
                    <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-xl animate-fade-in">
                        <div className="flex items-center gap-4 mb-8">
                            <div className="p-3 bg-amber-100 text-amber-600 rounded-2xl"><IconTrophy className="w-6 h-6" /></div>
                            <div>
                                <h3 className="text-2xl font-black text-gray-900">{t.historyTitle}</h3>
                                <p className="text-sm text-gray-400 font-bold">{t.historySub}</p>
                            </div>
                        </div>
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                            {historyView.map((goal, idx) => (
                                <div key={idx} className="bg-gray-50 p-4 rounded-2xl border border-gray-200 flex flex-col gap-3 relative group overflow-hidden">
                                    <div className="flex items-center gap-3">
                                        <IconStar className="w-5 h-5 text-amber-500 fill-current" />
                                        <div className="min-w-0">
                                            <h4 className="text-[13px] font-black text-gray-800 line-through opacity-40 truncate">{goal.text}</h4>
                                            <p className="text-[9px] font-bold text-gray-400 uppercase mt-0.5">{goal.categoryTitle}</p>
                                        </div>
                                    </div>
                                    {goal.subTasks && goal.subTasks.length > 0 && (
                                        <div className="pr-4 space-y-1">
                                            {goal.subTasks.map(st => (
                                                <div key={st.id} className="text-[10px] text-gray-400 flex items-center gap-2">
                                                    <IconCheck className="w-3 h-3 text-green-500" /> {st.text}
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                    <button onClick={() => toggleTask(goal.categoryTitle, goal.id)} className="mt-2 text-[10px] text-indigo-600 font-bold opacity-0 group-hover:opacity-100 transition-opacity underline">{t.restore}</button>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>

            {/* --- MINIMAL WHITE POSTER CANVAS (HIDDEN) --- */}
            <div style={{ position: 'fixed', left: '-9999px', top: 0 }}>
                <div ref={posterRef} className="flex flex-col bg-white overflow-hidden p-20 relative" style={{ width: '840px', height: '1188px' }}>
                    {/* Minimal Border Framework */}
                    <div className="absolute inset-10 border-[12px] border-gray-50 pointer-events-none"></div>
                    <div className="absolute inset-14 border border-gray-200 pointer-events-none"></div>

                    {/* Poster Header */}
                    <div className="flex justify-between items-start mb-16 relative z-10">
                        <div className="flex items-center gap-8">
                            <div className="w-32 h-32 rounded-3xl overflow-hidden border-2 border-gray-100 bg-gray-50 shadow-sm">
                                {selectedPerson?.avatar ? <img src={selectedPerson.avatar} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-4xl font-black text-gray-300">{selectedPerson?.fullName.charAt(0)}</div>}
                            </div>
                            <div>
                                <h1 className="text-5xl font-black text-gray-900 mb-2 tracking-tighter">{selectedPerson?.fullName}</h1>
                                <div className="flex gap-2">
                                    {selectedPerson?.roles.map(r => <span key={r} className="bg-gray-100 text-gray-500 px-4 py-1 rounded-lg text-[11px] font-black uppercase tracking-widest">{r}</span>)}
                                </div>
                            </div>
                        </div>
                        <div className="text-right">
                            <div className="text-7xl font-black text-indigo-600 leading-none mb-2">{stats.percent}%</div>
                            <div className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{t.progress}</div>
                        </div>
                    </div>

                    {/* Strategic Banner */}
                    <div className="bg-slate-900 text-white p-10 rounded-2xl mb-12 flex justify-between items-center shadow-xl">
                        <div className="flex items-center gap-4">
                            <IconShield className="w-8 h-8" />
                            <h2 className="text-2xl font-black uppercase tracking-tight">{t.reportTitle}</h2>
                        </div>
                        <div className="font-mono text-sm opacity-60">
                            {activePeriod.toUpperCase()} / {new Date().getFullYear()}
                        </div>
                    </div>

                    {/* Content Section: Active Objectives (Simple 2-Column Grid) */}
                    <div className="flex-grow grid grid-cols-2 gap-x-12 gap-y-12 content-start mb-16">
                        {activeView.map((cat) => (
                            <div key={cat.id} className="space-y-6">
                                <div className="flex items-center gap-3 border-b-2 border-gray-100 pb-3">
                                    <div className={`w-3 h-3 rounded-full ${cat.color}`}></div>
                                    <h3 className="text-xl font-black text-gray-800 uppercase tracking-widest">{cat.title}</h3>
                                </div>
                                <div className="space-y-6">
                                    {cat.tasks.map((task) => (
                                        <div key={task.id} className="flex gap-4">
                                            <div className="w-5 h-5 rounded-full border-2 border-gray-300 mt-1 shrink-0"></div>
                                            <div className="flex-grow min-w-0">
                                                <div className="text-lg font-bold text-gray-800 leading-tight mb-2">{task.text}</div>
                                                {task.subTasks && task.subTasks.length > 0 && (
                                                    <div className="space-y-2 pl-6 border-r-2 border-gray-100 mt-3">
                                                        {task.subTasks.map(st => (
                                                            <div key={st.id} className="text-xs font-bold text-gray-400 flex items-center gap-3">
                                                                <div className={`w-2 h-2 rounded-full ${st.isCompleted ? 'bg-indigo-500' : 'bg-gray-100'}`}></div>
                                                                <span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span>
                                                            </div>
                                                        ))}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                    {cat.tasks.length === 0 && <div className="text-gray-300 text-sm font-bold italic">NO ACTIVE OBJECTIVES</div>}
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* History Section on Poster */}
                    {historyView.length > 0 && (
                        <div className="bg-gray-50 p-10 rounded-3xl border border-gray-100 relative mb-12">
                             <div className="absolute top-0 right-0 p-8 opacity-5"><IconAward className="w-32 h-32" /></div>
                             <h3 className="text-lg font-black text-amber-600 mb-6 uppercase tracking-widest flex items-center gap-3"><IconAward className="w-5 h-5" /> {t.historyTitle}</h3>
                             <div className="grid grid-cols-3 gap-6">
                                {historyView.slice(0, 9).map((goal, i) => (
                                    <div key={i} className="flex flex-col gap-2">
                                        <div className="flex items-center gap-2">
                                            <IconCheck className="w-4 h-4 text-green-500" />
                                            <span className="text-[12px] font-bold text-gray-700 truncate">{goal.text}</span>
                                        </div>
                                        {goal.subTasks && goal.subTasks.length > 0 && (
                                            <div className="text-[9px] text-gray-400 pr-5 truncate">
                                                {goal.subTasks.length} Breakdown Steps
                                            </div>
                                        )}
                                    </div>
                                ))}
                             </div>
                        </div>
                    )}

                    {/* Footer Area */}
                    <div className="border-t border-gray-200 pt-10 flex justify-between items-end">
                        <div className="max-w-[70%]">
                            <p className="text-[10px] font-black text-indigo-600 uppercase tracking-[0.3em] mb-3">LEADERSHIP VISION</p>
                            <p className="text-xl font-bold text-gray-500 italic leading-relaxed">"{t.visionNote}"</p>
                        </div>
                        <div className="flex flex-col items-end">
                            <div className="w-24 h-24 bg-indigo-600 flex items-center justify-center rounded-3xl shadow-xl shadow-indigo-100 mb-4">
                                <IconShield className="w-10 h-10 text-white" />
                            </div>
                            <span className="text-[9px] font-black text-gray-300 uppercase tracking-widest">STRATEGIC PERFORMANCE CERTIFIED</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconCalendar, IconChart, IconShield, IconBrain, IconArrowRight, IconActivity, IconBriefcase, IconUsers, IconPrinter, IconAward, IconTrendingUp, IconClock, IconStar, IconTrophy, IconList } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';
import * as htmlToImage from 'html-to-image';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف تجاری و مالی', color: 'bg-indigo-600', type: 'business' as const },
    { id: 'cat2', title: 'توسعه فردی و مهارت', color: 'bg-emerald-600', type: 'personal' as const },
    { id: 'cat3', title: 'سلامتی و سبک زندگی', color: 'bg-rose-500', type: 'personal' as const },
    { id: 'cat4', title: 'پروژه‌های استراتژیک', color: 'bg-blue-500', type: 'business' as const },
    { id: 'cat5', title: 'سایر اولویت‌ها', color: 'bg-slate-600', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isExporting, setIsExporting] = useState(false);
    const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

    const posterRef = useRef<HTMLDivElement>(null);
    const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');
    const canEdit = selectedUserId === currentUser.id;

    // Fix: Defined selectedPerson to resolve 'Cannot find name' errors in poster rendering
    const selectedPerson = useMemo(() => personnel.find(p => p.id === selectedUserId), [personnel, selectedUserId]);

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    // Logical Separation for UI and Poster
    const { activeView, historyView } = useMemo(() => {
        if (!currentUserGoals) return { activeView: [], historyView: [] };

        const history: (GoalTask & { categoryTitle: string, categoryColor: string })[] = [];
        const active = currentUserGoals.categories.map(cat => {
            const activeTasks = cat.tasks.filter(t => !t.isCompleted);
            const completedTasks = cat.tasks.filter(t => t.isCompleted);

            completedTasks.forEach(ct => {
                history.push({ ...ct, categoryTitle: cat.title, categoryColor: cat.color });
            });

            return { ...cat, tasks: activeTasks };
        });

        return { activeView: active, historyView: history };
    }, [currentUserGoals]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => {
            c.tasks.forEach(t => {
                total++;
                if (t.isCompleted) done++;
            });
        });
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const t = {
        fa: {
            title: 'برنامه راهبردی عملکرد',
            daily: 'امروز', weekly: 'هفتگی', monthly: 'ماهانه', yearly: 'سالانه', five_year: '۵ ساله',
            viewMode: 'بازه زمانی:',
            addGoal: 'افزودن هدف جدید',
            progress: 'میزان تحقق اهداف',
            empty: 'لیست اهداف جاری خالی است.',
            print: 'دریافت نسخه چاپی (Poster)',
            exporting: 'در حال آماده‌سازی فایل...',
            reportTitle: 'سند استراتژیک و نقشه راه موفقیت',
            visionNote: 'نظم در اجرا، تفاوت میان سازمان‌های خوب و سازمان‌های عالی است.',
            historyTitle: 'تاریخچه موفقیت (Hall of Fame)',
            historySub: 'دستاوردها و اهداف محقق شده شما',
            achieved: 'موفقیت ثبت شده',
            restore: 'بازگشت به لیست',
            breakDown: 'گام‌های اجرایی (Breakdown)'
        },
        en: {
            title: 'Strategic Performance Roadmap',
            daily: 'Daily', weekly: 'Weekly', monthly: 'Monthly', yearly: 'Yearly', five_year: '5-Year',
            viewMode: 'Timeframe:',
            addGoal: 'Add New Objective',
            progress: 'Goal Completion Rate',
            empty: 'No active objectives.',
            print: 'Export Strategic Poster',
            exporting: 'Preparing File...',
            reportTitle: 'Strategic Plan & Achievement Roadmap',
            visionNote: 'Discipline in execution is what separates good organizations from great ones.',
            historyTitle: 'Success History (Hall of Fame)',
            historySub: 'Your achieved milestones and goals',
            achieved: 'Successes',
            restore: 'Restore to List',
            breakDown: 'Action Steps (Breakdown)'
        }
    }[lang];

    const handleExportImage = async () => {
        if (!posterRef.current || isExporting) return;
        setIsExporting(true);
        try {
            await new Promise(r => setTimeout(r, 1000));
            const dataUrl = await htmlToImage.toPng(posterRef.current, {
                quality: 1,
                pixelRatio: 3, 
                backgroundColor: '#ffffff' 
            });

            const link = document.createElement('a');
            link.download = `Strategic-Roadmap-${activePeriod}.png`;
            link.href = dataUrl;
            link.click();
        } catch (err) {
            alert('خطا در تولید تصویر.');
        } finally {
            setIsExporting(false);
        }
    };

    const handleAddTask = (catId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const taskText = window.prompt(lang === 'fa' ? 'عنوان هدف جدید را وارد کنید:' : 'Enter New Goal Title:');
        if (!taskText) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: taskText, isCompleted: false, subTasks: [] }] } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleTask = (catIdOrTitle: string, taskId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => {
            if (c.id === catIdOrTitle || c.title === catIdOrTitle) {
                return { 
                    ...c, 
                    tasks: c.tasks.map(t => { 
                        if (t.id === taskId) { 
                            const newCompleted = !t.isCompleted; 
                            return { ...t, isCompleted: newCompleted, subTasks: t.subTasks?.map(st => ({ ...st, isCompleted: newCompleted })) }; 
                        } 
                        return t; 
                    }) 
                };
            }
            return c;
        });
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleAddSubTask = (catId: string, taskId: string, text: string) => {
        if (!canEdit || !currentUserGoals || !text.trim()) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, subTasks: [...(t.subTasks || []), { id: `st-${Date.now()}`, text, isCompleted: false }], isCompleted: false } : t) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleSubTask = (catId: string, taskId: string, subId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const updatedSubTasks = t.subTasks?.map(st => st.id === subId ? { ...st, isCompleted: !st.isCompleted } : st); return { ...t, subTasks: updatedSubTasks, isCompleted: updatedSubTasks?.every(st => st.isCompleted) || false }; } return t; }) } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    if (isLoading) return <div className="p-20 text-center animate-pulse text-indigo-600 font-bold text-lg">در حال بارگذاری اهداف...</div>;

    return (
        <div className="space-y-10 pb-20">
            {/* --- WEB UI --- */}
            <div className="space-y-10 animate-fade-in">
                {/* Clean White Dashboard Header */}
                <div className="bg-white p-8 rounded-[2rem] shadow-xl border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-8">
                    <div className="flex items-center gap-6">
                        <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center text-white shadow-lg shadow-indigo-100">
                            <IconTarget className="w-10 h-10" />
                        </div>
                        <div>
                            <h2 className="text-3xl font-black text-gray-900 tracking-tight">{t.title}</h2>
                            <div className="flex items-center gap-2 mt-2">
                                <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{t.viewMode}</span>
                                <span className="px-3 py-1 bg-gray-100 text-gray-600 rounded-full text-[10px] font-black">{t[activePeriod as keyof typeof t.fa]}</span>
                            </div>
                        </div>
                    </div>

                    <div className="flex bg-gray-100 p-1.5 rounded-2xl">
                        {['daily', 'weekly', 'monthly', 'yearly', 'five_year'].map(p => (
                            <button key={p} onClick={() => setActivePeriod(p as GoalPeriod)} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${activePeriod === p ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>
                                {t[p as keyof typeof t.fa]}
                            </button>
                        ))}
                    </div>

                    <div className="flex items-center gap-6">
                        <div className="text-center">
                            <div className="text-3xl font-black text-indigo-600">{stats.percent}%</div>
                            <div className="text-[10px] font-bold text-gray-400 uppercase">{t.progress}</div>
                        </div>
                        <button onClick={handleExportImage} disabled={isExporting} className="bg-slate-900 text-white px-6 py-3 rounded-2xl text-sm font-bold flex items-center gap-3 hover:bg-black transition-all shadow-xl active:scale-95 disabled:opacity-50">
                            {isExporting ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : <IconPrinter className="w-5 h-5" />}
                            {t.print}
                        </button>
                    </div>
                </div>

                {isMaster && (
                    <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm flex items-center gap-4">
                        <span className="text-xs font-bold text-gray-500">نمایش اهداف:</span>
                        <select className="bg-gray-50 border-none rounded-xl px-4 py-2 text-sm font-bold text-indigo-600 outline-none" value={selectedUserId} onChange={(e) => setSelectedUserId(e.target.value)}>
                            {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                        </select>
                    </div>
                )}

                {/* Categories Grid (Active) */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
                    {activeView.map((cat) => (
                        <div key={cat.id} className="bg-white rounded-[2rem] border border-gray-100 shadow-lg flex flex-col min-h-[500px] overflow-hidden group">
                            <div className={`p-5 text-center text-white font-black text-xs uppercase tracking-widest ${cat.color}`}>
                                {cat.title}
                            </div>
                            <div className="flex-grow p-4 space-y-4 overflow-y-auto custom-scrollbar">
                                {cat.tasks.map((task) => (
                                    <div key={task.id} className="bg-gray-50/50 rounded-2xl border border-gray-100 p-4 hover:bg-white transition-all shadow-sm">
                                        <div className="flex items-start gap-3">
                                            <button onClick={() => toggleTask(cat.id, task.id)} className="w-6 h-6 rounded-lg border-2 border-indigo-200 bg-white flex items-center justify-center shrink-0 transition-all hover:border-indigo-600">
                                                {task.isCompleted && <IconCheck className="w-4 h-4 text-indigo-600" />}
                                            </button>
                                            <div className="flex-grow">
                                                <span onClick={() => setExpandedTaskId(expandedTaskId === task.id ? null : task.id)} className="text-[13px] font-bold text-gray-800 cursor-pointer block leading-tight">{task.text}</span>
                                                {task.subTasks && task.subTasks.length > 0 && (
                                                    <span className="text-[9px] font-black text-gray-400 mt-1 block">{(task.subTasks.filter(s=>s.isCompleted).length)} از {task.subTasks.length} گام انجام شده</span>
                                                )}
                                            </div>
                                        </div>

                                        {expandedTaskId === task.id && (
                                            <div className="mt-4 space-y-2 border-r-2 border-indigo-100 pr-3 mr-2 animate-slide-in">
                                                {task.subTasks?.map(st => (
                                                    <div key={st.id} className="flex items-center gap-3 text-[11px] font-bold text-gray-500">
                                                        <button onClick={() => toggleSubTask(cat.id, task.id, st.id)} className={`w-4 h-4 rounded border flex items-center justify-center ${st.isCompleted ? 'bg-indigo-500 border-indigo-500 text-white' : 'bg-white border-gray-200'}`}>{st.isCompleted && <IconCheck className="w-3 h-3" />}</button>
                                                        <span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span>
                                                    </div>
                                                ))}
                                                {canEdit && (
                                                    <input className="w-full text-[10px] p-2 bg-white rounded-lg outline-none border border-gray-100 focus:border-indigo-200" placeholder="Break Down (اینتر)..." onKeyDown={e => { if (e.key === 'Enter' && (e.target as HTMLInputElement).value.trim()) { handleAddSubTask(cat.id, task.id, (e.target as HTMLInputElement).value); (e.target as HTMLInputElement).value = ''; } }} />
                                                )}
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                            {canEdit && (
                                <div className="p-4 border-t border-gray-50"><button onClick={() => handleAddTask(cat.id)} className="w-full py-2.5 bg-gray-50 text-gray-400 text-[11px] font-black rounded-xl hover:bg-indigo-50 hover:text-indigo-600 transition-all flex items-center justify-center gap-2"><IconPlus className="w-4 h-4" /> {t.addGoal}</button></div>
                            )}
                        </div>
                    ))}
                </div>

                {/* Success History Section */}
                {historyView.length > 0 && (
                    <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-xl animate-fade-in">
                        <div className="flex items-center gap-4 mb-8">
                            <div className="p-3 bg-amber-100 text-amber-600 rounded-2xl"><IconTrophy className="w-6 h-6" /></div>
                            <div>
                                <h3 className="text-2xl font-black text-gray-900">{t.historyTitle}</h3>
                                <p className="text-sm text-gray-400 font-bold">{t.historySub}</p>
                            </div>
                        </div>
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                            {historyView.map((goal, idx) => (
                                <div key={idx} className="bg-gray-50 p-4 rounded-2xl border border-gray-200 flex flex-col gap-3 relative group overflow-hidden">
                                    <div className="flex items-center gap-3">
                                        <IconStar className="w-5 h-5 text-amber-500 fill-current" />
                                        <div className="min-w-0">
                                            <h4 className="text-[13px] font-black text-gray-800 line-through opacity-40 truncate">{goal.text}</h4>
                                            <p className="text-[9px] font-bold text-gray-400 uppercase mt-0.5">{goal.categoryTitle}</p>
                                        </div>
                                    </div>
                                    {goal.subTasks && goal.subTasks.length > 0 && (
                                        <div className="pr-4 space-y-1">
                                            {goal.subTasks.map(st => (
                                                <div key={st.id} className="text-[10px] text-gray-400 flex items-center gap-2">
                                                    <IconCheck className="w-3 h-3 text-green-500" /> {st.text}
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                    <button onClick={() => toggleTask(goal.categoryTitle, goal.id)} className="mt-2 text-[10px] text-indigo-600 font-bold opacity-0 group-hover:opacity-100 transition-opacity underline">{t.restore}</button>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>

            {/* --- MINIMAL WHITE POSTER CANVAS (HIDDEN) --- */}
            <div style={{ position: 'fixed', left: '-9999px', top: 0 }}>
                <div ref={posterRef} className="flex flex-col bg-white overflow-hidden p-20 relative" style={{ width: '840px', height: '1188px' }}>
                    {/* Minimal Border Framework */}
                    <div className="absolute inset-10 border-[12px] border-gray-50 pointer-events-none"></div>
                    <div className="absolute inset-14 border border-gray-200 pointer-events-none"></div>

                    {/* Poster Header */}
                    <div className="flex justify-between items-start mb-16 relative z-10">
                        <div className="flex items-center gap-8">
                            <div className="w-32 h-32 rounded-3xl overflow-hidden border-2 border-gray-100 bg-gray-50 shadow-sm">
                                {selectedPerson?.avatar ? <img src={selectedPerson.avatar} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-4xl font-black text-gray-300">{selectedPerson?.fullName.charAt(0)}</div>}
                            </div>
                            <div>
                                <h1 className="text-5xl font-black text-gray-900 mb-2 tracking-tighter">{selectedPerson?.fullName}</h1>
                                <div className="flex gap-2">
                                    {selectedPerson?.roles.map(r => <span key={r} className="bg-gray-100 text-gray-500 px-4 py-1 rounded-lg text-[11px] font-black uppercase tracking-widest">{r}</span>)}
                                </div>
                            </div>
                        </div>
                        <div className="text-right">
                            <div className="text-7xl font-black text-indigo-600 leading-none mb-2">{stats.percent}%</div>
                            <div className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{t.progress}</div>
                        </div>
                    </div>

                    {/* Strategic Banner */}
                    <div className="bg-slate-900 text-white p-10 rounded-2xl mb-12 flex justify-between items-center shadow-xl">
                        <div className="flex items-center gap-4">
                            <IconShield className="w-8 h-8" />
                            <h2 className="text-2xl font-black uppercase tracking-tight">{t.reportTitle}</h2>
                        </div>
                        <div className="font-mono text-sm opacity-60">
                            {activePeriod.toUpperCase()} / {new Date().getFullYear()}
                        </div>
                    </div>

                    {/* Content Section: Active Objectives (Simple 2-Column Grid) */}
                    <div className="flex-grow grid grid-cols-2 gap-x-12 gap-y-12 content-start mb-16">
                        {activeView.map((cat) => (
                            <div key={cat.id} className="space-y-6">
                                <div className="flex items-center gap-3 border-b-2 border-gray-100 pb-3">
                                    <div className={`w-3 h-3 rounded-full ${cat.color}`}></div>
                                    <h3 className="text-xl font-black text-gray-800 uppercase tracking-widest">{cat.title}</h3>
                                </div>
                                <div className="space-y-6">
                                    {cat.tasks.map((task) => (
                                        <div key={task.id} className="flex gap-4">
                                            <div className="w-5 h-5 rounded-full border-2 border-gray-300 mt-1 shrink-0"></div>
                                            <div className="flex-grow min-w-0">
                                                <div className="text-lg font-bold text-gray-800 leading-tight mb-2">{task.text}</div>
                                                {task.subTasks && task.subTasks.length > 0 && (
                                                    <div className="space-y-2 pl-6 border-r-2 border-gray-100 mt-3">
                                                        {task.subTasks.map(st => (
                                                            <div key={st.id} className="text-xs font-bold text-gray-400 flex items-center gap-3">
                                                                <div className={`w-2 h-2 rounded-full ${st.isCompleted ? 'bg-indigo-500' : 'bg-gray-100'}`}></div>
                                                                <span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span>
                                                            </div>
                                                        ))}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                    {cat.tasks.length === 0 && <div className="text-gray-300 text-sm font-bold italic">NO ACTIVE OBJECTIVES</div>}
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* History Section on Poster */}
                    {historyView.length > 0 && (
                        <div className="bg-gray-50 p-10 rounded-3xl border border-gray-100 relative mb-12">
                             <div className="absolute top-0 right-0 p-8 opacity-5"><IconAward className="w-32 h-32" /></div>
                             <h3 className="text-lg font-black text-amber-600 mb-6 uppercase tracking-widest flex items-center gap-3"><IconAward className="w-5 h-5" /> {t.historyTitle}</h3>
                             <div className="grid grid-cols-3 gap-6">
                                {historyView.slice(0, 9).map((goal, i) => (
                                    <div key={i} className="flex flex-col gap-2">
                                        <div className="flex items-center gap-2">
                                            <IconCheck className="w-4 h-4 text-green-500" />
                                            <span className="text-[12px] font-bold text-gray-700 truncate">{goal.text}</span>
                                        </div>
                                        {goal.subTasks && goal.subTasks.length > 0 && (
                                            <div className="text-[9px] text-gray-400 pr-5 truncate">
                                                {goal.subTasks.length} Breakdown Steps
                                            </div>
                                        )}
                                    </div>
                                ))}
                             </div>
                        </div>
                    )}

                    {/* Footer Area */}
                    <div className="border-t border-gray-200 pt-10 flex justify-between items-end">
                        <div className="max-w-[70%]">
                            <p className="text-[10px] font-black text-indigo-600 uppercase tracking-[0.3em] mb-3">LEADERSHIP VISION</p>
                            <p className="text-xl font-bold text-gray-500 italic leading-relaxed">"{t.visionNote}"</p>
                        </div>
                        <div className="flex flex-col items-end">
                            <div className="w-24 h-24 bg-indigo-600 flex items-center justify-center rounded-3xl shadow-xl shadow-indigo-100 mb-4">
                                <IconShield className="w-10 h-10 text-white" />
                            </div>
                            <span className="text-[9px] font-black text-gray-300 uppercase tracking-widest">STRATEGIC PERFORMANCE CERTIFIED</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconCalendar, IconChart, IconShield, IconBrain, IconArrowRight, IconActivity, IconBriefcase, IconUsers, IconPrinter, IconAward, IconTrendingUp, IconClock, IconStar, IconTrophy, IconList } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';
import * as htmlToImage from 'html-to-image';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف تجاری و مالی', color: 'bg-indigo-600', type: 'business' as const },
    { id: 'cat2', title: 'توسعه فردی و مهارت', color: 'bg-emerald-600', type: 'personal' as const },
    { id: 'cat3', title: 'سلامتی و سبک زندگی', color: 'bg-rose-500', type: 'personal' as const },
    { id: 'cat4', title: 'پروژه‌های استراتژیک', color: 'bg-blue-500', type: 'business' as const },
    { id: 'cat5', title: 'سایر اولویت‌ها', color: 'bg-slate-600', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isExporting, setIsExporting] = useState(false);
    const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

    // States for Editing
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editValue, setEditValue] = useState('');

    const posterRef = useRef<HTMLDivElement>(null);
    const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');
    const canEdit = selectedUserId === currentUser.id;

    const selectedPerson = useMemo(() => personnel.find(p => p.id === selectedUserId), [personnel, selectedUserId]);

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    const { activeView, historyView } = useMemo(() => {
        if (!currentUserGoals) return { activeView: [], historyView: [] };
        const history: (GoalTask & { categoryTitle: string, categoryColor: string })[] = [];
        const active = currentUserGoals.categories.map(cat => {
            const activeTasks = cat.tasks.filter(t => !t.isCompleted);
            const completedTasks = cat.tasks.filter(t => t.isCompleted);
            completedTasks.forEach(ct => {
                history.push({ ...ct, categoryTitle: cat.title, categoryColor: cat.color });
            });
            return { ...cat, tasks: activeTasks };
        });
        return { activeView: active, historyView: history };
    }, [currentUserGoals]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => {
            c.tasks.forEach(t => {
                total++;
                if (t.isCompleted) done++;
            });
        });
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const t = {
        fa: {
            title: 'برنامه راهبردی عملکرد',
            daily: 'امروز', weekly: 'هفتگی', monthly: 'ماهانه', yearly: 'سالانه', five_year: '۵ ساله',
            viewMode: 'بازه زمانی:',
            addGoal: 'افزودن هدف جدید',
            progress: 'میزان تحقق اهداف',
            empty: 'لیست اهداف جاری خالی است.',
            print: 'دریافت نسخه چاپی (Poster)',
            exporting: 'در حال آماده‌سازی فایل...',
            reportTitle: 'سند استراتژیک و نقشه راه موفقیت',
            visionNote: 'نظم در اجرا، تفاوت میان سازمان‌های خوب و سازمان‌های عالی است.',
            historyTitle: 'تاریخچه موفقیت (Hall of Fame)',
            historySub: 'دستاوردها و اهداف محقق شده شما',
            restore: 'بازگشت به لیست',
            breakDown: 'گام‌های اجرایی (Breakdown)'
        },
        en: {
            title: 'Strategic Performance Roadmap',
            daily: 'Daily', weekly: 'Weekly', monthly: 'Monthly', yearly: 'Yearly', five_year: '5-Year',
            viewMode: 'Timeframe:',
            addGoal: 'Add New Objective',
            progress: 'Goal Completion Rate',
            empty: 'No active objectives.',
            print: 'Export Strategic Poster',
            exporting: 'Preparing File...',
            reportTitle: 'Strategic Plan & Achievement Roadmap',
            visionNote: 'Discipline in execution is what separates good organizations from great ones.',
            historyTitle: 'Success History (Hall of Fame)',
            historySub: 'Your achieved milestones and goals',
            restore: 'Restore to List',
            breakDown: 'Action Steps (Breakdown)'
        }
    }[lang];

    const handleExportImage = async () => {
        if (!posterRef.current || isExporting) return;
        setIsExporting(true);
        try {
            await new Promise(r => setTimeout(r, 1000));
            const dataUrl = await htmlToImage.toPng(posterRef.current, { quality: 1, pixelRatio: 3, backgroundColor: '#ffffff' });
            const link = document.createElement('a');
            link.download = `Strategic-Roadmap-${activePeriod}.png`;
            link.href = dataUrl;
            link.click();
        } catch (err) {
            alert('خطا در تولید تصویر.');
        } finally {
            setIsExporting(false);
        }
    };

    const handleAddTask = (catId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const taskText = window.prompt(lang === 'fa' ? 'عنوان هدف جدید را وارد کنید:' : 'Enter New Goal Title:');
        if (!taskText) return;
        const updatedCategories = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: taskText, isCompleted: false, subTasks: [] }] } : c);
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    // Generic Update Function
    const syncGoals = (updatedCategories: GoalCategory[]) => {
        if (!currentUserGoals) return;
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const startEditing = (id: string, currentVal: string) => {
        if (!canEdit) return;
        setEditingId(id);
        setEditValue(currentVal);
    };

    const handleEditCategory = (catId: string, newTitle: string) => {
        if (!currentUserGoals) return;
        const updated = currentUserGoals.categories.map(c => c.id === catId ? { ...c, title: newTitle } : c);
        syncGoals(updated);
        setEditingId(null);
    };

    const handleEditTask = (catId: string, taskId: string, newText: string) => {
        if (!currentUserGoals) return;
        const updated = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, text: newText } : t) } : c);
        syncGoals(updated);
        setEditingId(null);
    };

    const handleEditSubTask = (catId: string, taskId: string, subId: string, newText: string) => {
        if (!currentUserGoals) return;
        const updated = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, subTasks: t.subTasks?.map(st => st.id === subId ? { ...st, text: newText } : st) } : t) } : c);
        syncGoals(updated);
        setEditingId(null);
    };

    const toggleTask = (catIdOrTitle: string, taskId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updated = currentUserGoals.categories.map(c => {
            if (c.id === catIdOrTitle || c.title === catIdOrTitle) {
                return { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const newCompleted = !t.isCompleted; return { ...t, isCompleted: newCompleted, subTasks: t.subTasks?.map(st => ({ ...st, isCompleted: newCompleted })) }; } return t; }) };
            }
            return c;
        });
        syncGoals(updated);
    };

    const handleAddSubTask = (catId: string, taskId: string, text: string) => {
        if (!canEdit || !currentUserGoals || !text.trim()) return;
        const updated = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, subTasks: [...(t.subTasks || []), { id: `st-${Date.now()}`, text, isCompleted: false }], isCompleted: false } : t) } : c);
        syncGoals(updated);
    };

    const toggleSubTask = (catId: string, taskId: string, subId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updated = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const updatedSubTasks = t.subTasks?.map(st => st.id === subId ? { ...st, isCompleted: !st.isCompleted } : st); return { ...t, subTasks: updatedSubTasks, isCompleted: updatedSubTasks?.every(st => st.isCompleted) || false }; } return t; }) } : c);
        syncGoals(updated);
    };

    const handleDeleteTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals || !window.confirm('حذف شود؟')) return;
        const updated = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.filter(t => t.id !== taskId) } : c);
        syncGoals(updated);
    };

    if (isLoading) return <div className="p-20 text-center animate-pulse text-indigo-600 font-bold text-lg">در حال بارگذاری اهداف...</div>;

    return (
        <div className="space-y-10 pb-20">
            <div className="space-y-10 animate-fade-in">
                {/* Header Widget */}
                <div className="bg-white p-8 rounded-[2rem] shadow-xl border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-8">
                    <div className="flex items-center gap-6">
                        <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center text-white shadow-lg shadow-indigo-100"><IconTarget className="w-10 h-10" /></div>
                        <div>
                            <h2 className="text-3xl font-black text-gray-900 tracking-tight">{t.title}</h2>
                            <div className="flex items-center gap-2 mt-2">
                                <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{t.viewMode}</span>
                                <span className="px-3 py-1 bg-gray-100 text-gray-600 rounded-full text-[10px] font-black">{t[activePeriod as keyof typeof t.fa]}</span>
                            </div>
                        </div>
                    </div>
                    <div className="flex bg-gray-100 p-1.5 rounded-2xl">
                        {['daily', 'weekly', 'monthly', 'yearly', 'five_year'].map(p => (
                            <button key={p} onClick={() => setActivePeriod(p as GoalPeriod)} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${activePeriod === p ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>{t[p as keyof typeof t.fa]}</button>
                        ))}
                    </div>
                    <div className="flex items-center gap-6">
                        <div className="text-center"><div className="text-3xl font-black text-indigo-600">{stats.percent}%</div><div className="text-[10px] font-bold text-gray-400 uppercase">{t.progress}</div></div>
                        <button onClick={handleExportImage} disabled={isExporting} className="bg-slate-900 text-white px-6 py-3 rounded-2xl text-sm font-bold flex items-center gap-3 hover:bg-black transition-all shadow-xl active:scale-95 disabled:opacity-50">{isExporting ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : <IconPrinter className="w-5 h-5" />}{t.print}</button>
                    </div>
                </div>

                {isMaster && (
                    <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm flex items-center gap-4">
                        <span className="text-xs font-bold text-gray-500">نمایش اهداف:</span>
                        <select className="bg-gray-50 border-none rounded-xl px-4 py-2 text-sm font-bold text-indigo-600 outline-none" value={selectedUserId} onChange={(e) => setSelectedUserId(e.target.value)}>{personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}</select>
                    </div>
                )}

                {/* Categories Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
                    {activeView.map((cat) => (
                        <div key={cat.id} className="bg-white rounded-[2rem] border border-gray-100 shadow-lg flex flex-col min-h-[500px] overflow-hidden group">
                            {editingId === cat.id ? (
                                <input 
                                    className="p-5 text-center text-gray-900 font-black text-xs bg-gray-50 outline-none border-b border-indigo-200"
                                    value={editValue}
                                    autoFocus
                                    onChange={(e) => setEditValue(e.target.value)}
                                    onBlur={() => handleEditCategory(cat.id, editValue)}
                                    onKeyDown={(e) => e.key === 'Enter' && handleEditCategory(cat.id, editValue)}
                                />
                            ) : (
                                <div 
                                    onClick={() => startEditing(cat.id, cat.title)}
                                    className={`p-5 text-center text-white font-black text-xs uppercase tracking-widest cursor-pointer ${cat.color}`}
                                >
                                    {cat.title}
                                </div>
                            )}

                            <div className="flex-grow p-4 space-y-4 overflow-y-auto custom-scrollbar">
                                {cat.tasks.map((task) => (
                                    <div key={task.id} className="bg-gray-50/50 rounded-2xl border border-gray-100 p-4 hover:bg-white transition-all shadow-sm relative group/task">
                                        <div className="flex items-start gap-3">
                                            <button onClick={() => toggleTask(cat.id, task.id)} className="w-6 h-6 rounded-lg border-2 border-indigo-200 bg-white flex items-center justify-center shrink-0 transition-all hover:border-indigo-600">
                                                {task.isCompleted && <IconCheck className="w-4 h-4 text-indigo-600" />}
                                            </button>
                                            <div className="flex-grow min-w-0">
                                                {editingId === task.id ? (
                                                    <input 
                                                        className="w-full text-[13px] font-bold text-gray-800 bg-white border border-indigo-300 rounded px-1 outline-none"
                                                        value={editValue}
                                                        autoFocus
                                                        onChange={e => setEditValue(e.target.value)}
                                                        onBlur={() => handleEditTask(cat.id, task.id, editValue)}
                                                        onKeyDown={e => e.key === 'Enter' && handleEditTask(cat.id, task.id, editValue)}
                                                    />
                                                ) : (
                                                    <span 
                                                        onClick={() => setExpandedTaskId(expandedTaskId === task.id ? null : task.id)} 
                                                        className="text-[13px] font-bold text-gray-800 cursor-pointer block leading-tight truncate"
                                                    >
                                                        {task.text}
                                                    </span>
                                                )}
                                                {task.subTasks && task.subTasks.length > 0 && (
                                                    <span className="text-[9px] font-black text-gray-400 mt-1 block">{(task.subTasks.filter(s=>s.isCompleted).length)} از {task.subTasks.length} گام انجام شده</span>
                                                )}
                                            </div>
                                            {canEdit && (
                                                <div className="flex flex-col gap-2 opacity-0 group-hover/task:opacity-100 transition-opacity">
                                                    <button onClick={() => startEditing(task.id, task.text)} className="text-gray-400 hover:text-indigo-600"><IconEdit className="w-3 h-3"/></button>
                                                    <button onClick={() => handleDeleteTask(cat.id, task.id)} className="text-gray-400 hover:text-red-500"><IconTrash className="w-3 h-3"/></button>
                                                </div>
                                            )}
                                        </div>

                                        {expandedTaskId === task.id && (
                                            <div className="mt-4 space-y-2 border-r-2 border-indigo-100 pr-3 mr-2 animate-slide-in">
                                                {task.subTasks?.map(st => (
                                                    <div key={st.id} className="flex items-center gap-3 text-[11px] font-bold text-gray-500 group/sub">
                                                        <button onClick={() => toggleSubTask(cat.id, task.id, st.id)} className={`w-4 h-4 rounded border flex items-center justify-center ${st.isCompleted ? 'bg-indigo-500 border-indigo-500 text-white' : 'bg-white border-gray-200'}`}>{st.isCompleted && <IconCheck className="w-3 h-3" />}</button>

                                                        {editingId === st.id ? (
                                                            <input 
                                                                className="flex-grow bg-white border border-indigo-300 rounded px-1 outline-none"
                                                                value={editValue}
                                                                autoFocus
                                                                onChange={e => setEditValue(e.target.value)}
                                                                onBlur={() => handleEditSubTask(cat.id, task.id, st.id, editValue)}
                                                                onKeyDown={e => e.key === 'Enter' && handleEditSubTask(cat.id, task.id, st.id, editValue)}
                                                            />
                                                        ) : (
                                                            <span 
                                                                onClick={() => startEditing(st.id, st.text)}
                                                                className={`flex-grow cursor-text ${st.isCompleted ? 'line-through opacity-50' : ''}`}
                                                            >
                                                                {st.text}
                                                            </span>
                                                        )}
                                                        <button onClick={() => { if(window.confirm('حذف شود؟')) syncGoals(currentUserGoals!.categories.map(c => c.id === cat.id ? { ...c, tasks: c.tasks.map(t => t.id === task.id ? { ...t, subTasks: t.subTasks?.filter(si => si.id !== st.id) } : t) } : c)) }} className="opacity-0 group-hover/sub:opacity-100 transition-opacity text-red-300 hover:text-red-500"><IconTrash className="w-2.5 h-2.5"/></button>
                                                    </div>
                                                ))}
                                                {canEdit && (
                                                    <input className="w-full text-[10px] p-2 bg-white rounded-lg outline-none border border-gray-100 focus:border-indigo-200" placeholder="Break Down (اینتر)..." onKeyDown={e => { if (e.key === 'Enter' && (e.target as HTMLInputElement).value.trim()) { handleAddSubTask(cat.id, task.id, (e.target as HTMLInputElement).value); (e.target as HTMLInputElement).value = ''; } }} />
                                                )}
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                            {canEdit && (
                                <div className="p-4 border-t border-gray-50"><button onClick={() => handleAddTask(cat.id)} className="w-full py-2.5 bg-gray-50 text-gray-400 text-[11px] font-black rounded-xl hover:bg-indigo-50 hover:text-indigo-600 transition-all flex items-center justify-center gap-2"><IconPlus className="w-4 h-4" /> {t.addGoal}</button></div>
                            )}
                        </div>
                    ))}
                </div>

                {/* Success History Section */}
                {historyView.length > 0 && (
                    <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-xl animate-fade-in">
                        <div className="flex items-center gap-4 mb-8">
                            <div className="p-3 bg-amber-100 text-amber-600 rounded-2xl"><IconTrophy className="w-6 h-6" /></div>
                            <div><h3 className="text-2xl font-black text-gray-900">{t.historyTitle}</h3><p className="text-sm text-gray-400 font-bold">{t.historySub}</p></div>
                        </div>
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                            {historyView.map((goal, idx) => (
                                <div key={idx} className="bg-gray-50 p-4 rounded-2xl border border-gray-200 flex flex-col gap-3 relative group overflow-hidden">
                                    <div className="flex items-center gap-3">
                                        <IconStar className="w-5 h-5 text-amber-500 fill-current" />
                                        <div className="min-w-0">
                                            <h4 className="text-[13px] font-black text-gray-800 line-through opacity-40 truncate">{goal.text}</h4>
                                            <p className="text-[9px] font-bold text-gray-400 uppercase mt-0.5">{goal.categoryTitle}</p>
                                        </div>
                                    </div>
                                    {goal.subTasks && goal.subTasks.length > 0 && (
                                        <div className="pr-4 space-y-1">{goal.subTasks.map(st => (<div key={st.id} className="text-[10px] text-gray-400 flex items-center gap-2"><IconCheck className="w-3 h-3 text-green-500" /> {st.text}</div>))}</div>
                                    )}
                                    <button onClick={() => toggleTask(goal.categoryTitle, goal.id)} className="mt-2 text-[10px] text-indigo-600 font-bold opacity-0 group-hover:opacity-100 transition-opacity underline">{t.restore}</button>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>

            {/* Poster Canvas (Hidden) */}
            <div style={{ position: 'fixed', left: '-9999px', top: 0 }}>
                <div ref={posterRef} className="flex flex-col bg-white overflow-hidden p-20 relative" style={{ width: '840px', height: '1188px' }}>
                    <div className="absolute inset-10 border-[12px] border-gray-50 pointer-events-none"></div>
                    <div className="absolute inset-14 border border-gray-200 pointer-events-none"></div>
                    <div className="flex justify-between items-start mb-16 relative z-10">
                        <div className="flex items-center gap-8">
                            <div className="w-32 h-32 rounded-3xl overflow-hidden border-2 border-gray-100 bg-gray-50 shadow-sm">{selectedPerson?.avatar ? <img src={selectedPerson.avatar} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-4xl font-black text-gray-300">{selectedPerson?.fullName.charAt(0)}</div>}</div>
                            <div>
                                <h1 className="text-5xl font-black text-gray-900 mb-2 tracking-tighter">{selectedPerson?.fullName}</h1>
                                <div className="flex gap-2">{selectedPerson?.roles.map(r => <span key={r} className="bg-gray-100 text-gray-500 px-4 py-1 rounded-lg text-[11px] font-black uppercase tracking-widest">{r}</span>)}</div>
                            </div>
                        </div>
                        <div className="text-right"><div className="text-7xl font-black text-indigo-600 leading-none mb-2">{stats.percent}%</div><div className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{t.progress}</div></div>
                    </div>
                    <div className="bg-slate-900 text-white p-10 rounded-2xl mb-12 flex justify-between items-center shadow-xl">
                        <div className="flex items-center gap-4"><IconShield className="w-8 h-8" /><h2 className="text-2xl font-black uppercase tracking-tight">{t.reportTitle}</h2></div>
                        <div className="font-mono text-sm opacity-60">{activePeriod.toUpperCase()} / {new Date().getFullYear()}</div>
                    </div>
                    <div className="flex-grow grid grid-cols-2 gap-x-12 gap-y-12 content-start mb-16">
                        {activeView.map((cat) => (
                            <div key={cat.id} className="space-y-6">
                                <div className="flex items-center gap-3 border-b-2 border-gray-100 pb-3"><div className={`w-3 h-3 rounded-full ${cat.color}`}></div><h3 className="text-xl font-black text-gray-800 uppercase tracking-widest">{cat.title}</h3></div>
                                <div className="space-y-6">
                                    {cat.tasks.map((task) => (
                                        <div key={task.id} className="flex gap-4">
                                            <div className="w-5 h-5 rounded-full border-2 border-gray-300 mt-1 shrink-0"></div>
                                            <div className="flex-grow min-w-0">
                                                <div className="text-lg font-bold text-gray-800 leading-tight mb-2">{task.text}</div>
                                                {task.subTasks && task.subTasks.length > 0 && (
                                                    <div className="space-y-2 pl-6 border-r-2 border-gray-100 mt-3">{task.subTasks.map(st => (<div key={st.id} className="text-xs font-bold text-gray-400 flex items-center gap-3"><div className={`w-2 h-2 rounded-full ${st.isCompleted ? 'bg-indigo-500' : 'bg-gray-100'}`}></div><span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span></div>))}</div>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                    {cat.tasks.length === 0 && <div className="text-gray-300 text-sm font-bold italic">NO ACTIVE OBJECTIVES</div>}
                                </div>
                            </div>
                        ))}
                    </div>
                    <div className="border-t border-gray-200 pt-10 flex justify-between items-end">
                        <div className="max-w-[70%]"><p className="text-[10px] font-black text-indigo-600 uppercase tracking-[0.3em] mb-3">LEADERSHIP VISION</p><p className="text-xl font-bold text-gray-500 italic leading-relaxed">"{t.visionNote}"</p></div>
                        <div className="flex flex-col items-end"><div className="w-24 h-24 bg-indigo-600 flex items-center justify-center rounded-3xl shadow-xl shadow-indigo-100 mb-4"><IconShield className="w-10 h-10 text-white" /></div><span className="text-[9px] font-black text-gray-300 uppercase tracking-widest">STRATEGIC PERFORMANCE CERTIFIED</span></div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconCalendar, IconChart, IconShield, IconBrain, IconArrowRight, IconActivity, IconBriefcase, IconUsers, IconPrinter, IconAward, IconTrendingUp, IconClock, IconStar, IconTrophy, IconList } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';
import * as htmlToImage from 'html-to-image';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف تجاری و مالی', color: 'bg-indigo-600', type: 'business' as const },
    { id: 'cat2', title: 'توسعه فردی و مهارت', color: 'bg-emerald-600', type: 'personal' as const },
    { id: 'cat3', title: 'سلامتی و سبک زندگی', color: 'bg-rose-500', type: 'personal' as const },
    { id: 'cat4', title: 'پروژه‌های استراتژیک', color: 'bg-blue-500', type: 'business' as const },
    { id: 'cat5', title: 'سایر اولویت‌ها', color: 'bg-slate-600', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isExporting, setIsExporting] = useState(false);
    const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

    // UI States
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [modalMode, setModalMode] = useState<'add' | 'edit'>('add');
    const [targetCatId, setTargetCatId] = useState<string | null>(null);
    const [targetTaskId, setTargetTaskId] = useState<string | null>(null);
    const [formText, setFormText] = useState('');

    const posterRef = useRef<HTMLDivElement>(null);
    const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');
    const canEdit = selectedUserId === currentUser.id;

    const selectedPerson = useMemo(() => personnel.find(p => p.id === selectedUserId), [personnel, selectedUserId]);

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    const { activeView, historyView } = useMemo(() => {
        if (!currentUserGoals) return { activeView: [], historyView: [] };
        const history: (GoalTask & { categoryTitle: string, categoryColor: string })[] = [];
        const active = currentUserGoals.categories.map(cat => {
            const activeTasks = cat.tasks.filter(t => !t.isCompleted);
            const completedTasks = cat.tasks.filter(t => t.isCompleted);
            completedTasks.forEach(ct => {
                history.push({ ...ct, categoryTitle: cat.title, categoryColor: cat.color });
            });
            return { ...cat, tasks: activeTasks };
        });
        return { activeView: active, historyView: history };
    }, [currentUserGoals]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => {
            c.tasks.forEach(t => {
                total++;
                if (t.isCompleted) done++;
            });
        });
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const t = {
        fa: {
            title: 'برنامه راهبردی عملکرد',
            daily: 'امروز', weekly: 'هفتگی', monthly: 'ماهانه', yearly: 'سالانه', five_year: '۵ ساله',
            viewMode: 'بازه زمانی:',
            addGoal: 'افزودن هدف جدید',
            progress: 'میزان تحقق اهداف',
            empty: 'لیست اهداف جاری خالی است.',
            print: 'دریافت نسخه چاپی (Poster)',
            exporting: 'در حال آماده‌سازی فایل...',
            reportTitle: 'سند استراتژیک و نقشه راه موفقیت',
            visionNote: 'نظم در اجرا، تفاوت میان سازمان‌های خوب و سازمان‌های عالی است.',
            historyTitle: 'تاریخچه موفقیت (Hall of Fame)',
            historySub: 'دستاوردها و اهداف محقق شده شما',
            restore: 'بازگشت به لیست',
            breakDown: 'گام‌های اجرایی (Breakdown)',
            modalTitle: 'تعریف هدف جدید',
            modalEditTitle: 'ویرایش هدف',
            modalPlaceholder: 'هدف خود را با جزئیات بنویسید...',
            save: 'ذخیره هدف',
            cancel: 'بستن'
        },
        en: {
            title: 'Strategic Performance Roadmap',
            daily: 'Daily', weekly: 'Weekly', monthly: 'Monthly', yearly: 'Yearly', five_year: '5-Year',
            viewMode: 'Timeframe:',
            addGoal: 'Add New Objective',
            progress: 'Goal Completion Rate',
            empty: 'No active objectives.',
            print: 'Export Strategic Poster',
            exporting: 'Preparing File...',
            reportTitle: 'Strategic Plan & Achievement Roadmap',
            visionNote: 'Discipline in execution is what separates good organizations from great ones.',
            historyTitle: 'Success History (Hall of Fame)',
            historySub: 'Your achieved milestones and goals',
            restore: 'Restore to List',
            breakDown: 'Action Steps (Breakdown)',
            modalTitle: 'New Objective',
            modalEditTitle: 'Edit Objective',
            modalPlaceholder: 'Write your goal details here...',
            save: 'Save Objective',
            cancel: 'Cancel'
        }
    }[lang];

    const handleExportImage = async () => {
        if (!posterRef.current || isExporting) return;
        setIsExporting(true);
        try {
            await new Promise(r => setTimeout(r, 1000));
            const dataUrl = await htmlToImage.toPng(posterRef.current, { quality: 1, pixelRatio: 3, backgroundColor: '#ffffff' });
            const link = document.createElement('a');
            link.download = `Strategic-Roadmap-${activePeriod}.png`;
            link.href = dataUrl;
            link.click();
        } catch (err) {
            alert('خطا در تولید تصویر.');
        } finally {
            setIsExporting(false);
        }
    };

    const openAddModal = (catId: string) => {
        setModalMode('add');
        setTargetCatId(catId);
        setFormText('');
        setIsModalOpen(true);
    };

    const openEditModal = (catId: string, task: GoalTask) => {
        setModalMode('edit');
        setTargetCatId(catId);
        setTargetTaskId(task.id);
        setFormText(task.text);
        setIsModalOpen(true);
    };

    const handleFormSubmit = () => {
        if (!formText.trim() || !currentUserGoals || !targetCatId) return;

        let updatedCategories;
        if (modalMode === 'add') {
            updatedCategories = currentUserGoals.categories.map(c => 
                c.id === targetCatId 
                ? { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: formText, isCompleted: false, subTasks: [] }] } 
                : c
            );
        } else {
            updatedCategories = currentUserGoals.categories.map(c => 
                c.id === targetCatId 
                ? { ...c, tasks: c.tasks.map(t => t.id === targetTaskId ? { ...t, text: formText } : t) } 
                : c
            );
        }

        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
        setIsModalOpen(false);
    };

    const syncGoals = (updatedCategories: GoalCategory[]) => {
        if (!currentUserGoals) return;
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleTask = (catIdOrTitle: string, taskId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updated = currentUserGoals.categories.map(c => {
            if (c.id === catIdOrTitle || c.title === catIdOrTitle) {
                return { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const newCompleted = !t.isCompleted; return { ...t, isCompleted: newCompleted, subTasks: t.subTasks?.map(st => ({ ...st, isCompleted: newCompleted })) }; } return t; }) };
            }
            return c;
        });
        syncGoals(updated);
    };

    const handleAddSubTask = (catId: string, taskId: string, text: string) => {
        if (!canEdit || !currentUserGoals || !text.trim()) return;
        const updated = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, subTasks: [...(t.subTasks || []), { id: `st-${Date.now()}`, text, isCompleted: false }], isCompleted: false } : t) } : c);
        syncGoals(updated);
    };

    const toggleSubTask = (catId: string, taskId: string, subId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updated = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const updatedSubTasks = t.subTasks?.map(st => st.id === subId ? { ...st, isCompleted: !st.isCompleted } : st); return { ...t, subTasks: updatedSubTasks, isCompleted: updatedSubTasks?.every(st => st.isCompleted) || false }; } return t; }) } : c);
        syncGoals(updated);
    };

    const handleDeleteTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals || !window.confirm('حذف شود؟')) return;
        const updated = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.filter(t => t.id !== taskId) } : c);
        syncGoals(updated);
    };

    if (isLoading) return <div className="p-20 text-center animate-pulse text-indigo-600 font-bold text-lg">در حال بارگذاری اهداف...</div>;

    return (
        <div className="space-y-10 pb-20">
            {/* Modal for Adding/Editing Goals */}
            {isModalOpen && (
                <div className="fixed inset-0 z-[150] flex items-center justify-center bg-gray-900/60 backdrop-blur-sm p-4 animate-fade-in" onClick={() => setIsModalOpen(false)}>
                    <div className="bg-white rounded-[2.5rem] w-full max-w-xl shadow-2xl flex flex-col overflow-hidden" onClick={e => e.stopPropagation()}>
                        <div className="p-8 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                            <h3 className="text-2xl font-black text-gray-800 flex items-center gap-3">
                                <div className="p-2 bg-indigo-600 text-white rounded-2xl"><IconTarget className="w-5 h-5" /></div>
                                {modalMode === 'add' ? t.modalTitle : t.modalEditTitle}
                            </h3>
                            <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-red-500 transition-colors">✕</button>
                        </div>
                        <div className="p-8">
                            <label className="block text-xs font-black text-gray-400 uppercase tracking-[0.2em] mb-4">شرح کامل هدف یا ماموریت</label>
                            <textarea 
                                className="w-full h-48 p-6 bg-gray-50 border-2 border-transparent focus:border-indigo-200 focus:bg-white rounded-3xl text-lg font-bold text-gray-800 outline-none transition-all resize-none shadow-inner"
                                placeholder={t.modalPlaceholder}
                                value={formText}
                                onChange={e => setFormText(e.target.value)}
                                autoFocus
                            />
                        </div>
                        <div className="p-8 border-t border-gray-50 bg-white flex gap-3">
                            <button onClick={() => setIsModalOpen(false)} className="flex-1 py-4 text-gray-500 font-bold hover:bg-gray-100 rounded-2xl transition-all">{t.cancel}</button>
                            <button onClick={handleFormSubmit} disabled={!formText.trim()} className="flex-[2] py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95 disabled:opacity-50">{t.save}</button>
                        </div>
                    </div>
                </div>
            )}

            <div className="space-y-10 animate-fade-in">
                {/* Header Widget */}
                <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-8">
                    <div className="flex items-center gap-6">
                        <div className="w-20 h-20 bg-indigo-600 rounded-[2rem] flex items-center justify-center text-white shadow-lg shadow-indigo-100"><IconTarget className="w-10 h-10" /></div>
                        <div>
                            <h2 className="text-3xl font-black text-gray-900 tracking-tight">{t.title}</h2>
                            <div className="flex items-center gap-2 mt-2">
                                <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{t.viewMode}</span>
                                <span className="px-3 py-1 bg-gray-100 text-gray-600 rounded-full text-[10px] font-black">{t[activePeriod as keyof typeof t.fa]}</span>
                            </div>
                        </div>
                    </div>
                    <div className="flex bg-gray-100 p-1.5 rounded-2xl">
                        {['daily', 'weekly', 'monthly', 'yearly', 'five_year'].map(p => (
                            <button key={p} onClick={() => setActivePeriod(p as GoalPeriod)} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${activePeriod === p ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>{t[p as keyof typeof t.fa]}</button>
                        ))}
                    </div>
                    <div className="flex items-center gap-6">
                        <div className="text-center"><div className="text-3xl font-black text-indigo-600">{stats.percent}%</div><div className="text-[10px] font-bold text-gray-400 uppercase">{t.progress}</div></div>
                        <button onClick={handleExportImage} disabled={isExporting} className="bg-slate-900 text-white px-6 py-3 rounded-2xl text-sm font-bold flex items-center gap-3 hover:bg-black transition-all shadow-xl active:scale-95 disabled:opacity-50">{isExporting ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : <IconPrinter className="w-5 h-5" />}{t.print}</button>
                    </div>
                </div>

                {isMaster && (
                    <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm flex items-center gap-4">
                        <span className="text-xs font-bold text-gray-500">نمایش اهداف پرسنل:</span>
                        <select className="bg-gray-50 border-none rounded-xl px-4 py-2 text-sm font-bold text-indigo-600 outline-none" value={selectedUserId} onChange={(e) => setSelectedUserId(e.target.value)}>{personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}</select>
                    </div>
                )}

                {/* Categories Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
                    {activeView.map((cat) => (
                        <div key={cat.id} className="bg-white rounded-[2.5rem] border border-gray-100 shadow-lg flex flex-col min-h-[550px] overflow-hidden group">
                            <div className={`p-6 text-center text-white font-black text-xs uppercase tracking-[0.2em] ${cat.color} shadow-lg`}>
                                {cat.title}
                            </div>

                            <div className="flex-grow p-5 space-y-5 overflow-y-auto custom-scrollbar">
                                {cat.tasks.map((task) => (
                                    <div key={task.id} className="bg-gray-50/50 rounded-3xl border border-gray-100 p-5 hover:bg-white transition-all shadow-sm relative group/task">
                                        <div className="flex items-start gap-4">
                                            <button onClick={() => toggleTask(cat.id, task.id)} className="w-7 h-7 rounded-xl border-2 border-indigo-200 bg-white flex items-center justify-center shrink-0 transition-all hover:border-indigo-600">
                                                {task.isCompleted && <IconCheck className="w-5 h-5 text-indigo-600" />}
                                            </button>
                                            <div className="flex-grow min-w-0">
                                                <span 
                                                    onClick={() => setExpandedTaskId(expandedTaskId === task.id ? null : task.id)} 
                                                    className="text-[14px] font-black text-gray-800 cursor-pointer block leading-snug whitespace-pre-wrap"
                                                >
                                                    {task.text}
                                                </span>
                                                {task.subTasks && task.subTasks.length > 0 && (
                                                    <span className="text-[10px] font-black text-gray-400 mt-2 block flex items-center gap-1.5"><IconList className="w-3 h-3" /> {(task.subTasks.filter(s=>s.isCompleted).length)} / {task.subTasks.length} {t.breakDown}</span>
                                                )}
                                            </div>
                                            {canEdit && (
                                                <div className="flex flex-col gap-2 opacity-0 group-hover/task:opacity-100 transition-opacity">
                                                    <button onClick={() => openEditModal(cat.id, task)} className="text-gray-400 hover:text-indigo-600"><IconEdit className="w-4 h-4"/></button>
                                                    <button onClick={() => handleDeleteTask(cat.id, task.id)} className="text-gray-400 hover:text-red-500"><IconTrash className="w-4 h-4"/></button>
                                                </div>
                                            )}
                                        </div>

                                        {expandedTaskId === task.id && (
                                            <div className="mt-5 space-y-3 border-r-2 border-indigo-100 pr-4 mr-2 animate-slide-in">
                                                {task.subTasks?.map(st => (
                                                    <div key={st.id} className="flex items-center gap-3 text-[12px] font-bold text-gray-500 group/sub">
                                                        <button onClick={() => toggleSubTask(cat.id, task.id, st.id)} className={`w-4.5 h-4.5 rounded-lg border flex items-center justify-center transition-colors ${st.isCompleted ? 'bg-indigo-500 border-indigo-500 text-white' : 'bg-white border-gray-200'}`}>{st.isCompleted && <IconCheck className="w-3 h-3" />}</button>
                                                        <span className={`flex-grow ${st.isCompleted ? 'line-through opacity-50' : ''}`}>{st.text}</span>
                                                        <button onClick={() => { if(window.confirm('حذف؟')) syncGoals(currentUserGoals!.categories.map(c => c.id === cat.id ? { ...c, tasks: c.tasks.map(t => t.id === task.id ? { ...t, subTasks: t.subTasks?.filter(si => si.id !== st.id) } : t) } : c)) }} className="opacity-0 group-hover/sub:opacity-100 transition-opacity text-red-300 hover:text-red-500"><IconTrash className="w-3.5 h-3.5"/></button>
                                                    </div>
                                                ))}
                                                {canEdit && (
                                                    <div className="relative">
                                                        <input className="w-full text-[11px] py-2 px-3 bg-white rounded-xl outline-none border border-gray-100 focus:border-indigo-300 shadow-inner" placeholder="Break Down (اینتر)..." onKeyDown={e => { if (e.key === 'Enter' && (e.target as HTMLInputElement).value.trim()) { handleAddSubTask(cat.id, task.id, (e.target as HTMLInputElement).value); (e.target as HTMLInputElement).value = ''; } }} />
                                                    </div>
                                                )}
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                            {canEdit && (
                                <div className="p-5 border-t border-gray-50 bg-gray-50/20"><button onClick={() => openAddModal(cat.id)} className="w-full py-4 bg-white border-2 border-dashed border-gray-200 rounded-[1.5rem] text-gray-400 text-[11px] font-black hover:text-indigo-600 hover:border-indigo-400 transition-all flex items-center justify-center gap-2 shadow-sm"><IconPlus className="w-4 h-4" /> {t.addGoal}</button></div>
                            )}
                        </div>
                    ))}
                </div>

                {/* Success History Section */}
                {historyView.length > 0 && (
                    <div className="bg-white p-10 rounded-[3.5rem] border border-gray-100 shadow-xl animate-fade-in">
                        <div className="flex items-center gap-4 mb-10">
                            <div className="p-4 bg-amber-100 text-amber-600 rounded-[1.5rem]"><IconTrophy className="w-8 h-8" /></div>
                            <div><h3 className="text-3xl font-black text-gray-900">{t.historyTitle}</h3><p className="text-base text-gray-400 font-bold">{t.historySub}</p></div>
                        </div>
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                            {historyView.map((goal, idx) => (
                                <div key={idx} className="bg-gray-50 p-5 rounded-[2rem] border border-gray-200 flex flex-col gap-3 relative group overflow-hidden hover:shadow-lg transition-all">
                                    <div className="flex items-center gap-3">
                                        <IconStar className="w-6 h-6 text-amber-500 fill-current" />
                                        <div className="min-w-0">
                                            <h4 className="text-[14px] font-black text-gray-800 line-through opacity-40 truncate">{goal.text}</h4>
                                            <p className="text-[10px] font-bold text-gray-400 uppercase mt-1 tracking-widest">{goal.categoryTitle}</p>
                                        </div>
                                    </div>
                                    {goal.subTasks && goal.subTasks.length > 0 && (
                                        <div className="pr-4 space-y-1.5">{goal.subTasks.map(st => (<div key={st.id} className="text-[11px] text-gray-400 flex items-center gap-2"><IconCheck className="w-3.5 h-3.5 text-green-500" /> {st.text}</div>))}</div>
                                    )}
                                    <button onClick={() => toggleTask(goal.categoryTitle, goal.id)} className="mt-3 text-[11px] text-indigo-600 font-black opacity-0 group-hover:opacity-100 transition-opacity underline decoration-2">{t.restore}</button>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>

            {/* Poster Canvas (Hidden) */}
            <div style={{ position: 'fixed', left: '-9999px', top: 0 }}>
                <div ref={posterRef} className="flex flex-col bg-white overflow-hidden p-20 relative" style={{ width: '840px', height: '1188px' }}>
                    <div className="absolute inset-10 border-[12px] border-gray-50 pointer-events-none"></div>
                    <div className="absolute inset-14 border border-gray-200 pointer-events-none"></div>
                    <div className="flex justify-between items-start mb-16 relative z-10">
                        <div className="flex items-center gap-8">
                            <div className="w-32 h-32 rounded-[2rem] overflow-hidden border-2 border-gray-100 bg-gray-50 shadow-sm">{selectedPerson?.avatar ? <img src={selectedPerson.avatar} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-5xl font-black text-gray-200">{selectedPerson?.fullName.charAt(0)}</div>}</div>
                            <div>
                                <h1 className="text-6xl font-black text-gray-900 mb-2 tracking-tighter">{selectedPerson?.fullName}</h1>
                                <div className="flex gap-2">{selectedPerson?.roles.map(r => <span key={r} className="bg-gray-100 text-gray-500 px-5 py-1.5 rounded-xl text-xs font-black uppercase tracking-widest">{r}</span>)}</div>
                            </div>
                        </div>
                        <div className="text-right"><div className="text-8xl font-black text-indigo-600 leading-none mb-2">{stats.percent}%</div><div className="text-xs font-bold text-gray-400 uppercase tracking-[0.3em]">{t.progress}</div></div>
                    </div>
                    <div className="bg-slate-900 text-white p-12 rounded-[2rem] mb-12 flex justify-between items-center shadow-2xl">
                        <div className="flex items-center gap-5"><IconShield className="w-10 h-10" /><h2 className="text-3xl font-black uppercase tracking-tight">{t.reportTitle}</h2></div>
                        <div className="font-mono text-lg opacity-60 font-bold">{activePeriod.toUpperCase()} / {new Date().getFullYear()}</div>
                    </div>
                    <div className="flex-grow grid grid-cols-2 gap-x-16 gap-y-16 content-start mb-16">
                        {activeView.map((cat) => (
                            <div key={cat.id} className="space-y-8">
                                <div className="flex items-center gap-4 border-b-2 border-gray-100 pb-4"><div className={`w-4 h-4 rounded-full ${cat.color} shadow-sm`}></div><h3 className="text-2xl font-black text-gray-800 uppercase tracking-widest">{cat.title}</h3></div>
                                <div className="space-y-10">
                                    {cat.tasks.map((task) => (
                                        <div key={task.id} className="flex gap-6">
                                            <div className="w-6 h-6 rounded-full border-4 border-gray-200 mt-1.5 shrink-0"></div>
                                            <div className="flex-grow min-w-0">
                                                <div className="text-2xl font-black text-gray-800 leading-snug mb-3">{task.text}</div>
                                                {task.subTasks && task.subTasks.length > 0 && (
                                                    <div className="space-y-3 pl-8 border-r-4 border-gray-50 mt-5 py-1">
                                                        {task.subTasks.map(st => (<div key={st.id} className="text-base font-bold text-gray-400 flex items-center gap-4"><div className={`w-3 h-3 rounded-md ${st.isCompleted ? 'bg-indigo-500' : 'bg-gray-100'}`}></div><span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span></div>))}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                    {cat.tasks.length === 0 && <div className="text-gray-300 text-base font-black italic tracking-widest opacity-40">NO ACTIVE OBJECTIVES</div>}
                                </div>
                            </div>
                        ))}
                    </div>
                    <div className="border-t border-gray-200 pt-12 flex justify-between items-end">
                        <div className="max-w-[70%]"><p className="text-[12px] font-black text-indigo-600 uppercase tracking-[0.5em] mb-4">CORE LEADERSHIP VISION</p><p className="text-3xl font-black text-gray-500 italic leading-relaxed">"{t.visionNote}"</p></div>
                        <div className="flex flex-col items-end"><div className="w-32 h-32 bg-indigo-600 flex items-center justify-center rounded-[2.5rem] shadow-2xl shadow-indigo-100 mb-6 border-4 border-white"><IconShield className="w-14 h-14 text-white" /></div><span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em]">STRATEGIC PERFORMANCE CERTIFIED</span></div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconShield, IconPrinter, IconTrophy, IconList, IconStar, IconAward } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';
import * as htmlToImage from 'html-to-image';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف تجاری و مالی', color: 'bg-indigo-600', type: 'business' as const },
    { id: 'cat2', title: 'توسعه فردی و مهارت', color: 'bg-emerald-600', type: 'personal' as const },
    { id: 'cat3', title: 'سلامتی و سبک زندگی', color: 'bg-rose-500', type: 'personal' as const },
    { id: 'cat4', title: 'پروژه‌های استراتژیک', color: 'bg-blue-500', type: 'business' as const },
    { id: 'cat5', title: 'سایر اولویت‌ها', color: 'bg-slate-600', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isExporting, setIsExporting] = useState(false);

    // Advanced Modal States
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [targetCatId, setTargetCatId] = useState<string | null>(null);
    const [editingTaskId, setEditingTaskId] = useState<string | null>(null);
    const [mainGoalText, setMainGoalText] = useState('');
    const [subTasks, setSubTasks] = useState<{id: string, text: string, isCompleted: boolean}[]>([]);
    const [newSubInput, setNewSubInput] = useState('');

    const posterRef = useRef<HTMLDivElement>(null);
    const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');
    const canEdit = selectedUserId === currentUser.id;

    const selectedPerson = useMemo(() => personnel.find(p => p.id === selectedUserId), [personnel, selectedUserId]);

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    const t = {
        fa: {
            title: 'برنامه راهبردی عملکرد',
            daily: 'امروز', weekly: 'هفتگی', monthly: 'ماهانه', yearly: 'سالانه', five_year: '۵ ساله',
            viewMode: 'بازه زمانی:',
            addGoal: 'افزودن هدف و برنامه',
            progress: 'میزان تحقق اهداف',
            empty: 'لیست اهداف جاری خالی است.',
            print: 'دریافت نسخه چاپی (Poster)',
            modalTitle: 'تعریف و خرد کردن هدف (Breakdown)',
            modalEditTitle: 'ویرایش برنامه عملیاتی',
            mainPlaceholder: 'هدف اصلی یا ماموریت بزرگ خود را بنویسید...',
            subLabel: 'گام‌های اجرایی برای رسیدن به این هدف:',
            addSub: 'افزودن گام',
            save: 'ثبت نهایی برنامه',
            cancel: 'بستن',
            historyTitle: 'تاریخچه موفقیت (Hall of Fame)',
            restore: 'بازگشت به لیست',
            breakDown: 'گام اجرایی'
        },
        en: {
            title: 'Strategic Performance Roadmap',
            daily: 'Daily', weekly: 'Weekly', monthly: 'Monthly', yearly: 'Yearly', five_year: '5-Year',
            viewMode: 'Timeframe:',
            addGoal: 'Add Goal & Plan',
            progress: 'Completion Rate',
            empty: 'No active objectives.',
            print: 'Export Poster',
            modalTitle: 'Define & Breakdown Objective',
            modalEditTitle: 'Edit Action Plan',
            mainPlaceholder: 'Write your main mission or big goal...',
            subLabel: 'Action steps to achieve this goal:',
            addSub: 'Add Step',
            save: 'Save Action Plan',
            cancel: 'Cancel',
            historyTitle: 'Success History',
            restore: 'Restore',
            breakDown: 'Steps'
        }
    }[lang];

    const openAddModal = (catId: string) => {
        setTargetCatId(catId);
        setEditingTaskId(null);
        setMainGoalText('');
        setSubTasks([]);
        setIsModalOpen(true);
    };

    const openEditModal = (catId: string, task: GoalTask) => {
        setTargetCatId(catId);
        setEditingTaskId(task.id);
        setMainGoalText(task.text);
        setSubTasks(task.subTasks || []);
        setIsModalOpen(true);
    };

    const handleAddSubInModal = () => {
        if (!newSubInput.trim()) return;
        setSubTasks([...subTasks, { id: `st-${Date.now()}`, text: newSubInput.trim(), isCompleted: false }]);
        setNewSubInput('');
    };

    const handleSaveFullGoal = () => {
        if (!mainGoalText.trim() || !currentUserGoals || !targetCatId) return;

        let updatedCategories;
        if (editingTaskId) {
            // Edit existing
            updatedCategories = currentUserGoals.categories.map(c => 
                c.id === targetCatId 
                ? { ...c, tasks: c.tasks.map(t => t.id === editingTaskId ? { ...t, text: mainGoalText, subTasks: subTasks } : t) } 
                : c
            );
        } else {
            // Add new
            updatedCategories = currentUserGoals.categories.map(c => 
                c.id === targetCatId 
                ? { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: mainGoalText, isCompleted: false, subTasks: subTasks }] } 
                : c
            );
        }

        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
        setIsModalOpen(false);
    };

    const toggleTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updated = currentUserGoals.categories.map(c => {
            if (c.id === catId) {
                return { ...c, tasks: c.tasks.map(t => { if (t.id === taskId) { const ns = !t.isCompleted; return { ...t, isCompleted: ns, subTasks: t.subTasks?.map(st => ({ ...st, isCompleted: ns })) }; } return t; }) };
            }
            return c;
        });
        syncGoals(updated);
    };

    const syncGoals = (updatedCategories: GoalCategory[]) => {
        if (!currentUserGoals) return;
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleExportImage = async () => {
        if (!posterRef.current || isExporting) return;
        setIsExporting(true);
        try {
            await new Promise(r => setTimeout(r, 1000));
            const dataUrl = await htmlToImage.toPng(posterRef.current, { quality: 1, pixelRatio: 3, backgroundColor: '#ffffff' });
            const link = document.createElement('a');
            link.download = `Goal-Roadmap-${activePeriod}.png`;
            link.href = dataUrl;
            link.click();
        } catch (err) {
            alert('Error exporting image.');
        } finally {
            setIsExporting(false);
        }
    };

    const { activeView, historyView } = useMemo(() => {
        if (!currentUserGoals) return { activeView: [], historyView: [] };
        const history: (GoalTask & { categoryTitle: string, categoryColor: string })[] = [];
        const active = currentUserGoals.categories.map(cat => {
            const activeTasks = cat.tasks.filter(t => !t.isCompleted);
            const completedTasks = cat.tasks.filter(t => t.isCompleted);
            completedTasks.forEach(ct => history.push({ ...ct, categoryTitle: cat.title, categoryColor: cat.color }));
            return { ...cat, tasks: activeTasks };
        });
        return { activeView: active, historyView: history };
    }, [currentUserGoals]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => c.tasks.forEach(t => { total++; if (t.isCompleted) done++; }));
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    if (isLoading) return <div className="p-20 text-center animate-pulse text-indigo-600 font-bold">بارگذاری اهداف...</div>;

    return (
        <div className="space-y-10 pb-20">
            {/* --- ADVANCED BREAKDOWN MODAL --- */}
            {isModalOpen && (
                <div className="fixed inset-0 z-[150] flex items-center justify-center bg-gray-900/60 backdrop-blur-md p-4 animate-fade-in" onClick={() => setIsModalOpen(false)}>
                    <div className="bg-white rounded-[3rem] w-full max-w-2xl shadow-2xl flex flex-col overflow-hidden animate-scale-in" onClick={e => e.stopPropagation()}>
                        <div className="p-8 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                            <h3 className="text-2xl font-black text-gray-800 flex items-center gap-3">
                                <div className="p-2 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-100"><IconTarget className="w-6 h-6" /></div>
                                {editingTaskId ? t.modalEditTitle : t.modalTitle}
                            </h3>
                            <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-red-500 transition-all p-2 hover:bg-red-50 rounded-xl">✕</button>
                        </div>

                        <div className="p-8 space-y-8 overflow-y-auto max-h-[70vh] custom-scrollbar">
                            {/* Main Goal Input */}
                            <div className="space-y-3">
                                <label className="text-[11px] font-black text-indigo-600 uppercase tracking-widest block">{lang === 'fa' ? 'هدف استراتژیک' : 'Main Objective'}</label>
                                <textarea 
                                    className="w-full h-32 p-6 bg-gray-50 border-2 border-transparent focus:border-indigo-200 focus:bg-white rounded-3xl text-lg font-bold text-gray-800 outline-none transition-all resize-none shadow-inner"
                                    placeholder={t.mainPlaceholder}
                                    value={mainGoalText}
                                    onChange={e => setMainGoalText(e.target.value)}
                                    autoFocus
                                />
                            </div>

                            {/* Breakdown (Action Steps) */}
                            <div className="bg-gray-50 p-6 rounded-[2rem] border border-gray-100">
                                <label className="text-[11px] font-black text-gray-400 uppercase tracking-widest block mb-4">{t.subLabel}</label>
                                <div className="space-y-3 mb-6">
                                    {subTasks.map((st, idx) => (
                                        <div key={st.id} className="flex items-center gap-3 bg-white p-3 rounded-2xl border border-gray-200 shadow-sm animate-slide-in group">
                                            <div className="w-6 h-6 rounded-lg bg-indigo-50 text-indigo-600 flex items-center justify-center text-[10px] font-black">{idx + 1}</div>
                                            <input 
                                                className="flex-grow text-sm font-bold text-gray-700 bg-transparent outline-none"
                                                value={st.text}
                                                onChange={e => setSubTasks(subTasks.map(s => s.id === st.id ? { ...s, text: e.target.value } : s))}
                                            />
                                            <button onClick={() => setSubTasks(subTasks.filter(s => s.id !== st.id))} className="text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><IconTrash className="w-4 h-4" /></button>
                                        </div>
                                    ))}
                                </div>
                                <div className="flex gap-2">
                                    <input 
                                        className="flex-grow py-3 px-5 bg-white border border-gray-200 rounded-2xl text-sm font-bold outline-none focus:border-indigo-400 shadow-sm"
                                        placeholder={t.addSub + "..."}
                                        value={newSubInput}
                                        onChange={e => setNewSubInput(e.target.value)}
                                        onKeyDown={e => e.key === 'Enter' && (e.preventDefault(), handleAddSubInModal())}
                                    />
                                    <button onClick={handleAddSubInModal} className="bg-indigo-600 text-white px-5 rounded-2xl font-black text-xs hover:bg-indigo-700 transition-all">{t.addSub}</button>
                                </div>
                            </div>
                        </div>

                        <div className="p-8 border-t border-gray-100 bg-white flex gap-4">
                            <button onClick={() => setIsModalOpen(false)} className="flex-1 py-4 text-gray-400 font-bold hover:bg-gray-100 rounded-2xl transition-all">{t.cancel}</button>
                            <button onClick={handleSaveFullGoal} disabled={!mainGoalText.trim()} className="flex-[2] py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95 disabled:opacity-50">{t.save}</button>
                        </div>
                    </div>
                </div>
            )}

            {/* --- WEB UI --- */}
            <div className="space-y-10 animate-fade-in">
                {/* Dashboard Header */}
                <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-8">
                    <div className="flex items-center gap-6">
                        <div className="w-20 h-20 bg-indigo-600 rounded-[2.2rem] flex items-center justify-center text-white shadow-lg shadow-indigo-100"><IconTarget className="w-10 h-10" /></div>
                        <div>
                            <h2 className="text-3xl font-black text-gray-900 tracking-tight">{t.title}</h2>
                            <div className="flex items-center gap-2 mt-2">
                                <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{t.viewMode}</span>
                                <span className="px-3 py-1 bg-gray-100 text-gray-600 rounded-full text-[10px] font-black">{t[activePeriod as keyof typeof t.fa]}</span>
                            </div>
                        </div>
                    </div>
                    <div className="flex bg-gray-100 p-1.5 rounded-2xl">
                        {['daily', 'weekly', 'monthly', 'yearly', 'five_year'].map(p => (
                            <button key={p} onClick={() => setActivePeriod(p as GoalPeriod)} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${activePeriod === p ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>{t[p as keyof typeof t.fa]}</button>
                        ))}
                    </div>
                    <div className="flex items-center gap-6">
                        <div className="text-center"><div className="text-3xl font-black text-indigo-600">{stats.percent}%</div><div className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{t.progress}</div></div>
                        <button onClick={handleExportImage} disabled={isExporting} className="bg-slate-900 text-white px-6 py-3 rounded-2xl text-sm font-bold flex items-center gap-3 hover:bg-black transition-all shadow-xl active:scale-95 disabled:opacity-50">{isExporting ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : <IconPrinter className="w-5 h-5" />}{t.print}</button>
                    </div>
                </div>

                {isMaster && (
                    <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm flex items-center gap-4">
                        <span className="text-xs font-bold text-gray-500">مشاهده اهداف:</span>
                        <select className="bg-gray-50 border-none rounded-xl px-4 py-2 text-sm font-bold text-indigo-600 outline-none" value={selectedUserId} onChange={(e) => setSelectedUserId(e.target.value)}>{personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}</select>
                    </div>
                )}

                {/* Categories Grid (Dashboard Cards) */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-8">
                    {activeView.map((cat) => (
                        <div key={cat.id} className="bg-white rounded-[2.5rem] border border-gray-100 shadow-lg flex flex-col min-h-[600px] overflow-hidden group hover:shadow-2xl transition-shadow duration-500">
                            <div className={`p-6 text-center text-white font-black text-xs uppercase tracking-[0.2em] ${cat.color} shadow-lg shrink-0`}>
                                {cat.title}
                            </div>

                            <div className="flex-grow p-6 space-y-6 overflow-y-auto custom-scrollbar bg-gray-50/10">
                                {cat.tasks.map((task) => (
                                    <div key={task.id} className="bg-white rounded-3xl border border-gray-100 p-6 hover:border-indigo-200 transition-all shadow-sm relative group/task">
                                        <div className="flex items-start gap-4">
                                            <button onClick={() => toggleTask(cat.id, task.id)} className="w-7 h-7 rounded-xl border-2 border-indigo-100 bg-white flex items-center justify-center shrink-0 transition-all hover:border-indigo-600">
                                                {task.isCompleted && <IconCheck className="w-4 h-4 text-indigo-600" />}
                                            </button>
                                            <div className="flex-grow min-w-0">
                                                <span 
                                                    onClick={() => openEditModal(cat.id, task)}
                                                    className="text-[15px] font-black text-gray-800 cursor-pointer block leading-relaxed whitespace-pre-wrap hover:text-indigo-600"
                                                >
                                                    {task.text}
                                                </span>

                                                {/* Display Sub-tasks (Breakdown) in Card */}
                                                {task.subTasks && task.subTasks.length > 0 && (
                                                    <div className="mt-4 space-y-2 border-r-2 border-indigo-50 pr-4 mr-1">
                                                        {task.subTasks.slice(0, 5).map(st => (
                                                            <div key={st.id} className="flex items-center gap-2 text-[11px] font-bold text-gray-400">
                                                                <div className={`w-1.5 h-1.5 rounded-full ${st.isCompleted ? 'bg-green-500' : 'bg-gray-200'}`}></div>
                                                                <span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span>
                                                            </div>
                                                        ))}
                                                        {task.subTasks.length > 5 && <div className="text-[10px] text-indigo-400 font-black">+ {task.subTasks.length - 5} مورد دیگر</div>}
                                                    </div>
                                                )}
                                            </div>
                                            {canEdit && (
                                                <div className="flex flex-col gap-2 opacity-0 group-hover/task:opacity-100 transition-opacity">
                                                    <button onClick={() => openEditModal(cat.id, task)} className="text-gray-400 hover:text-indigo-600 p-1"><IconEdit className="w-4 h-4"/></button>
                                                    <button onClick={() => {if(confirm('حذف این هدف؟')) syncGoals(currentUserGoals!.categories.map(c => c.id === cat.id ? {...c, tasks: c.tasks.filter(t => t.id !== task.id)} : c))}} className="text-gray-300 hover:text-red-500 p-1"><IconTrash className="w-4 h-4"/></button>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                ))}
                                {cat.tasks.length === 0 && <div className="text-center py-20 text-gray-300 font-bold text-sm italic">{t.empty}</div>}
                            </div>

                            {canEdit && (
                                <div className="p-6 border-t border-gray-50 bg-gray-50/20 shrink-0">
                                    <button onClick={() => openAddModal(cat.id)} className="w-full py-4 bg-white border-2 border-dashed border-gray-200 rounded-3xl text-gray-400 text-[11px] font-black hover:text-indigo-600 hover:border-indigo-400 transition-all flex items-center justify-center gap-2 shadow-sm">
                                        <IconPlus className="w-4 h-4" /> {t.addGoal}
                                    </button>
                                </div>
                            )}
                        </div>
                    ))}
                </div>

                {/* History Section */}
                {historyView.length > 0 && (
                    <div className="bg-white p-10 rounded-[3.5rem] border border-gray-100 shadow-xl animate-fade-in">
                        <div className="flex items-center gap-4 mb-10">
                            <div className="p-4 bg-amber-100 text-amber-600 rounded-[1.5rem] shadow-lg shadow-amber-50"><IconTrophy className="w-8 h-8" /></div>
                            <div><h3 className="text-3xl font-black text-gray-900">{t.historyTitle}</h3><p className="text-sm text-gray-400 font-bold">ماموریت‌های با موفقیت انجام شده</p></div>
                        </div>
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                            {historyView.map((goal, idx) => (
                                <div key={idx} className="bg-gray-50 p-6 rounded-[2.5rem] border border-gray-200 flex flex-col gap-3 relative group overflow-hidden">
                                    <div className="flex items-center gap-3">
                                        <IconStar className="w-6 h-6 text-amber-500 fill-current" />
                                        <div className="min-w-0">
                                            <h4 className="text-[14px] font-black text-gray-800 line-through opacity-40 truncate">{goal.text}</h4>
                                            <p className="text-[10px] font-bold text-gray-400 uppercase mt-1">{goal.categoryTitle}</p>
                                        </div>
                                    </div>
                                    <button onClick={() => toggleTask(goal.categoryTitle, goal.id)} className="mt-3 text-[11px] text-indigo-600 font-black opacity-0 group-hover:opacity-100 transition-opacity underline decoration-2">{t.restore}</button>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>

            {/* Poster Canvas (Hidden) */}
            <div style={{ position: 'fixed', left: '-9999px', top: 0 }}>
                <div ref={posterRef} className="flex flex-col bg-white overflow-hidden p-20 relative" style={{ width: '840px', height: '1188px' }}>
                    <div className="absolute inset-10 border-[12px] border-gray-50 pointer-events-none"></div>
                    <div className="absolute inset-14 border border-gray-200 pointer-events-none"></div>
                    <div className="flex justify-between items-start mb-16 relative z-10">
                        <div className="flex items-center gap-8">
                            <div className="w-32 h-32 rounded-[2.5rem] overflow-hidden border-2 border-gray-100 bg-gray-50 shadow-sm">{selectedPerson?.avatar ? <img src={selectedPerson.avatar} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-5xl font-black text-gray-200">{selectedPerson?.fullName.charAt(0)}</div>}</div>
                            <div>
                                <h1 className="text-6xl font-black text-gray-900 mb-2 tracking-tighter">{selectedPerson?.fullName}</h1>
                                <div className="flex gap-2">{selectedPerson?.roles.map(r => <span key={r} className="bg-gray-100 text-gray-500 px-5 py-1.5 rounded-xl text-xs font-black uppercase tracking-widest">{r}</span>)}</div>
                            </div>
                        </div>
                        <div className="text-right"><div className="text-8xl font-black text-indigo-600 leading-none mb-2">{stats.percent}%</div><div className="text-xs font-bold text-gray-400 uppercase tracking-[0.3em]">{t.progress}</div></div>
                    </div>
                    <div className="bg-slate-900 text-white p-12 rounded-[2.5rem] mb-12 flex justify-between items-center shadow-2xl">
                        <div className="flex items-center gap-5"><IconShield className="w-10 h-10" /><h2 className="text-3xl font-black uppercase tracking-tight">STRATEGIC PERFORMANCE ROADMAP</h2></div>
                        <div className="font-mono text-lg opacity-60 font-bold">{activePeriod.toUpperCase()} / {new Date().getFullYear()}</div>
                    </div>
                    <div className="flex-grow grid grid-cols-2 gap-x-16 gap-y-16 content-start mb-16">
                        {activeView.map((cat) => (
                            <div key={cat.id} className="space-y-8">
                                <div className="flex items-center gap-4 border-b-2 border-gray-100 pb-4"><div className={`w-4 h-4 rounded-full ${cat.color} shadow-sm`}></div><h3 className="text-2xl font-black text-gray-800 uppercase tracking-widest">{cat.title}</h3></div>
                                <div className="space-y-12">
                                    {cat.tasks.map((task) => (
                                        <div key={task.id} className="flex gap-6">
                                            <div className="w-6 h-6 rounded-full border-4 border-gray-200 mt-1.5 shrink-0"></div>
                                            <div className="flex-grow min-w-0">
                                                <div className="text-2xl font-black text-gray-800 leading-snug mb-3">{task.text}</div>
                                                {task.subTasks && task.subTasks.length > 0 && (
                                                    <div className="space-y-3 pl-8 border-r-4 border-gray-50 mt-5 py-1">
                                                        {task.subTasks.map(st => (<div key={st.id} className="text-base font-bold text-gray-400 flex items-center gap-4"><div className={`w-3 h-3 rounded-md ${st.isCompleted ? 'bg-indigo-500' : 'bg-gray-100'}`}></div><span className={st.isCompleted ? 'line-through opacity-50' : ''}>{st.text}</span></div>))}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                    <div className="border-t border-gray-200 pt-12 flex justify-between items-end">
                        <div className="max-w-[70%]"><p className="text-[12px] font-black text-indigo-600 uppercase tracking-[0.5em] mb-4">CORE LEADERSHIP VISION</p><p className="text-3xl font-black text-gray-500 italic leading-relaxed">"{t.visionNote}"</p></div>
                        <div className="flex flex-col items-end"><div className="w-32 h-32 bg-indigo-600 flex items-center justify-center rounded-[2.5rem] shadow-2xl shadow-indigo-100 mb-6 border-4 border-white"><IconShield className="w-14 h-14 text-white" /></div><span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em]">STRATEGIC PERFORMANCE CERTIFIED</span></div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconShield, IconPrinter, IconTrophy, IconList, IconStar, IconAward, IconArrowRight } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';
import * as htmlToImage from 'html-to-image';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف تجاری و فروش', color: 'bg-indigo-600', type: 'business' as const },
    { id: 'cat2', title: 'توسعه بازار و برندینگ', color: 'bg-emerald-600', type: 'business' as const },
    { id: 'cat3', title: 'بهره‌وری و فرآیندها', color: 'bg-amber-500', type: 'business' as const },
    { id: 'cat4', title: 'آموزش و رشد فردی', color: 'bg-rose-500', type: 'personal' as const },
    { id: 'cat5', title: 'سایر اولویت‌های کلیدی', color: 'bg-slate-700', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isExporting, setIsExporting] = useState(false);

    // UI states for live editing
    const [editingCatId, setEditingCatId] = useState<string | null>(null);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [targetCatId, setTargetCatId] = useState<string | null>(null);
    const [editingTaskId, setEditingTaskId] = useState<string | null>(null);
    const [mainGoalText, setMainGoalText] = useState('');
    const [subTasks, setSubTasks] = useState<GoalSubTask[]>([]);
    const [newSubInput, setNewSubInput] = useState('');

    const posterRef = useRef<HTMLDivElement>(null);
    const canEdit = selectedUserId === currentUser.id || currentUser.username === 'master';

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    const t = {
        fa: {
            title: 'میز خدمت و اهداف استراتژیک',
            daily: 'امروز', weekly: 'هفتگی', monthly: 'ماهانه', yearly: 'سالانه', five_year: '۵ ساله',
            viewMode: 'بازه برنامه ریزی:',
            addGoal: 'افزودن هدف/برنامه',
            progress: 'درصد تحقق',
            empty: 'هنوز هدفی تعریف نشده است.',
            print: 'خروجی پوستر',
            modalTitle: 'مهندسی و خرد کردن هدف',
            mainLabel: 'عنوان اصلی هدف یا ماموریت:',
            subLabel: 'گام‌های اجرایی (Breakdown):',
            addSub: 'افزودن سطر',
            save: 'ذخیره نهایی',
            historyTitle: 'تالار افتخارات',
            restore: 'بازیابی'
        },
        en: {
            title: 'Strategic Goals Dashboard',
            daily: 'Daily', weekly: 'Weekly', monthly: 'Monthly', yearly: 'Yearly', five_year: '5-Year',
            viewMode: 'Planning Period:',
            addGoal: 'Add Mission',
            progress: 'Progress',
            empty: 'No objectives set.',
            print: 'Export Poster',
            modalTitle: 'Goal Engineering',
            mainLabel: 'Main Objective:',
            subLabel: 'Action Steps (Breakdown):',
            addSub: 'Add Step',
            save: 'Save Changes',
            historyTitle: 'Hall of Fame',
            restore: 'Restore'
        }
    }[lang];

    const handleSync = (updatedCategories: GoalCategory[]) => {
        if (!currentUserGoals) return;
        const updated = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updated);
        saveUserGoals(updated);
    };

    const openGoalModal = (catId: string, task?: GoalTask) => {
        if (!canEdit) return;
        setTargetCatId(catId);
        if (task) {
            setEditingTaskId(task.id);
            setMainGoalText(task.text);
            setSubTasks(task.subTasks || []);
        } else {
            setEditingTaskId(null);
            setMainGoalText('');
            setSubTasks([]);
        }
        setIsModalOpen(true);
    };

    const handleSaveGoal = () => {
        if (!mainGoalText.trim() || !currentUserGoals || !targetCatId) return;
        let updated;
        if (editingTaskId) {
            updated = currentUserGoals.categories.map(c => c.id === targetCatId ? { ...c, tasks: c.tasks.map(t => t.id === editingTaskId ? { ...t, text: mainGoalText, subTasks } : t) } : c);
        } else {
            updated = currentUserGoals.categories.map(c => c.id === targetCatId ? { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: mainGoalText, isCompleted: false, subTasks }] } : c);
        }
        handleSync(updated);
        setIsModalOpen(false);
    };

    const handleEditCategoryTitle = (catId: string, newTitle: string) => {
        if (!currentUserGoals) return;
        const updated = currentUserGoals.categories.map(c => c.id === catId ? { ...c, title: newTitle } : c);
        handleSync(updated);
        setEditingCatId(null);
    };

    const handleDeleteTask = (catId: string, taskId: string) => {
        if (!canEdit || !confirm('از حذف این هدف اطمینان دارید؟')) return;
        const updated = currentUserGoals!.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.filter(t => t.id !== taskId) } : c);
        handleSync(updated);
    };

    const toggleTaskStatus = (catId: string, taskId: string) => {
        if (!canEdit) return;
        const updated = currentUserGoals!.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, isCompleted: !t.isCompleted, subTasks: t.subTasks?.map(st => ({ ...st, isCompleted: !t.isCompleted })) } : t) } : c);
        handleSync(updated);
    };

    const stats = useMemo(() => {
        if (!currentUserGoals) return { percent: 0 };
        let total = 0, done = 0;
        currentUserGoals.categories.forEach(c => c.tasks.forEach(t => { total++; if (t.isCompleted) done++; }));
        return { percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const handleExport = async () => {
        if (!posterRef.current) return;
        setIsExporting(true);
        const dataUrl = await htmlToImage.toPng(posterRef.current, { quality: 1, pixelRatio: 3 });
        const link = document.createElement('a');
        link.download = `Strategy-${activePeriod}.png`;
        link.href = dataUrl;
        link.click();
        setIsExporting(false);
    };

    if (isLoading) return <div className="p-20 text-center animate-pulse text-indigo-600 font-black">در حال آماده سازی تخته استراتژیک...</div>;

    return (
        <div className="space-y-10 pb-24">
            {/* Mission Breakdown Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center bg-indigo-900/40 backdrop-blur-xl p-4 animate-fade-in" onClick={() => setIsModalOpen(false)}>
                    <div className="bg-white rounded-[3.5rem] w-full max-w-2xl shadow-2xl flex flex-col overflow-hidden animate-scale-in border border-white" onClick={e => e.stopPropagation()}>
                        <div className="p-10 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                            <h3 className="text-2xl font-black text-gray-900 flex items-center gap-4">
                                <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-xl shadow-indigo-100"><IconTarget className="w-6 h-6" /></div>
                                {t.modalTitle}
                            </h3>
                            <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-red-500 transition-all p-2 hover:bg-red-50 rounded-2xl">✕</button>
                        </div>
                        <div className="p-10 space-y-10 overflow-y-auto max-h-[70vh] custom-scrollbar">
                            <div className="space-y-4">
                                <label className="text-[11px] font-black text-indigo-600 uppercase tracking-[0.2em] block">{t.mainLabel}</label>
                                <textarea 
                                    className="w-full p-8 bg-gray-50 border-2 border-transparent focus:border-indigo-100 focus:bg-white rounded-[2.5rem] text-xl font-bold text-gray-900 outline-none transition-all resize-none shadow-inner leading-relaxed"
                                    rows={3}
                                    placeholder="شرح هدف اصلی..."
                                    value={mainGoalText}
                                    onChange={e => setMainGoalText(e.target.value)}
                                    autoFocus
                                />
                            </div>
                            <div className="bg-gray-50 p-8 rounded-[3rem] border border-gray-100">
                                <label className="text-[11px] font-black text-gray-400 uppercase tracking-widest block mb-6">{t.subLabel}</label>
                                <div className="space-y-4 mb-8">
                                    {subTasks.map((st, idx) => (
                                        <div key={st.id} className="flex items-center gap-4 bg-white p-4 rounded-2xl border border-gray-200 shadow-sm group">
                                            <div className="w-8 h-8 rounded-xl bg-indigo-50 text-indigo-600 flex items-center justify-center text-xs font-black shrink-0">{idx + 1}</div>
                                            <input className="flex-grow text-sm font-bold text-gray-800 bg-transparent outline-none" value={st.text} onChange={e => setSubTasks(subTasks.map(s => s.id === st.id ? {...s, text: e.target.value} : s))} />
                                            <button onClick={() => setSubTasks(subTasks.filter(s => s.id !== st.id))} className="text-red-300 hover:text-red-600 p-1 opacity-0 group-hover:opacity-100 transition-opacity"><IconTrash className="w-4 h-4" /></button>
                                        </div>
                                    ))}
                                </div>
                                <div className="flex gap-3">
                                    <input 
                                        className="flex-grow py-4 px-6 bg-white border-2 border-gray-100 rounded-2xl text-sm font-bold outline-none focus:border-indigo-300 transition-all shadow-sm"
                                        placeholder="تایپ کنید و اینتر بزنید..."
                                        value={newSubInput}
                                        onChange={e => setNewSubInput(e.target.value)}
                                        onKeyDown={e => { if(e.key==='Enter') { e.preventDefault(); if(!newSubInput.trim()) return; setSubTasks([...subTasks, {id: `st-${Date.now()}`, text: newSubInput.trim(), isCompleted: false}]); setNewSubInput(''); } }}
                                    />
                                    <button onClick={() => { if(!newSubInput.trim()) return; setSubTasks([...subTasks, {id: `st-${Date.now()}`, text: newSubInput.trim(), isCompleted: false}]); setNewSubInput(''); }} className="bg-indigo-600 text-white px-6 rounded-2xl font-black text-xs hover:bg-indigo-700 transition-all">{t.addSub}</button>
                                </div>
                            </div>
                        </div>
                        <div className="p-10 border-t border-gray-100 bg-white flex gap-4">
                            <button onClick={() => setIsModalOpen(false)} className="flex-1 py-5 text-gray-400 font-bold hover:bg-gray-50 rounded-2xl transition-all uppercase text-xs tracking-widest">{lang==='fa'?'انصراف':'Cancel'}</button>
                            <button onClick={handleSaveGoal} disabled={!mainGoalText.trim()} className="flex-[2] py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-2xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95 disabled:opacity-50">{t.save}</button>
                        </div>
                    </div>
                </div>
            )}

            {/* DASHBOARD HEADER */}
            <div className="bg-white p-10 rounded-[4rem] shadow-2xl border border-gray-50 flex flex-col lg:flex-row justify-between items-center gap-10">
                <div className="flex items-center gap-8">
                    <div className="w-24 h-24 bg-gradient-to-br from-indigo-600 to-blue-700 rounded-[2.5rem] flex items-center justify-center text-white shadow-2xl shadow-indigo-200 rotate-3 transition-transform hover:rotate-0 cursor-pointer"><IconTarget className="w-12 h-12" /></div>
                    <div>
                        <h2 className="text-4xl font-black text-gray-900 tracking-tighter mb-2">{t.title}</h2>
                        <div className="flex items-center gap-3">
                            <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">{t.viewMode}</span>
                            <div className="flex bg-gray-100 p-1 rounded-2xl">
                                {['daily', 'weekly', 'monthly', 'yearly'].map(p => (
                                    <button key={p} onClick={() => setActivePeriod(p as any)} className={`px-5 py-2 rounded-xl text-[10px] font-black transition-all ${activePeriod === p ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}>{t[p as keyof typeof t.fa]}</button>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>

                <div className="flex items-center gap-10">
                    <div className="text-center">
                        <div className="text-5xl font-black text-indigo-600 leading-none mb-2">{stats.percent}%</div>
                        <div className="text-[9px] font-black text-gray-400 uppercase tracking-widest">{t.progress}</div>
                    </div>
                    <div className="h-16 w-px bg-gray-100"></div>
                    <button onClick={handleExport} disabled={isExporting} className="bg-slate-900 text-white px-8 py-4 rounded-3xl font-black text-xs flex items-center gap-3 hover:bg-black transition-all shadow-2xl hover:-translate-y-1 active:scale-95 disabled:opacity-50">
                        {isExporting ? '...' : <IconPrinter className="w-5 h-5" />} {t.print}
                    </button>
                </div>
            </div>

            {/* STRATEGY BOARD (The Columns) */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-8">
                {currentUserGoals?.categories.map(cat => (
                    <div key={cat.id} className="flex flex-col min-h-[700px] group">
                        {/* CATEGORY TITLE (Editable) */}
                        <div className="mb-6 px-4">
                            {editingCatId === cat.id ? (
                                <input 
                                    className="w-full bg-indigo-50 border-2 border-indigo-200 rounded-2xl py-3 px-4 text-sm font-black text-indigo-900 outline-none text-center"
                                    value={cat.title}
                                    autoFocus
                                    onBlur={() => setEditingCatId(null)}
                                    onKeyDown={e => e.key === 'Enter' && handleEditCategoryTitle(cat.id, (e.target as HTMLInputElement).value)}
                                    onChange={e => handleSync(currentUserGoals.categories.map(c => c.id === cat.id ? {...c, title: e.target.value} : c))}
                                />
                            ) : (
                                <div 
                                    onClick={() => canEdit && setEditingCatId(cat.id)}
                                    className="flex items-center justify-between group/title cursor-pointer"
                                >
                                    <h3 className="text-sm font-black text-gray-400 uppercase tracking-[0.2em] group-hover/title:text-indigo-600 transition-colors">{cat.title}</h3>
                                    <IconPlus className="w-4 h-4 text-gray-200 group-hover/title:text-indigo-400" />
                                </div>
                            )}
                        </div>

                        {/* TASK CARDS (Full Display) */}
                        <div className="space-y-6 flex-grow">
                            {cat.tasks.filter(t => !t.isCompleted).map(task => (
                                <div key={task.id} className="bg-white rounded-[2.5rem] border border-gray-100 p-8 shadow-xl shadow-gray-200/50 hover:shadow-indigo-100 hover:border-indigo-100 transition-all relative group/card">
                                    <div className="flex items-start gap-5">
                                        <button onClick={() => toggleTaskStatus(cat.id, task.id)} className="w-8 h-8 rounded-2xl border-2 border-gray-100 bg-white flex items-center justify-center shrink-0 transition-all hover:border-indigo-400 group/check">
                                            <div className="w-3 h-3 rounded-full bg-indigo-50 group-hover/check:bg-indigo-500 transition-colors"></div>
                                        </button>
                                        <div className="flex-grow min-w-0" onClick={() => openGoalModal(cat.id, task)}>
                                            <div className="text-lg font-black text-gray-900 leading-snug whitespace-pre-wrap cursor-pointer hover:text-indigo-600 transition-colors mb-4">{task.text}</div>

                                            {/* FULL BREAKDOWN DISPLAY */}
                                            {task.subTasks && task.subTasks.length > 0 && (
                                                <div className="space-y-3 mt-4 pt-4 border-t border-gray-50">
                                                    {task.subTasks.map(st => (
                                                        <div key={st.id} className="flex items-center gap-3 text-[11px] font-bold text-gray-400">
                                                            <div className={`w-1.5 h-1.5 rounded-full ${st.isCompleted ? 'bg-green-500' : 'bg-gray-200'}`}></div>
                                                            <span className={st.isCompleted ? 'line-through' : ''}>{st.text}</span>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    </div>

                                    {/* Edit/Delete Actions */}
                                    <div className="absolute top-6 rtl:left-6 ltr:right-6 flex flex-col gap-2 opacity-0 group-hover/card:opacity-100 transition-opacity">
                                        <button onClick={() => openGoalModal(cat.id, task)} className="p-2 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all"><IconEdit className="w-4 h-4" /></button>
                                        <button onClick={() => handleDeleteTask(cat.id, task.id)} className="p-2 bg-red-50 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all"><IconTrash className="w-4 h-4" /></button>
                                    </div>
                                </div>
                            ))}

                            {/* ADD NEW GOAL BUTTON */}
                            {canEdit && (
                                <button 
                                    onClick={() => openGoalModal(cat.id)}
                                    className="w-full py-8 border-2 border-dashed border-gray-100 rounded-[2.5rem] flex flex-col items-center justify-center gap-3 text-gray-300 hover:border-indigo-200 hover:text-indigo-400 hover:bg-indigo-50/30 transition-all group/add"
                                >
                                    <div className="w-10 h-10 rounded-full border-2 border-current flex items-center justify-center group-hover/add:scale-110 transition-transform"><IconPlus className="w-6 h-6" /></div>
                                    <span className="text-[10px] font-black uppercase tracking-widest">{t.addGoal}</span>
                                </button>
                            )}
                        </div>
                    </div>
                ))}
            </div>

            {/* ARCHIVE / SUCCESS HISTORY */}
            {currentUserGoals?.categories.some(c => c.tasks.some(t => t.isCompleted)) && (
                <div className="mt-20 bg-indigo-50/50 p-12 rounded-[5rem] border border-indigo-100/50 animate-fade-in">
                    <div className="flex items-center gap-4 mb-10">
                        <div className="p-4 bg-white text-amber-500 rounded-3xl shadow-xl shadow-indigo-100"><IconTrophy className="w-8 h-8" /></div>
                        <div><h3 className="text-3xl font-black text-gray-900">{t.historyTitle}</h3><p className="text-xs text-indigo-400 font-bold uppercase tracking-widest mt-1">Achievements and Completed Milestones</p></div>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                        {currentUserGoals.categories.flatMap(c => c.tasks.filter(t => t.isCompleted).map(t => ({...t, catId: c.id, catTitle: c.title}))).map(goal => (
                            <div key={goal.id} className="bg-white p-6 rounded-[2.5rem] border border-white shadow-lg relative group overflow-hidden">
                                <div className="flex items-center gap-4">
                                    <IconStar className="w-6 h-6 text-amber-400 fill-current" />
                                    <div className="min-w-0">
                                        <h4 className="text-sm font-black text-gray-800 line-through opacity-40 truncate">{goal.text}</h4>
                                        <p className="text-[9px] font-black text-indigo-300 uppercase mt-1 tracking-widest">{goal.catTitle}</p>
                                    </div>
                                </div>
                                <button onClick={() => toggleTaskStatus(goal.catId, goal.id)} className="absolute inset-0 bg-indigo-600 text-white flex items-center justify-center gap-2 text-xs font-black opacity-0 group-hover:opacity-100 transition-opacity rounded-[2.5rem]">
                                    <IconArrowRight className="w-4 h-4 rtl:rotate-180" /> {t.restore}
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* HIDDEN POSTER CANVAS */}
            <div style={{ position: 'fixed', left: '-9999px', top: 0 }}>
                <div ref={posterRef} className="bg-white p-20 flex flex-col" style={{ width: '1200px', height: '1600px' }}>
                    <div className="border-[20px] border-gray-50 flex-grow p-16 flex flex-col relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-96 h-96 bg-indigo-50 rounded-full -mr-32 -mt-32 opacity-50"></div>
                        <div className="flex justify-between items-start mb-20 relative z-10">
                            <div>
                                <h1 className="text-7xl font-black text-gray-900 mb-4 tracking-tighter uppercase">{currentUserGoals?.userName}</h1>
                                <div className="flex gap-4">{personnel.find(p=>p.id===selectedUserId)?.roles.map(r => <span key={r} className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-xs font-black tracking-widest uppercase">{r}</span>)}</div>
                            </div>
                            <div className="text-right"><div className="text-9xl font-black text-indigo-600 leading-none">{stats.percent}%</div><div className="text-sm font-black text-gray-400 tracking-[0.4em] uppercase">{t.progress}</div></div>
                        </div>
                        <div className="bg-slate-900 text-white p-16 rounded-[4rem] mb-20 flex justify-between items-center shadow-2xl">
                            <div className="flex items-center gap-8"><IconShield className="w-16 h-16" /><h2 className="text-4xl font-black uppercase tracking-tight">Strategy Execution Roadmap</h2></div>
                            <div className="text-2xl font-mono font-black opacity-40">{activePeriod.toUpperCase()} / {new Date().getFullYear()}</div>
                        </div>
                        <div className="flex-grow grid grid-cols-2 gap-20">
                            {currentUserGoals?.categories.map(cat => (
                                <div key={cat.id} className="space-y-10">
                                    <div className="border-b-4 border-gray-100 pb-6 flex items-center gap-6"><div className={`w-6 h-6 rounded-full ${cat.color}`}></div><h3 className="text-3xl font-black uppercase tracking-widest text-gray-800">{cat.title}</h3></div>
                                    <div className="space-y-12">
                                        {cat.tasks.filter(t => !t.isCompleted).map(task => (
                                            <div key={task.id} className="flex gap-8">
                                                <div className="w-8 h-8 rounded-full border-4 border-indigo-200 mt-2 shrink-0"></div>
                                                <div className="flex-grow">
                                                    <div className="text-3xl font-bold text-gray-900 leading-snug mb-4">{task.text}</div>
                                                    <div className="space-y-3 pl-10 border-l-4 border-gray-50 py-2">
                                                        {task.subTasks?.map(st => (<div key={st.id} className="text-lg font-bold text-gray-400 flex items-center gap-4"><div className="w-3 h-3 rounded-md bg-gray-200"></div>{st.text}</div>))}
                                                    </div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

