import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconShield, IconPrinter, IconTrophy, IconList, IconStar, IconAward, IconArrowRight, IconClock, IconCalendar } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';
import * as htmlToImage from 'html-to-image';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف تجاری و فروش', color: 'bg-indigo-600', type: 'business' as const },
    { id: 'cat2', title: 'توسعه بازار و برندینگ', color: 'bg-emerald-600', type: 'business' as const },
    { id: 'cat3', title: 'بهره‌وری و فرآیندها', color: 'bg-amber-500', type: 'business' as const },
    { id: 'cat4', title: 'آموزش و رشد فردی', color: 'bg-rose-500', type: 'personal' as const },
    { id: 'cat5', title: 'سایر اولویت‌های کلیدی', color: 'bg-slate-700', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isExporting, setIsExporting] = useState(false);

    // UI states for professional modal
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [targetCatId, setTargetCatId] = useState<string | null>(null);
    const [editingTaskId, setEditingTaskId] = useState<string | null>(null);
    const [mainGoalText, setMainGoalText] = useState('');
    const [deadline, setDeadline] = useState('');
    const [subTasks, setSubTasks] = useState<GoalSubTask[]>([]);
    const [newSubInput, setNewSubInput] = useState('');

    const posterRef = useRef<HTMLDivElement>(null);
    const canEdit = selectedUserId === currentUser.id || currentUser.username === 'master';

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    const t = {
        fa: {
            title: 'میز فرماندهی اهداف استراتژیک',
            daily: 'امروز', weekly: 'هفتگی', monthly: 'ماهانه', yearly: 'سالانه', five_year: '۵ ساله',
            viewMode: 'بازه برنامه ریزی:',
            addGoal: 'افزودن ماموریت جدید',
            progress: 'میزان تحقق',
            empty: 'هنوز هدفی برای این بازه تعریف نکرده‌اید.',
            print: 'دریافت نسخه چاپی',
            modalTitle: 'مهندسی و خرد کردن ماموریت',
            mainLabel: 'شرح کامل هدف یا ماموریت اصلی:',
            subLabel: 'گام‌های اجرایی و برنامه عملیاتی (Breakdown):',
            deadlineLabel: 'تاریخ ددلاین / ضرب‌الاجل:',
            addSub: 'افزودن سطر عملیاتی',
            save: 'ذخیره و انتشار',
            historyTitle: 'دستاوردها و اهداف محقق شده',
            restore: 'بازیابی به جاری',
            deadline: 'مهلت:'
        },
        en: {
            title: 'Strategic Goals Center',
            daily: 'Daily', weekly: 'Weekly', monthly: 'Monthly', yearly: 'Yearly', five_year: '5-Year',
            viewMode: 'Timeframe:',
            addGoal: 'New Mission',
            progress: 'Progress',
            empty: 'No objectives defined for this period.',
            print: 'Export Poster',
            modalTitle: 'Mission Engineering',
            mainLabel: 'Full Mission/Objective Description:',
            subLabel: 'Action Steps & Breakdown:',
            deadlineLabel: 'Deadline Date:',
            addSub: 'Add Action Line',
            save: 'Save & Publish',
            historyTitle: 'Hall of Fame',
            restore: 'Restore',
            deadline: 'Deadline:'
        }
    }[lang];

    const handleSync = (updatedCategories: GoalCategory[]) => {
        if (!currentUserGoals) return;
        const updated = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updated);
        saveUserGoals(updated);
    };

    const openGoalModal = (catId: string, task?: GoalTask) => {
        if (!canEdit) return;
        setTargetCatId(catId);
        if (task) {
            setEditingTaskId(task.id);
            setMainGoalText(task.text);
            setDeadline(task.deadline || '');
            setSubTasks(task.subTasks || []);
        } else {
            setEditingTaskId(null);
            setMainGoalText('');
            setDeadline('');
            setSubTasks([]);
        }
        setIsModalOpen(true);
    };

    const handleSaveGoal = () => {
        if (!mainGoalText.trim() || !currentUserGoals || !targetCatId) return;
        let updated;
        if (editingTaskId) {
            updated = currentUserGoals.categories.map(c => c.id === targetCatId ? { ...c, tasks: c.tasks.map(t => t.id === editingTaskId ? { ...t, text: mainGoalText, deadline, subTasks } : t) } : c);
        } else {
            updated = currentUserGoals.categories.map(c => c.id === targetCatId ? { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: mainGoalText, deadline, isCompleted: false, subTasks }] } : c);
        }
        handleSync(updated);
        setIsModalOpen(false);
    };

    const toggleTaskStatus = (catId: string, taskId: string) => {
        if (!canEdit) return;
        const updated = currentUserGoals!.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, isCompleted: !t.isCompleted, subTasks: t.subTasks?.map(st => ({ ...st, isCompleted: !t.isCompleted })) } : t) } : c);
        handleSync(updated);
    };

    const stats = useMemo(() => {
        if (!currentUserGoals) return { percent: 0 };
        let total = 0, done = 0;
        currentUserGoals.categories.forEach(c => c.tasks.forEach(t => { total++; if (t.isCompleted) done++; }));
        return { percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const handleExport = async () => {
        if (!posterRef.current) return;
        setIsExporting(true);
        const dataUrl = await htmlToImage.toPng(posterRef.current, { quality: 1, pixelRatio: 3 });
        const link = document.createElement('a');
        link.download = `Strategy-${activePeriod}.png`;
        link.href = dataUrl;
        link.click();
        setIsExporting(false);
    };

    if (isLoading) return <div className="p-20 text-center animate-pulse text-indigo-600 font-black">در حال بارگذاری تخته استراتژیک...</div>;

    return (
        <div className="space-y-10 pb-24 max-w-[1600px] mx-auto">
            {/* --- GOAL ENGINEERING MODAL --- */}
            {isModalOpen && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center bg-gray-900/70 backdrop-blur-md p-4 animate-fade-in" onClick={() => setIsModalOpen(false)}>
                    <div className="bg-white rounded-[3rem] w-full max-w-3xl shadow-2xl flex flex-col overflow-hidden animate-scale-in border border-gray-100" onClick={e => e.stopPropagation()}>
                        <div className="p-8 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                            <h3 className="text-2xl font-black text-gray-900 flex items-center gap-4">
                                <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-xl shadow-indigo-100"><IconTarget className="w-7 h-7" /></div>
                                {t.modalTitle}
                            </h3>
                            <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-red-500 transition-all p-2 hover:bg-red-50 rounded-2xl">✕</button>
                        </div>

                        <div className="p-10 space-y-8 overflow-y-auto max-h-[75vh] custom-scrollbar">
                            <div className="space-y-4">
                                <label className="text-[11px] font-black text-indigo-600 uppercase tracking-widest block">{t.mainLabel}</label>
                                <textarea 
                                    className="w-full p-8 bg-gray-50 border-2 border-transparent focus:border-indigo-100 focus:bg-white rounded-[2.5rem] text-xl font-bold text-gray-900 outline-none transition-all resize-none shadow-inner leading-relaxed"
                                    rows={3}
                                    placeholder="..."
                                    value={mainGoalText}
                                    onChange={e => setMainGoalText(e.target.value)}
                                    autoFocus
                                />
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div className="bg-indigo-50/50 p-6 rounded-[2rem] border border-indigo-100">
                                    <label className="text-[11px] font-black text-indigo-900 uppercase tracking-widest block mb-3 flex items-center gap-2">
                                        <IconCalendar className="w-4 h-4" /> {t.deadlineLabel}
                                    </label>
                                    <input 
                                        type="date" 
                                        className="w-full bg-white border border-indigo-200 rounded-xl px-4 py-3 text-sm font-bold text-indigo-700 outline-none focus:ring-2 focus:ring-indigo-500"
                                        value={deadline}
                                        onChange={e => setDeadline(e.target.value)}
                                    />
                                </div>
                            </div>

                            <div className="bg-gray-50 p-8 rounded-[3rem] border border-gray-100">
                                <label className="text-[11px] font-black text-gray-400 uppercase tracking-widest block mb-6">{t.subLabel}</label>
                                <div className="space-y-4 mb-8">
                                    {subTasks.map((st, idx) => (
                                        <div key={st.id} className="flex items-center gap-4 bg-white p-4 rounded-2xl border border-gray-200 shadow-sm group">
                                            <div className="w-8 h-8 rounded-xl bg-indigo-50 text-indigo-600 flex items-center justify-center text-xs font-black shrink-0">{idx + 1}</div>
                                            <input className="flex-grow text-sm font-bold text-gray-800 bg-transparent outline-none" value={st.text} onChange={e => setSubTasks(subTasks.map(s => s.id === st.id ? {...s, text: e.target.value} : s))} />
                                            <button onClick={() => setSubTasks(subTasks.filter(s => s.id !== st.id))} className="text-red-300 hover:text-red-600 p-1 opacity-0 group-hover:opacity-100 transition-opacity"><IconTrash className="w-4 h-4" /></button>
                                        </div>
                                    ))}
                                </div>
                                <div className="flex gap-3">
                                    <input 
                                        className="flex-grow py-4 px-6 bg-white border-2 border-gray-100 rounded-2xl text-sm font-bold outline-none focus:border-indigo-300 transition-all shadow-sm"
                                        placeholder="تایپ کنید و اینتر بزنید..."
                                        value={newSubInput}
                                        onChange={e => setNewSubInput(e.target.value)}
                                        onKeyDown={e => { if(e.key==='Enter') { e.preventDefault(); if(!newSubInput.trim()) return; setSubTasks([...subTasks, {id: `st-${Date.now()}`, text: newSubInput.trim(), isCompleted: false}]); setNewSubInput(''); } }}
                                    />
                                    <button onClick={() => { if(!newSubInput.trim()) return; setSubTasks([...subTasks, {id: `st-${Date.now()}`, text: newSubInput.trim(), isCompleted: false}]); setNewSubInput(''); }} className="bg-indigo-600 text-white px-6 rounded-2xl font-black text-xs hover:bg-indigo-700 transition-all">{t.addSub}</button>
                                </div>
                            </div>
                        </div>

                        <div className="p-8 border-t border-gray-100 bg-white flex gap-4">
                            <button onClick={() => setIsModalOpen(false)} className="flex-1 py-5 text-gray-400 font-bold hover:bg-gray-50 rounded-2xl transition-all uppercase text-xs tracking-widest">{lang==='fa'?'انصراف':'Cancel'}</button>
                            <button onClick={handleSaveGoal} disabled={!mainGoalText.trim()} className="flex-[2] py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-2xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95 disabled:opacity-50">{t.save}</button>
                        </div>
                    </div>
                </div>
            )}

            {/* --- DASHBOARD HEADER --- */}
            <div className="bg-white p-10 rounded-[4rem] shadow-2xl border border-gray-100 flex flex-col lg:flex-row justify-between items-center gap-10">
                <div className="flex items-center gap-8">
                    <div className="w-24 h-24 bg-gradient-to-br from-indigo-600 to-blue-700 rounded-[2.5rem] flex items-center justify-center text-white shadow-2xl shadow-indigo-200"><IconTarget className="w-12 h-12" /></div>
                    <div>
                        <h2 className="text-4xl font-black text-gray-900 tracking-tighter mb-2">{t.title}</h2>
                        <div className="flex items-center gap-3">
                            <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">{t.viewMode}</span>
                            <div className="flex bg-gray-100 p-1 rounded-2xl">
                                {['daily', 'weekly', 'monthly', 'yearly'].map(p => (
                                    <button key={p} onClick={() => setActivePeriod(p as any)} className={`px-5 py-2 rounded-xl text-[10px] font-black transition-all ${activePeriod === p ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}>{t[p as keyof typeof t.fa]}</button>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
                <div className="flex items-center gap-10">
                    <div className="text-center"><div className="text-5xl font-black text-indigo-600 leading-none mb-2">{stats.percent}%</div><div className="text-[9px] font-black text-gray-400 uppercase tracking-widest">{t.progress}</div></div>
                    <button onClick={handleExport} disabled={isExporting} className="bg-slate-900 text-white px-8 py-4 rounded-3xl font-black text-xs flex items-center gap-3 hover:bg-black transition-all shadow-2xl active:scale-95 disabled:opacity-50">
                        {isExporting ? '...' : <IconPrinter className="w-5 h-5" />} {t.print}
                    </button>
                </div>
            </div>

            {/* --- STRATEGY GRID (Columns) --- */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-8 items-start">
                {currentUserGoals?.categories.map(cat => (
                    <div key={cat.id} className="flex flex-col gap-6">
                        <div className="px-4 flex items-center justify-between">
                            <h3 className="text-sm font-black text-gray-400 uppercase tracking-[0.2em]">{cat.title}</h3>
                            <div className={`w-2 h-2 rounded-full ${cat.color} animate-pulse`}></div>
                        </div>

                        <div className="space-y-6">
                            {cat.tasks.map(task => (
                                <div key={task.id} className="bg-white rounded-[2.5rem] border border-gray-100 p-8 shadow-xl shadow-gray-200/50 hover:shadow-indigo-100 hover:border-indigo-100 transition-all group/card relative">
                                    <div className="flex items-start gap-5">
                                        <button onClick={() => toggleTaskStatus(cat.id, task.id)} className={`w-8 h-8 rounded-2xl border-2 shrink-0 transition-all flex items-center justify-center ${task.isCompleted ? 'bg-green-600 border-green-600 text-white shadow-lg shadow-green-100' : 'bg-white border-gray-100 group-hover/card:border-indigo-400 text-indigo-50'}`}>
                                            <IconCheck className="w-4 h-4" />
                                        </button>

                                        <div className="flex-grow min-w-0" onClick={() => openGoalModal(cat.id, task)}>
                                            {/* FULL TEXT DISPLAY - NO TRUNCATION */}
                                            <div className={`text-base font-black text-gray-900 leading-relaxed whitespace-pre-wrap cursor-pointer hover:text-indigo-600 transition-colors mb-4 ${task.isCompleted ? 'opacity-40 line-through' : ''}`}>
                                                {task.text}
                                            </div>

                                            {/* Deadline Badge */}
                                            {task.deadline && (
                                                <div className="flex items-center gap-2 mb-4 bg-rose-50 text-rose-600 px-3 py-1 rounded-full w-fit border border-rose-100">
                                                    <IconClock className="w-3 h-3" />
                                                    <span className="text-[10px] font-black dir-ltr">{task.deadline}</span>
                                                </div>
                                            )}

                                            {/* BREAKDOWN PREVIEW */}
                                            {task.subTasks && task.subTasks.length > 0 && (
                                                <div className="space-y-3 pt-4 border-t border-gray-50">
                                                    {task.subTasks.map(st => (
                                                        <div key={st.id} className="flex items-center gap-3 text-[11px] font-bold text-gray-500">
                                                            <div className={`w-1.5 h-1.5 rounded-full ${st.isCompleted ? 'bg-green-500' : 'bg-gray-200'}`}></div>
                                                            <span className={st.isCompleted ? 'line-through' : ''}>{st.text}</span>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    </div>

                                    {/* Quick Actions */}
                                    <div className="absolute top-6 rtl:left-6 ltr:right-6 flex flex-col gap-2 opacity-0 group-hover/card:opacity-100 transition-opacity">
                                        <button onClick={(e) => {e.stopPropagation(); openGoalModal(cat.id, task);}} className="p-2 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all"><IconEdit className="w-4 h-4" /></button>
                                        <button onClick={(e) => {e.stopPropagation(); if(confirm('حذف شود؟')) handleSync(currentUserGoals!.categories.map(c => c.id === cat.id ? {...c, tasks: c.tasks.filter(t=>t.id!==task.id)} : c));}} className="p-2 bg-red-50 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all"><IconTrash className="w-4 h-4" /></button>
                                    </div>
                                </div>
                            ))}

                            {canEdit && (
                                <button 
                                    onClick={() => openGoalModal(cat.id)}
                                    className="w-full py-10 border-2 border-dashed border-gray-200 rounded-[2.5rem] flex flex-col items-center justify-center gap-3 text-gray-300 hover:border-indigo-200 hover:text-indigo-400 hover:bg-indigo-50/20 transition-all group/add"
                                >
                                    <div className="w-12 h-12 rounded-full border-2 border-current flex items-center justify-center group-hover/add:scale-110 transition-transform"><IconPlus className="w-6 h-6" /></div>
                                    <span className="text-[10px] font-black uppercase tracking-widest">{t.addGoal}</span>
                                </button>
                            )}
                        </div>
                    </div>
                ))}
            </div>

            {/* Poster Canvas (Hidden) */}
            <div style={{ position: 'fixed', left: '-9999px', top: 0 }}>
                <div ref={posterRef} className="bg-white p-20 flex flex-col" style={{ width: '1200px', height: '1600px' }}>
                    <div className="border-[20px] border-gray-50 flex-grow p-16 flex flex-col relative overflow-hidden">
                        <div className="flex justify-between items-start mb-20 relative z-10">
                            <div><h1 className="text-7xl font-black text-gray-900 mb-4 tracking-tighter uppercase">{currentUserGoals?.userName}</h1><div className="flex gap-4">{personnel.find(p=>p.id===selectedUserId)?.roles.map(r => <span key={r} className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-xs font-black tracking-widest uppercase">{r}</span>)}</div></div>
                            <div className="text-right"><div className="text-9xl font-black text-indigo-600 leading-none">{stats.percent}%</div><div className="text-sm font-black text-gray-400 tracking-[0.4em] uppercase">{t.progress}</div></div>
                        </div>
                        <div className="bg-slate-900 text-white p-16 rounded-[4rem] mb-20 flex justify-between items-center shadow-2xl">
                            <div className="flex items-center gap-8"><IconShield className="w-16 h-16" /><h2 className="text-4xl font-black uppercase tracking-tight">Strategy Execution Roadmap</h2></div>
                            <div className="text-2xl font-mono font-black opacity-40">{activePeriod.toUpperCase()} / {new Date().getFullYear()}</div>
                        </div>
                        <div className="flex-grow grid grid-cols-2 gap-20">
                            {currentUserGoals?.categories.map(cat => (
                                <div key={cat.id} className="space-y-10">
                                    <div className="border-b-4 border-gray-100 pb-6 flex items-center gap-6"><div className={`w-6 h-6 rounded-full ${cat.color}`}></div><h3 className="text-3xl font-black uppercase tracking-widest text-gray-800">{cat.title}</h3></div>
                                    <div className="space-y-12">
                                        {cat.tasks.filter(t => !t.isCompleted).map(task => (
                                            <div key={task.id} className="flex gap-8">
                                                <div className="w-8 h-8 rounded-full border-4 border-indigo-200 mt-2 shrink-0"></div>
                                                <div className="flex-grow">
                                                    <div className="text-3xl font-bold text-gray-900 leading-snug mb-4">{task.text}</div>
                                                    {task.deadline && <div className="text-lg font-black text-rose-600 mb-4 flex items-center gap-2"><IconClock className="w-5 h-5" /> Deadline: {task.deadline}</div>}
                                                    <div className="space-y-3 pl-10 border-l-4 border-gray-50 py-2">
                                                        {task.subTasks?.map(st => (<div key={st.id} className="text-lg font-bold text-gray-400 flex items-center gap-4"><div className="w-3 h-3 rounded-md bg-gray-200"></div>{st.text}</div>))}
                                                    </div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Personnel, UserGoals, GoalCategory, GoalTask, GoalPeriod, GoalSubTask } from '../types';
import { IconTarget, IconPlus, IconCheck, IconTrash, IconEdit, IconShield, IconPrinter, IconTrophy, IconList, IconStar, IconAward, IconArrowRight, IconClock, IconCalendar } from './Icons';
import { saveUserGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';
import * as htmlToImage from 'html-to-image';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'تجاری و فروش', color: 'bg-indigo-500', type: 'business' as const },
    { id: 'cat2', title: 'توسعه بازار', color: 'bg-emerald-500', type: 'business' as const },
    { id: 'cat3', title: 'فرآیندها', color: 'bg-amber-500', type: 'business' as const },
    { id: 'cat4', title: 'رشد فردی', color: 'bg-rose-500', type: 'personal' as const },
    { id: 'cat5', title: 'سایر اولویت‌ها', color: 'bg-slate-600', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isExporting, setIsExporting] = useState(false);

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [targetCatId, setTargetCatId] = useState<string | null>(null);
    const [editingTaskId, setEditingTaskId] = useState<string | null>(null);
    const [mainGoalText, setMainGoalText] = useState('');
    const [deadline, setDeadline] = useState('');
    const [subTasks, setSubTasks] = useState<GoalSubTask[]>([]);
    const [newSubInput, setNewSubInput] = useState('');

    const posterRef = useRef<HTMLDivElement>(null);
    const canEdit = selectedUserId === currentUser.id || currentUser.username === 'master';

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    const t = {
        fa: {
            title: 'مدیریت اهداف و برنامه‌ریزی',
            daily: 'روزانه', weekly: 'هفتگی', monthly: 'ماهانه', yearly: 'سالانه', five_year: '۵ ساله',
            viewMode: 'بازه زمانی:',
            addGoal: 'هدف جدید',
            progress: 'پیشرفت',
            empty: 'لیست اهداف این دوره خالی است.',
            print: 'خروجی تصویر',
            modalTitle: 'تعریف و خرد کردن هدف',
            mainLabel: 'عنوان یا ماموریت اصلی:',
            subLabel: 'گام‌های اجرایی (Breakdown):',
            deadlineLabel: 'مهلت انجام (Deadline):',
            addSub: 'افزودن گام',
            save: 'ذخیره نهایی',
            restore: 'بازیابی'
        },
        en: {
            title: 'Goals & Strategic Planning',
            daily: 'Daily', weekly: 'Weekly', monthly: 'Monthly', yearly: 'Yearly', five_year: '5-Year',
            viewMode: 'Timeframe:',
            addGoal: 'New Goal',
            progress: 'Progress',
            empty: 'No goals set for this period.',
            print: 'Export Image',
            modalTitle: 'Goal Definition & Breakdown',
            mainLabel: 'Main Mission/Objective:',
            subLabel: 'Action Steps (Breakdown):',
            deadlineLabel: 'Completion Deadline:',
            addSub: 'Add Step',
            save: 'Save Goal',
            restore: 'Restore'
        }
    }[lang];

    const handleSync = (updatedCategories: GoalCategory[]) => {
        if (!currentUserGoals) return;
        const updated = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updated);
        saveUserGoals(updated);
    };

    const openGoalModal = (catId: string, task?: GoalTask) => {
        if (!canEdit) return;
        setTargetCatId(catId);
        if (task) {
            setEditingTaskId(task.id);
            setMainGoalText(task.text);
            setDeadline(task.deadline || '');
            setSubTasks(task.subTasks || []);
        } else {
            setEditingTaskId(null);
            setMainGoalText('');
            setDeadline('');
            setSubTasks([]);
        }
        setIsModalOpen(true);
    };

    const handleSaveGoal = () => {
        if (!mainGoalText.trim() || !currentUserGoals || !targetCatId) return;
        let updated;
        if (editingTaskId) {
            updated = currentUserGoals.categories.map(c => c.id === targetCatId ? { ...c, tasks: c.tasks.map(t => t.id === editingTaskId ? { ...t, text: mainGoalText, deadline, subTasks } : t) } : c);
        } else {
            updated = currentUserGoals.categories.map(c => c.id === targetCatId ? { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: mainGoalText, deadline, isCompleted: false, subTasks }] } : c);
        }
        handleSync(updated);
        setIsModalOpen(false);
    };

    const toggleTaskStatus = (catId: string, taskId: string) => {
        if (!canEdit) return;
        const updated = currentUserGoals!.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, isCompleted: !t.isCompleted, subTasks: t.subTasks?.map(st => ({ ...st, isCompleted: !t.isCompleted })) } : t) } : c);
        handleSync(updated);
    };

    const stats = useMemo(() => {
        if (!currentUserGoals) return { percent: 0 };
        let total = 0, done = 0;
        currentUserGoals.categories.forEach(c => c.tasks.forEach(t => { total++; if (t.isCompleted) done++; }));
        return { percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    if (isLoading) return <div className="p-20 text-center text-indigo-600 font-medium animate-pulse">در حال فراخوانی اطلاعات...</div>;

    return (
        <div className="space-y-8 pb-20 max-w-7xl mx-auto">
            {/* Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4 animate-fade-in" onClick={() => setIsModalOpen(false)}>
                    <div className="bg-white rounded-2xl w-full max-w-2xl shadow-2xl flex flex-col overflow-hidden border border-gray-200" onClick={e => e.stopPropagation()}>
                        <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                            <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
                                <IconTarget className="w-5 h-5 text-indigo-600" />
                                {t.modalTitle}
                            </h3>
                            <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-red-500 transition-colors">✕</button>
                        </div>
                        <div className="p-6 space-y-6 overflow-y-auto max-h-[75vh]">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 mb-2 uppercase tracking-wider">{t.mainLabel}</label>
                                <textarea 
                                    className="w-full p-4 bg-white border border-gray-300 rounded-xl text-sm font-medium text-gray-800 outline-none focus:ring-2 focus:ring-indigo-500 transition-all resize-none"
                                    rows={3}
                                    value={mainGoalText}
                                    onChange={e => setMainGoalText(e.target.value)}
                                    autoFocus
                                />
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div className="bg-gray-50 p-4 rounded-xl border border-gray-200">
                                    <label className="block text-xs font-bold text-gray-500 mb-2 flex items-center gap-1"><IconCalendar className="w-3.5 h-3.5" /> {t.deadlineLabel}</label>
                                    <input type="date" className="w-full bg-white border border-gray-300 rounded-lg px-3 py-2 text-sm outline-none focus:border-indigo-500" value={deadline} onChange={e => setDeadline(e.target.value)} />
                                </div>
                            </div>
                            <div className="bg-indigo-50/30 p-5 rounded-xl border border-indigo-100">
                                <label className="block text-xs font-bold text-indigo-700 mb-3 uppercase tracking-wider">{t.subLabel}</label>
                                <div className="space-y-2 mb-4">
                                    {subTasks.map((st, idx) => (
                                        <div key={st.id} className="flex items-center gap-3 bg-white p-3 rounded-lg border border-gray-200 group">
                                            <span className="text-[10px] font-bold text-gray-400 w-4">{idx + 1}</span>
                                            <input className="flex-grow text-xs font-medium text-gray-700 bg-transparent outline-none" value={st.text} onChange={e => setSubTasks(subTasks.map(s => s.id === st.id ? {...s, text: e.target.value} : s))} />
                                            <button onClick={() => setSubTasks(subTasks.filter(s => s.id !== st.id))} className="text-gray-300 hover:text-red-500 transition-colors"><IconTrash className="w-4 h-4" /></button>
                                        </div>
                                    ))}
                                </div>
                                <div className="flex gap-2">
                                    <input className="flex-grow py-2 px-4 bg-white border border-gray-300 rounded-lg text-xs outline-none focus:border-indigo-500" placeholder="..." value={newSubInput} onChange={e => setNewSubInput(e.target.value)} onKeyDown={e => { if(e.key==='Enter') { e.preventDefault(); if(!newSubInput.trim()) return; setSubTasks([...subTasks, {id: `st-${Date.now()}`, text: newSubInput.trim(), isCompleted: false}]); setNewSubInput(''); } }} />
                                    <button onClick={() => { if(!newSubInput.trim()) return; setSubTasks([...subTasks, {id: `st-${Date.now()}`, text: newSubInput.trim(), isCompleted: false}]); setNewSubInput(''); }} className="bg-indigo-600 text-white px-4 rounded-lg text-xs font-bold hover:bg-indigo-700">{t.addSub}</button>
                                </div>
                            </div>
                        </div>
                        <div className="p-4 border-t border-gray-100 bg-gray-50 flex gap-3">
                            <button onClick={() => setIsModalOpen(false)} className="flex-1 py-2.5 text-gray-600 text-sm font-bold hover:bg-gray-200 rounded-xl transition-colors">{lang==='fa'?'انصراف':'Cancel'}</button>
                            <button onClick={handleSaveGoal} disabled={!mainGoalText.trim()} className="flex-1 py-2.5 bg-indigo-600 text-white text-sm font-bold rounded-xl shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all disabled:opacity-50">{t.save}</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Header */}
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 flex flex-col lg:flex-row justify-between items-center gap-6">
                <div className="flex items-center gap-5">
                    <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center shadow-inner"><IconTarget className="w-8 h-8" /></div>
                    <div>
                        <h2 className="text-xl font-bold text-gray-900">{t.title}</h2>
                        <div className="flex items-center gap-2 mt-1">
                            <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{t.viewMode}</span>
                            <div className="flex bg-gray-100 p-1 rounded-lg">
                                {['daily', 'weekly', 'monthly', 'yearly'].map(p => (
                                    <button key={p} onClick={() => setActivePeriod(p as any)} className={`px-3 py-1 rounded-md text-[10px] font-bold transition-all ${activePeriod === p ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}>{t[p as keyof typeof t.fa]}</button>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
                <div className="flex items-center gap-8">
                    <div className="text-center">
                        <div className="text-2xl font-bold text-indigo-600 leading-none">{stats.percent}%</div>
                        <div className="text-[10px] font-bold text-gray-400 uppercase mt-1">{t.progress}</div>
                    </div>
                    <button onClick={() => { if(posterRef.current) htmlToImage.toPng(posterRef.current).then(u => { const l=document.createElement('a'); l.download='goals.png'; l.href=u; l.click(); }); }} className="text-xs font-bold text-gray-500 bg-gray-50 hover:bg-gray-100 px-4 py-2 rounded-xl flex items-center gap-2 transition-colors border border-gray-200">
                        <IconPrinter className="w-4 h-4" /> {t.print}
                    </button>
                </div>
            </div>

            {/* Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6 items-start">
                {currentUserGoals?.categories.map(cat => (
                    <div key={cat.id} className="flex flex-col gap-4">
                        <div className="px-2 flex items-center justify-between">
                            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest">{cat.title}</h3>
                            <div className={`w-1.5 h-1.5 rounded-full ${cat.color}`}></div>
                        </div>

                        <div className="space-y-4">
                            {cat.tasks.map(task => (
                                <div key={task.id} className="bg-white rounded-xl border border-gray-200 p-5 shadow-sm hover:shadow-md transition-all group relative">
                                    <div className="flex items-start gap-3">
                                        <button onClick={() => toggleTaskStatus(cat.id, task.id)} className={`w-6 h-6 rounded-lg border-2 shrink-0 flex items-center justify-center transition-all ${task.isCompleted ? 'bg-emerald-500 border-emerald-500 text-white shadow-sm shadow-emerald-100' : 'bg-white border-gray-200 hover:border-indigo-400'}`}>
                                            {task.isCompleted && <IconCheck className="w-3 h-3" />}
                                        </button>
                                        <div className="flex-grow min-w-0" onClick={() => openGoalModal(cat.id, task)}>
                                            <div className={`text-sm font-semibold text-gray-800 leading-relaxed cursor-pointer transition-colors ${task.isCompleted ? 'opacity-40 line-through' : 'group-hover:text-indigo-600'}`}>
                                                {task.text}
                                            </div>
                                            {task.deadline && (
                                                <div className="flex items-center gap-1.5 mt-2 text-[10px] font-bold text-rose-500 bg-rose-50 w-fit px-2 py-0.5 rounded border border-rose-100">
                                                    <IconClock className="w-3 h-3" />
                                                    <span className="dir-ltr">{task.deadline}</span>
                                                </div>
                                            )}
                                            {task.subTasks && task.subTasks.length > 0 && (
                                                <div className="mt-3 pt-3 border-t border-gray-50 space-y-2">
                                                    {task.subTasks.map(st => (
                                                        <div key={st.id} className="flex items-center gap-2 text-[10px] font-medium text-gray-400">
                                                            <div className={`w-1.5 h-1.5 rounded-sm ${st.isCompleted ? 'bg-emerald-400' : 'bg-gray-200'}`}></div>
                                                            <span className={st.isCompleted ? 'line-through opacity-60' : ''}>{st.text}</span>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                    <div className="absolute top-2 rtl:left-2 ltr:right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button onClick={(e) => {e.stopPropagation(); openGoalModal(cat.id, task);}} className="p-1.5 text-indigo-400 hover:text-indigo-600 bg-indigo-50 rounded-lg"><IconEdit className="w-3.5 h-3.5" /></button>
                                        <button onClick={(e) => {e.stopPropagation(); if(confirm('حذف شود؟')) handleSync(currentUserGoals!.categories.map(c => c.id === cat.id ? {...c, tasks: c.tasks.filter(t=>t.id!==task.id)} : c));}} className="p-1.5 text-gray-300 hover:text-red-500 bg-gray-50 rounded-lg"><IconTrash className="w-3.5 h-3.5" /></button>
                                    </div>
                                </div>
                            ))}
                            {canEdit && (
                                <button 
                                    onClick={() => openGoalModal(cat.id)}
                                    className="w-full py-4 border-2 border-dashed border-gray-200 rounded-xl flex flex-col items-center justify-center gap-2 text-gray-400 hover:border-indigo-300 hover:text-indigo-500 hover:bg-indigo-50/20 transition-all group/add"
                                >
                                    <IconPlus className="w-5 h-5 group-hover/add:scale-110 transition-transform" />
                                    <span className="text-[10px] font-bold uppercase tracking-wider">{t.addGoal}</span>
                                </button>
                            )}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

