// --- Attendance Functions ---

export const checkIn = async (person: Personnel) => {
    const today = new Date().toISOString().split('T')[0];
    const docId = `${person.id}_${today}`;
    const record: AttendanceRecord = {
        id: docId,
        userId: person.id,
        userName: person.fullName,
        date: today,
        checkIn: new Date().toISOString(),
        activeMinutes: 0,
        status: 'working'
    };
    await setDoc(doc(db, "attendance", docId), sanitizeData(record));
    logSystemAction('OTHER', 'System', 'ثبت ورود پرسنل', person.fullName, person.id);
};

export const checkOut = async (person: Personnel) => {
    const today = new Date().toISOString().split('T')[0];
    const docId = `${person.id}_${today}`;
    await updateDoc(doc(db, "attendance", docId), {
        checkOut: new Date().toISOString(),
        status: 'finished'
    });
    logSystemAction('OTHER', 'System', 'ثبت خروج پرسنل', person.fullName, person.id);
};

export const updateActiveHeartbeat = async (userId: string) => {
    const today = new Date().toISOString().split('T')[0];
    const docId = `${userId}_${today}`;
    const docRef = doc(db, "attendance", docId);
    const snap = await getDoc(docRef);
    if (snap.exists() && snap.data().status === 'working') {
        await updateDoc(docRef, {
            activeMinutes: increment(1) // Heartbeat every 1 min
        });
    }
};

export const subscribeToTodayAttendance = (callback: (records: AttendanceRecord[]) => void) => {
    const today = new Date().toISOString().split('T')[0];
    const q = query(collection(db, "attendance"), where("date", "==", today));
    return onSnapshot(q, (snapshot) => {
        callback(snapshot.docs.map(d => d.data() as AttendanceRecord));
    });
