export const backupSystemData = async () => {
    try {
        const collections = ['tickets', 'customers', 'settings', 'messages', 'tasks', 'meetings', 'kpis', 'custom_forms', 'sales_records', 'reports', 'user_goals', 'objectives', 'attendance', 'leaves'];
