import React, { useState, useEffect } from 'react';
import { Personnel, AttendanceRecord, LeaveRequest } from '../types';
import { IconClock, IconCheck, IconTrash, IconPlus, IconTime, IconCalendar, IconLock, IconRefreshCw, IconActivity, IconAlertTriangle } from './Icons';
import { checkIn, checkOut, subscribeToUserAttendanceHistory, subscribeToUserLeaves, saveLeaveRequest, updateActiveHeartbeat } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  lang: Language;
}

export const AttendanceManager: React.FC<Props> = ({ currentUser, lang }) => {
    const [history, setHistory] = useState<AttendanceRecord[]>([]);
    const [leaves, setLeaves] = useState<LeaveRequest[]>([]);
    const [todayRecord, setTodayRecord] = useState<AttendanceRecord | null>(null);
    const [activeTab, setActiveTab] = useState<'attendance' | 'leaves'>('attendance');
    const [showLeaveModal, setShowLeaveModal] = useState(false);

    // Form for Leave
    const [leaveType, setLeaveType] = useState<'daily' | 'hourly'>('daily');
    const [leaveStart, setLeaveStart] = useState('');
    const [leaveEnd, setLeaveEnd] = useState('');
    const [leaveReason, setLeaveReason] = useState('');

    const isWorking = todayRecord?.status === 'working';

    useEffect(() => {
        const unsubAtt = subscribeToUserAttendanceHistory(currentUser.id, (data) => {
            setHistory(data);
            const todayStr = new Date().toISOString().split('T')[0];
            setTodayRecord(data.find(r => r.date === todayStr) || null);
        });
        const unsubLeaves = subscribeToUserLeaves(currentUser.id, setLeaves);

        // Heartbeat timer while working
        const timer = setInterval(() => {
            if (isWorking) {
                updateActiveHeartbeat(currentUser.id);
            }
        }, 60000); // Check every 1 minute

        return () => {
            unsubAtt();
            unsubLeaves();
            clearInterval(timer);
        };
    }, [currentUser.id, isWorking]);

    const handleCheckIn = async () => {
        if (todayRecord) return;
        await checkIn(currentUser);
    };

    const handleCheckOut = async () => {
        if (!isWorking) return;
        if (window.confirm(lang === 'fa' ? 'آیا قصد خروج نهایی و اتمام کار امروز را دارید؟' : 'Finish your shift for today?')) {
            await checkOut(currentUser);
        }
    };

    const handleSubmitLeave = async (e: React.FormEvent) => {
        e.preventDefault();
        const req: LeaveRequest = {
            id: `leave-${Date.now()}`,
            userId: currentUser.id,
            userName: currentUser.fullName,
            type: leaveType,
            startDate: leaveStart,
            endDate: leaveType === 'daily' ? leaveEnd : leaveStart,
            startTime: leaveType === 'hourly' ? leaveStart : '',
            endTime: leaveType === 'hourly' ? leaveEnd : '',
            reason: leaveReason,
            status: 'pending',
            createdAt: new Date().toISOString()
        };
        await saveLeaveRequest(req);
        setShowLeaveModal(false);
        setLeaveReason('');
    };

    const formatTime = (iso: string) => new Date(iso).toLocaleTimeString(lang === 'fa' ? 'fa-IR' : 'en-US', { hour: '2-digit', minute: '2-digit' });

    const t = {
        fa: {
            header: 'حضور و غیاب و مرخصی',
            todayStatus: 'وضعیت امروز شما',
            checkIn: 'ثبت ورود (شروع کار)',
            checkOut: 'ثبت خروج (پایان کار)',
            working: 'در حال کار...',
            finished: 'پایان کار ثبت شده',
            notStarted: 'هنوز ورود نزده‌اید',
            activeTime: 'مدت فعالیت در نرم‌افزار:',
