    logSystemAction('CREATE', 'CustomForm', `فرم "${form.title}" ایجاد شد`, actorName, form.id);
};

export const updateCustomFormInCloud = async (id: string, updates: Partial<CustomForm>, actorName: string) => {
    await updateDoc(doc(db, "custom_forms", id), sanitizeData(updates));
    logSystemAction('UPDATE', 'CustomForm', `فرم بروزرسانی شد`, actorName, id);
};

export const deleteCustomFormFromCloud = async (id: string, actorName: string) => {
    const ref = doc(db, "custom_forms", id);
    await deleteDoc(ref);
    logSystemAction('DELETE', 'CustomForm', `فرم حذف شد`, actorName, id);
};

export const subscribeToCustomForms = (callback: (forms: CustomForm[]) => void) => {
    const q = query(collection(db, "custom_forms"));
    return onSnapshot(q, (snapshot) => {
        const forms = snapshot.docs.map(d => d.data() as CustomForm);
        callback(forms);
    }, (e) => {});
};

export const saveAppConfigToCloud = async (config: AppConfig) => {
    await setDoc(doc(db, "settings", "appConfig"), sanitizeData(config));
    logSystemAction('UPDATE', 'System', `تنظیمات سیستم تغییر کرد`, 'Admin');
};

export const saveServicesToCloud = async (services: ServiceOption[]) => {
    await setDoc(doc(db, "settings", "services"), { list: sanitizeData(services) });
    logSystemAction('UPDATE', 'System', `لیست خدمات/تعرفه‌ها بروز شد`, 'Admin');
};

export const savePersonnelToCloud = async (personnel: Personnel[]) => {
    const cleanList = personnel.map(p => {
        const cleanDocs = (p.documents || []).map(docItem => {
             const cleanedFiles = cleanFilesForDB([docItem.file]);
             return cleanedFiles.length > 0 ? { ...docItem, file: cleanedFiles[0] } : null;
        }).filter(d => d !== null);
        return { ...p, documents: cleanDocs };
    });
    await setDoc(doc(db, "settings", "personnel"), { list: sanitizeData(cleanList) });
    logSystemAction('UPDATE', 'Personnel', `لیست پرسنل بروزرسانی شد`, 'Admin');
};

export const subscribeToSettings = (
    onConfig: (c: AppConfig) => void,
    onServices: (s: ServiceOption[]) => void,
    onPersonnel: (p: Personnel[]) => void
) => {
    return onSnapshot(collection(db, "settings"), (snap) => {
        snap.docs.forEach(doc => {
            if (doc.id === 'appConfig') onConfig(doc.data() as AppConfig);
            if (doc.id === 'services') onServices(doc.data().list);
            if (doc.id === 'personnel') onPersonnel(doc.data().list);
        });
    }, (error) => {});
};

import React, { useState, useEffect } from 'react';
import { Personnel, AttendanceRecord, LeaveRequest } from '../types';
import { IconClock, IconPlus, IconCheck, IconTrash, IconCalendarClock, IconAlertTriangle } from './Icons';
import { saveAttendanceRecord, updateAttendanceRecord, incrementActiveTime, saveLeaveRequest, subscribeToAttendance, subscribeToLeaves } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  lang: Language;
}

export const AttendanceManager: React.FC<Props> = ({ currentUser, lang }) => {
    const [todayRecord, setTodayRecord] = useState<AttendanceRecord | null>(null);
    const [history, setHistory] = useState<AttendanceRecord[]>([]);
    const [leaves, setLeaves] = useState<LeaveRequest[]>([]);
    const [activeTab, setActiveTab] = useState<'attendance' | 'leave'>('attendance');
    const [showLeaveModal, setShowLeaveModal] = useState(false);

    // Leave Form State
    const [leaveType, setLeaveType] = useState<'daily' | 'hourly'>('daily');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [startTime, setStartTime] = useState('09:00');
    const [endTime, setEndTime] = useState('11:00');
    const [reason, setReason] = useState('');

    useEffect(() => {
        const unsubAtt = subscribeToAttendance((records) => {
            const todayStr = new Date().toISOString().split('T')[0];
            const tr = records.find(r => r.userId === currentUser.id && r.date === todayStr);
            setTodayRecord(tr || null);
            setHistory(records.filter(r => r.userId === currentUser.id));
        });
        const unsubLeaves = subscribeToLeaves((all) => {
            setLeaves(all.filter(l => l.userId === currentUser.id));
        });

        // Heartbeat timer for active usage
        const heartbeat = setInterval(() => {
            if (todayRecord && !todayRecord.checkOut) {
                incrementActiveTime(currentUser.id);
            }
        }, 60000);

        return () => {
            unsubAtt();
            unsubLeaves();
            clearInterval(heartbeat);
        };
    }, [currentUser.id, todayRecord?.id]);

    const handleCheckIn = async () => {
        const today = new Date().toISOString().split('T')[0];
        const record: AttendanceRecord = {
            id: `${currentUser.id}_${today}`,
            userId: currentUser.id,
            userName: currentUser.fullName,
            date: today,
            checkIn: new Date().toISOString(),
            activeMinutes: 0
        };
        await saveAttendanceRecord(record);
    };

    const handleCheckOut = async () => {
        if (!todayRecord) return;
        await updateAttendanceRecord(todayRecord.id, { checkOut: new Date().toISOString() });
    };

    const handleSubmitLeave = async (e: React.FormEvent) => {
        e.preventDefault();
        const request: LeaveRequest = {
            id: `leave-${Date.now()}`,
            userId: currentUser.id,
            userName: currentUser.fullName,
            type: leaveType,
            startDate,
            endDate: leaveType === 'daily' ? endDate : startDate,
            startTime: leaveType === 'hourly' ? startTime : undefined,
            endTime: leaveType === 'hourly' ? endTime : undefined,
            reason,
            status: 'pending',
            createdAt: new Date().toISOString()
        };
        await saveLeaveRequest(request);
        setShowLeaveModal(false);
        setReason('');
    };

    const t = {
        fa: {
            title: 'مدیریت حضور و غیاب و مرخصی',
            checkIn: 'ثبت ورود',
            checkOut: 'ثبت خروج',
            working: 'در حال کار...',
            finished: 'پایان کار ثبت شد',
            presence: 'مدت حضور امروز:',
            active: 'مدت فعالیت در نرم‌افزار:',
            history: 'تاریخچه فعالیت‌های اخیر',
            leave: 'ثبت درخواست مرخصی',
            leaveList: 'لیست مرخصی‌های من',
            reason: 'علت مرخصی',
            submit: 'ثبت درخواست',
            daily: 'روزانه',
            hourly: 'ساعتی',
            date: 'تاریخ',
            from: 'از',
            to: 'تا',
            status: 'وضعیت',
            activeMin: 'دقیقه فعالیت'
        },
        en: {
            title: 'Attendance & Leave Management',
            checkIn: 'Check In',
            checkOut: 'Check Out',
            working: 'Working...',
            finished: 'Shift Finished',
            presence: 'Total Presence:',
            active: 'Active Software Usage:',
            history: 'Recent Activity',
            leave: 'Request Leave',
            leaveList: 'My Leave History',
            reason: 'Reason',
            submit: 'Submit Request',
            daily: 'Daily',
            hourly: 'Hourly',
            date: 'Date',
            from: 'From',
            to: 'To',
            status: 'Status',
            activeMin: 'Active Minutes'
        }
    }[lang];

    const getStatusColor = (s: string) => {
        switch(s) {
            case 'approved': return 'bg-green-100 text-green-700';
            case 'rejected': return 'bg-red-100 text-red-700';
            default: return 'bg-amber-100 text-amber-700';
        }
    };

    return (
        <div className="space-y-6 animate-fade-in">
            {/* Top Widget */}
            <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex flex-col md:flex-row justify-between items-center gap-6">
                <div className="flex items-center gap-4">
                    <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-white shadow-lg ${todayRecord ? (todayRecord.checkOut ? 'bg-gray-400' : 'bg-green-500 animate-pulse') : 'bg-indigo-600'}`}>
                        <IconClock className="w-8 h-8" />
                    </div>
                    <div>
                        <h3 className="font-bold text-gray-800 text-lg">{todayRecord ? (todayRecord.checkOut ? t.finished : t.working) : 'هنوز ورود نزده‌اید'}</h3>
                        {todayRecord && (
                            <div className="text-sm text-gray-500 mt-1">
                                {t.active}: <span className="font-bold text-indigo-600">{todayRecord.activeMinutes} {lang === 'fa' ? 'دقیقه' : 'min'}</span>
                            </div>
                        )}
                    </div>
                </div>
                <div className="flex gap-2">
                    {!todayRecord && (
                        <button onClick={handleCheckIn} className="bg-indigo-600 text-white px-8 py-3 rounded-xl font-bold shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all flex items-center gap-2">
                            <IconPlus className="w-5 h-5" /> {t.checkIn}
                        </button>
                    )}
                    {todayRecord && !todayRecord.checkOut && (
                        <button onClick={handleCheckOut} className="bg-rose-600 text-white px-8 py-3 rounded-xl font-bold shadow-lg shadow-rose-100 hover:bg-rose-700 transition-all flex items-center gap-2">
                            <IconCheck className="w-5 h-5" /> {t.checkOut}
                        </button>
                    )}
                </div>
            </div>

            {/* Tabs */}
            <div className="flex bg-white p-1 rounded-xl border border-gray-100 w-fit">
                <button onClick={() => setActiveTab('attendance')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'attendance' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-50'}`}>{t.history}</button>
                <button onClick={() => setActiveTab('leave')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'leave' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-50'}`}>{t.leaveList}</button>
            </div>

            {activeTab === 'attendance' && (
                <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                    <table className="w-full text-start text-sm">
                        <thead className="bg-gray-50 text-gray-500">
                            <tr>
                                <th className="px-6 py-4">{t.date}</th>
                                <th className="px-6 py-4">{t.checkIn}</th>
                                <th className="px-6 py-4">{t.checkOut}</th>
                                <th className="px-6 py-4">{t.activeMin}</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {history.map(h => (
                                <tr key={h.id} className="hover:bg-gray-50">
                                    <td className="px-6 py-4 font-bold text-gray-700">{h.date}</td>
                                    <td className="px-6 py-4 dir-ltr text-right">{new Date(h.checkIn).toLocaleTimeString()}</td>
                                    <td className="px-6 py-4 dir-ltr text-right">{h.checkOut ? new Date(h.checkOut).toLocaleTimeString() : '-'}</td>
                                    <td className="px-6 py-4 text-indigo-600 font-bold">{h.activeMinutes}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}

            {activeTab === 'leave' && (
                <div className="space-y-4">
                    <div className="flex justify-end">
                        <button onClick={() => setShowLeaveModal(true)} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:bg-indigo-700 flex items-center gap-2">
                            <IconPlus className="w-4 h-4" /> {t.leave}
                        </button>
                    </div>
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                        <table className="w-full text-start text-sm">
                            <thead className="bg-gray-50 text-gray-500">
                                <tr>
                                    <th className="px-6 py-4">{t.daily} / {t.hourly}</th>
                                    <th className="px-6 py-4">{t.date} / بازه</th>
                                    <th className="px-6 py-4">{t.reason}</th>
                                    <th className="px-6 py-4">{t.status}</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {leaves.map(l => (
                                    <tr key={l.id}>
                                        <td className="px-6 py-4 font-bold">{l.type === 'daily' ? t.daily : t.hourly}</td>
                                        <td className="px-6 py-4 dir-ltr text-right">
                                            {l.type === 'daily' ? `${l.startDate} ~ ${l.endDate}` : `${l.startDate} (${l.startTime}-${l.endTime})`}
                                        </td>
                                        <td className="px-6 py-4 text-gray-500 truncate max-w-xs">{l.reason}</td>
                                        <td className="px-6 py-4">
                                            <span className={`px-2 py-1 rounded text-[10px] font-bold ${getStatusColor(l.status)}`}>{l.status}</span>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {showLeaveModal && (
                <div className="fixed inset-0 z-[120] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
                    <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl p-6 animate-fade-in">
                        <h3 className="text-xl font-bold text-gray-800 mb-6 flex items-center gap-2">
                            <IconCalendarClock className="w-6 h-6 text-indigo-600" /> {t.leave}
                        </h3>
                        <form onSubmit={handleSubmitLeave} className="space-y-4">
                            <div className="flex bg-gray-100 p-1 rounded-xl">
                                <button type="button" onClick={() => setLeaveType('daily')} className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${leaveType === 'daily' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>{t.daily}</button>
                                <button type="button" onClick={() => setLeaveType('hourly')} className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${leaveType === 'hourly' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>{t.hourly}</button>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-bold text-gray-500 mb-1">{t.date} {t.from}</label>
                                    <input type="date" required className="w-full border rounded-lg p-2 text-sm" value={startDate} onChange={e => setStartDate(e.target.value)} />
                                </div>
                                {leaveType === 'daily' ? (
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-1">{t.date} {t.to}</label>
                                        <input type="date" required className="w-full border rounded-lg p-2 text-sm" value={endDate} onChange={e => setEndDate(e.target.value)} />
                                    </div>
                                ) : (
                                    <div className="grid grid-cols-2 gap-2">
                                        <div>
                                            <label className="block text-xs font-bold text-gray-500 mb-1">{t.from}</label>
                                            <input type="time" required className="w-full border rounded-lg p-2 text-sm" value={startTime} onChange={e => setStartTime(e.target.value)} />
                                        </div>
                                        <div>
                                            <label className="block text-xs font-bold text-gray-500 mb-1">{t.to}</label>
                                            <input type="time" required className="w-full border rounded-lg p-2 text-sm" value={endTime} onChange={e => setEndTime(e.target.value)} />
                                        </div>
                                    </div>
                                )}
                            </div>

                            <div>
                                <label className="block text-xs font-bold text-gray-500 mb-1">{t.reason}</label>
                                <textarea required rows={3} className="w-full border rounded-lg p-3 text-sm outline-none focus:ring-2 focus:ring-indigo-500" value={reason} onChange={e => setReason(e.target.value)} />
                            </div>

                            <div className="flex gap-3 pt-4">
                                <button type="button" onClick={() => setShowLeaveModal(false)} className="flex-1 py-3 text-gray-600 font-bold hover:bg-gray-50 rounded-xl transition-colors">{lang === 'fa' ? 'انصراف' : 'Cancel'}</button>
                                <button type="submit" className="flex-1 py-3 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-200">{t.submit}</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

