  const ITEMS_PER_PAGE = 10;

  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);

  // Attendance & Leaves Dashboard State
  const [allAttendance, setAllAttendance] = useState<AttendanceRecord[]>([]);
  const [allLeaves, setAllLeaves] = useState<LeaveRequest[]>([]);

  useEffect(() => {
    if (isMaster || isAdmin) {
        const unsubAtt = subscribeToAttendance(setAllAttendance);
        const unsubLeaves = subscribeToLeaves(setAllLeaves);
        return () => { unsubAtt(); unsubLeaves(); };
    }
  }, [isMaster, isAdmin]);

  const handleApproveLeave = async (id: string, status: 'approved' | 'rejected') => {
      await updateLeaveStatus(id, status, currentUser.fullName);
  };

  const t = {
      fa: {
          attendanceTab: 'حضور و غیاب',
          attendanceTitle: 'داشبورد کنترل حضور و غیاب پرسنل',
          pendingLeaves: 'درخواست‌های مرخصی منتظر تایید',
          staffStatus: 'وضعیت فعالیت آنلاین پرسنل (امروز)',
          approve: 'تایید',
          reject: 'رد',
          date: 'تاریخ',
          user: 'کاربر',
          activeMin: 'فعالیت مفید (دقیقه)',
          status: 'وضعیت',
          online: 'آنلاین (در حال کار)',
          offline: 'آفلاین',
          noPending: 'درخواست جدیدی وجود ندارد.'
      },
      en: {
          attendanceTab: 'Attendance',
          attendanceTitle: 'Staff Attendance Control Panel',
          pendingLeaves: 'Pending Leave Requests',
          staffStatus: 'Today\'s Live Activity Status',
          approve: 'Approve',
          reject: 'Reject',
          date: 'Date',
          user: 'User',
          activeMin: 'Active Min',
          status: 'Status',
          online: 'Online',
          offline: 'Offline',
          noPending: 'No pending requests.'
      }
  }[lang];

  return (
    <div className="flex flex-col md:flex-row gap-6 min-h-[calc(100vh-100px)]">
