// --- Financial Expense Functions ---

export const saveExpense = async (expense: Expense) => {
    await setDoc(doc(db, "expenses", expense.id), sanitizeData(expense));
    logSystemAction('CREATE', 'Expense', `هزینه ثبت شد: ${expense.title}`, expense.recordedBy, expense.id);
};

export const deleteExpense = async (id: string, actorName: string) => {
    await deleteDoc(doc(db, "expenses", id));
    logSystemAction('DELETE', 'Expense', `حذف رکورد هزینه`, actorName, id);
};

export const subscribeToExpenses = (callback: (expenses: Expense[]) => void) => {
    const q = query(collection(db, "expenses"), orderBy("date", "desc"));
    return onSnapshot(q, (snapshot) => {
        callback(snapshot.docs.map(d => d.data() as Expense));
    });
};

// --- Attendance Functions ---

export const saveAttendanceRecord = async (record: AttendanceRecord) => {
    await setDoc(doc(db, "attendance", record.id), sanitizeData(record));
};

export const updateAttendanceRecord = async (id: string, updates: Partial<AttendanceRecord>) => {
    await updateDoc(doc(db, "attendance", id), sanitizeData(updates));
};

export const incrementActiveTime = async (userId: string) => {
    const today = new Date().toISOString().split('T')[0];
    const docId = `${userId}_${today}`;
    const docRef = doc(db, "attendance", docId);
    const snap = await getDoc(docRef);
    if (snap.exists()) {
        await updateDoc(docRef, { activeMinutes: increment(1) });
    }
