export const backupSystemData = async () => {
    try {
        const collections = ['tickets', 'customers', 'settings', 'messages', 'tasks', 'meetings', 'kpis', 'custom_forms', 'sales_records', 'reports', 'user_goals', 'objectives', 'attendance', 'leaves', 'expenses'];
        const data: any = {};
        for (const col of collections) {
            const snap = await getDocs(collection(db, col));
            data[col] = snap.docs.map(d => d.data());
        }
        const safeData = sanitizeData(data);
        const blob = new Blob([JSON.stringify(safeData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `CRM_Full_Backup_${new Date().toISOString().split('T')[0]}.json`;
        a.click();
        return true;
    } catch (e) {
        return false;
    }
};

